insert into public.questions
(book,book_name,chapter,question,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,hint,source_type,order_index) values
('oseias','Oséias',1,'Qual é o nome do profeta que recebeu de Deus a ordem de se casar com uma mulher de prostituição?','facil','Miquéias','Amós','Oséias','Joel','C','Oséias 1:2 identifica o próprio profeta como aquele que recebeu essa ordem.','O nome do livro é também o nome do profeta.','texto_biblico',1),
('oseias','Oséias',11,'Em Oséias 11, como Deus descreve seu relacionamento com Israel?','facil','Como um rei estrangeiro','Como um guerreiro derrotado','Como um comerciante','Como um pai que ensinou seu filho a andar','D','Oséias 11:1-3 usa a imagem de Deus ensinando Efraim a andar e tomando-o nos braços.','A imagem é de cuidado paternal.','texto_biblico',2),
('oseias','Oséias',6,'O que Oséias 6:6 diz que Deus deseja mais do que sacrifícios?','medio','Construções','Conhecimento de Deus','Vitórias militares','Riquezas','B','Oséias 6:6 afirma que Deus deseja misericórdia e conhecimento de Deus mais do que holocaustos e sacrifícios.','A resposta envolve conhecer a Deus.','texto_biblico',3),
('oseias','Oséias',14,'Qual é o convite final do livro de Oséias?','medio','Escolher um novo rei','Construir um novo templo','Voltar ao Senhor','Fugir para o Egito','C','Oséias 14:1 chama Israel a voltar ao Senhor, pois tropeçou em sua iniquidade.','O capítulo final começa com um chamado de retorno.','texto_biblico',4),
('oseias','Oséias',2,'No simbolismo de Oséias 2, o que representa a infidelidade de Israel?','dificil','A construção do templo','A idolatria e a ruptura da aliança com Deus','A invasão da Assíria apenas','A divisão das tribos no deserto','B','Oséias usa a imagem conjugal para denunciar a infidelidade espiritual de Israel, associada à idolatria.','A metáfora central é a de um casamento rompido.','texto_biblico',5),
('oseias','Oséias',3,'O que Oséias fez para readquirir sua esposa, ilustrando o amor redentor de Deus?','facil','Pagou com prata e cevada','Foi a um tribunal romano','Pediu ajuda ao rei da Assíria','Construiu um novo templo','A','Oséias 3:2 relata que o profeta comprou sua esposa por quinze moedas de prata e certa quantidade de cevada, simbolizando a redenção de Israel.','O preço envolve dinheiro e um grão.','texto_biblico',6),
('oseias','Oséias',4,'Qual acusação abre a controvérsia de Deus com Israel em Oséias 4?','facil','Não há conhecimento de Deus na terra','O rei foi deposto','O templo foi destruído','O povo é rico demais','A','Oséias 4:1 acusa a terra de faltar verdade, misericórdia e conhecimento de Deus.','É uma falta de relacionamento com Deus.','texto_biblico',7),
('oseias','Oséias',13,'Qual pergunta desafiadora sobre a morte aparece em Oséias 13:14?','medio','Quem construirá o templo?','Quando virá o novo rei?','Onde está a arca da aliança?','Onde está, ó morte, o teu aguilhão?','D','Oséias 13:14 desafia a morte e o Seol, texto depois citado em 1 Coríntios 15.','É citado no Novo Testamento sobre a ressurreição.','texto_biblico',8),
('oseias','Oséias',10,'O que Oséias 10:12 convida o povo a semear?','medio','Medo','Discórdia','Ouro','Justiça','D','Oséias 10:12 exorta: semeai para vós a justiça e colhei segundo a bondade.','É um chamado agrícola com sentido moral.','texto_biblico',9),
('oseias','Oséias',5,'Em Oséias 5:15, o que Deus diz que fará até que o povo reconheça sua culpa?','dificil','Voltará ao seu lugar','Abandonará os profetas','Enviará outro dilúvio','Destruirá o mundo','A','Oséias 5:15 apresenta Deus retirando-se até que o povo, em angústia, busque a sua face.','Deus se retira temporariamente.','texto_biblico',10),
('oseias','Oséias',1,'Qual era o nome da esposa que Oséias recebeu por ordem de Deus?','facil','Rute','Gômer','Ester','Dalila','B','Oséias 1:3 identifica Gômer, filha de Diblaim, como a mulher que Oséias tomou por esposa.','É o mesmo nome repetido no início do capítulo 1.','texto_biblico',11),
('oseias','Oséias',1,'Que nome Deus mandou dar ao primeiro filho de Oséias e Gômer?','facil','Emanuel','Jezreel','Absalão','Eliseu','B','Oséias 1:4 registra a ordem de Deus para chamar o menino de Jezreel, ligado ao julgamento sobre a casa de Jeú.','É também o nome de um vale importante na história de Israel.','texto_biblico',12),
('oseias','Oséias',1,'Qual o significado do nome dado à filha de Oséias em Oséias 1:6?','facil','"Não compadecida" (Lo-Ruama)','"Bem-amada"','"Alegria completa"','"Fiel para sempre"','A','Oséias 1:6 explica que o nome Lo-Ruama significa que Deus não teria mais compaixão da casa de Israel.','É um nome de julgamento, oposto de misericórdia.','texto_biblico',13),
('oseias','Oséias',1,'O que significa o nome do segundo filho de Oséias, Lo-Ami?','facil','"Herdeiro do reino"','"Filho da promessa"','"Não é meu povo"','"Amado de Deus"','C','Oséias 1:9 explica que o nome Lo-Ami anuncia que Israel deixaria de ser considerado povo de Deus.','É o terceiro e mais duro dos três nomes simbólicos.','texto_biblico',14),
('oseias','Oséias',2,'Segundo Oséias 2:14, o que Deus promete fazer com Israel no deserto?','facil','Destruir todas as suas cidades','Abandoná-la definitivamente','Atraí-la e falar ao seu coração','Enviá-la para o exílio permanente','C','Apesar do julgamento, Oséias 2:14 mostra Deus prometendo atrair Israel ao deserto para renovar o relacionamento.','É uma imagem de reconquista amorosa, como um noivado.','texto_biblico',15),
('oseias','Oséias',3,'Por quanto Oséias comprou de volta sua esposa, segundo Oséias 3:2?','facil','Um rebanho de ovelhas','Cem moedas de ouro','Quinze siclos de prata e cevada','Trinta siclos de prata','C','Oséias 3:2 relata que ele a comprou por quinze siclos de prata e um jeito e meio de cevada.','É um preço modesto, mostrando o estado de degradação da mulher.','texto_biblico',16),
('oseias','Oséias',4,'Segundo Oséias 4:6, por que o povo de Deus perece?','facil','Por falta de exércitos','Por falta de chuva','Por causa de uma peste','Por falta de conhecimento','D','Oséias 4:6 declara: "O meu povo foi destruído porque lhe faltou o conhecimento".','É uma das frases mais citadas do livro.','texto_biblico',17),
('oseias','Oséias',6,'Segundo Oséias 6:2, depois de quantos dias o povo seria ressuscitado?','facil','Ao terceiro dia','Depois de quarenta dias','Depois de sete anos','No mesmo dia','A','Oséias 6:2 fala em ser vivificado depois de dois dias e ressuscitado ao terceiro dia, texto lido como figura profética.','É um número associado depois a outro evento bíblico central.','texto_biblico',18),
('oseias','Oséias',7,'A que Efraim é comparado em Oséias 7:8, por se misturar com os povos?','facil','A uma rocha firme','A uma árvore frondosa','A um leão faminto','A um bolo que não foi virado','D','Oséias 7:8 usa a imagem de um bolo (pão) que não foi virado no forno, queimado de um lado e cru do outro.','É uma imagem de algo malfeito, incompleto.','texto_biblico',19),
('oseias','Oséias',8,'Segundo Oséias 8:7, o que Israel vai colher por ter semeado vento?','facil','Trigo em abundância','Tempestade','Paz duradoura','Um novo rei','B','Oséias 8:7 registra a célebre frase "porque semearam vento, colherão tempestade".','É uma frase que virou expressão popular sobre consequências.','texto_biblico',20),
('oseias','Oséias',9,'Como Oséias 9:7 descreve os dias que estavam chegando sobre Israel?','facil','Dias de punição e retribuição','Dias de festa e fartura','Dias de paz com a Assíria','Dias de reconstrução do templo','A','Oséias 9:7 anuncia que chegaram os dias da punição e da retribuição por causa da grande maldade do povo.','É um anúncio de julgamento iminente.','texto_biblico',21),
('oseias','Oséias',12,'Segundo Oséias 12:3-4, o que o patriarca Jacó fez com o anjo, relembrado como exemplo?','facil','Construiu um altar em sua honra','Lutou com ele e chorou, suplicando favor','Fugiu apavorado dele','Recusou-se a falar com ele','B','Oséias 12:3-4 relembra a luta de Jacó com o anjo em Betel, quando chorou e suplicou o favor de Deus.','É uma referência ao episódio de Gênesis 32.','texto_biblico',22),
('oseias','Oséias',2,'Segundo Oséias 2:17, o que Deus promete tirar da boca de Israel?','medio','As leis de Moisés','Os nomes dos baalins','O nome do rei','As bênçãos do templo','B','Oséias 2:17 anuncia que Deus tiraria da boca dela os nomes dos baalins, para que não fossem mais lembrados.','Trata-se dos ídolos cananeus adorados por Israel.','texto_biblico',23),
('oseias','Oséias',4,'O que Deus responde aos sacerdotes por terem rejeitado o conhecimento, segundo Oséias 4:6?','medio','Que também os rejeitaria do sacerdócio','Que dobraria seus salários','Que os enviaria à Babilônia','Que perdoaria seus filhos','A','Oséias 4:6 conclui: "Visto que rejeitaste o conhecimento, também eu te rejeitarei, para que não sejas sacerdote diante de mim".','É uma resposta direta contra a liderança religiosa.','texto_biblico',24),
('oseias','Oséias',5,'Segundo Oséias 5:11, por que Efraim está oprimido e quebrantado no juízo?','medio','Porque perdeu uma guerra contra Judá','Porque recusou pagar tributo à Assíria','Porque quis seguir mandamentos humanos','Porque desprezou os profetas apenas uma vez','C','Oséias 5:11 diz que Efraim está oprimido e quebrantado no juízo, porque quis andar após o mandamento (vaidade humana).','O contraste é obedecer ordens humanas em vez da lei de Deus.','texto_biblico',25),
('oseias','Oséias',8,'Segundo Oséias 8:4, qual foi o erro de Israel ao constituir reis e príncipes?','medio','Nunca tiveram um rei','Escolheram apenas estrangeiros','Fizeram isso sem consultar a Deus','Consultaram somente os sacerdotes','C','Oséias 8:4 acusa: "Eles fizeram reis, mas não por mim; constituíram príncipes, mas eu não o soube".','É uma crítica à independência política de Israel em relação a Deus.','texto_biblico',26),
('oseias','Oséias',9,'A que período de pecado antigo Oséias 9:9 compara a corrupção do seu tempo?','medio','Aos dias de Salomão','Aos dias do dilúvio','Aos dias de Gibeá','Aos dias do êxodo do Egito','C','Oséias 9:9 afirma que se corromperam profundamente, "como nos dias de Gibeá", episódio vergonhoso narrado em Juízes 19-20.','É uma referência a um crime grave da época dos juízes.','texto_biblico',27),
('oseias','Oséias',10,'Como Oséias 10:1 descreve Israel logo no início do capítulo?','medio','Como um deserto árido e estéril','Como uma vide luxuriante que dá fruto para si mesma','Como um exército poderoso e fiel','Como uma cidade sem muros','B','Oséias 10:1 compara Israel a uma vide exuberante, mas que usa sua prosperidade para multiplicar altares e ídolos.','É uma imagem agrícola sobre prosperidade mal utilizada.','texto_biblico',28),
('oseias','Oséias',11,'Segundo Oséias 11:2, o que aconteceu quanto mais os profetas chamavam Israel?','medio','Mais alianças com Judá eram feitas','Mais eles se aproximavam do templo','Mais reis justos surgiam','Mais eles se afastavam, sacrificando aos baalins','D','Oséias 11:2 lamenta que quanto mais Deus os chamava, mais eles se apartavam para sacrificar a Baal e queimar incenso a imagens.','É a continuação da imagem paterna do capítulo 11.','texto_biblico',29),
('oseias','Oséias',12,'Segundo Oséias 12:1, com o que Efraim é comparado por buscar alianças contraditórias?','medio','Alguém que planta uma vinha próspera','Alguém que se apascenta de vento e persegue o vento leste','Um pastor fiel que cuida do rebanho','Um rei sábio e justo','B','Oséias 12:1 diz que Efraim se apascenta de vento e persegue o vento leste, fazendo alianças com Assíria e Egito ao mesmo tempo.','É uma crítica à política externa instável de Israel.','texto_biblico',30),
('oseias','Oséias',13,'Segundo Oséias 13:4, desde onde Deus se identifica como o único Deus de Israel?','medio','Desde a terra do Egito','Desde a fundação de Jerusalém','Desde o reinado de Davi','Desde a construção do templo','A','Oséias 13:4 declara: "Eu sou o Senhor teu Deus desde a terra do Egito; portanto não conhecerás outro Deus além de mim".','É uma referência direta ao êxodo.','texto_biblico',31),
('oseias','Oséias',13,'A que animal feroz Deus se compara em relação a Efraim, segundo Oséias 13:7?','medio','A um cordeiro','A uma pomba','A um leão','A um boi manso','C','Oséias 13:7 afirma: "Portanto serei para eles como leão; como leopardo, os espiarei no caminho".','É uma imagem de julgamento súbito e implacável.','texto_biblico',32),
('oseias','Oséias',14,'Segundo Oséias 14:4, o que Deus promete fazer com a rebeldia de Israel?','medio','Registrá-la em um livro de acusação','Ignorá-la para sempre','Curá-la e amá-los voluntariamente','Transferi-la para outra nação','C','Oséias 14:4 promete: "Eu sararei a sua rebeldia, eu os amarei voluntariamente", encerrando o livro com esperança.','É a resposta de graça ao convite ao arrependimento.','texto_biblico',33),
('oseias','Oséias',6,'Segundo Oséias 6:4, o que Deus compara ao amor de Efraim e Judá, por ser passageiro?','medio','A um rio que nunca seca','A uma rocha inabalável','A uma nuvem da manhã e ao orvalho que cedo se desfaz','A uma árvore de raízes profundas','C','Oséias 6:4 lamenta que a fidelidade deles é como a nuvem da manhã e como o orvalho que cedo se vai.','É uma crítica à inconstância espiritual do povo.','texto_biblico',34),
('oseias','Oséias',1,'Segundo o cabeçalho de Oséias 1:1, durante o reinado de quais reis de Judá o profeta atuou?','dificil','Davi, Salomão e Roboão','Uzias, Jotão, Acaz e Ezequias','Saul, Davi e Salomão','Ezequias, Manassés e Josias','B','Oséias 1:1 situa o ministério do profeta nos reinados de Uzias, Jotão, Acaz e Ezequias, reis de Judá, e de Jeroboão II em Israel.','É a mesma lista de reis de Judá que aparece também em Isaías 1:1.','texto_biblico',35),
('oseias','Oséias',2,'Segundo Oséias 2:18, além do povo, com quem mais Deus promete fazer aliança de paz?','dificil','Com os reis vizinhos de Judá','Somente com os sacerdotes de Israel','Com os animais do campo, as aves do céu e os répteis','Com os anjos do céu','C','Oséias 2:18 amplia a promessa de restauração a uma aliança cósmica com os animais do campo, aves do céu e répteis da terra.','É uma imagem de paz que envolve toda a criação.','texto_biblico',36),
('oseias','Oséias',6,'Segundo Oséias 6:9, a que grupo os sacerdotes são comparados por matarem no caminho a Siquém?','dificil','A juízes justos que aplicam a lei','A pastores fiéis que guardam ovelhas','A uma quadrilha de salteadores que espreita um homem','A profetas que anunciam a paz','C','Oséias 6:9 denuncia que, como bando de salteadores espreita alguém, assim os sacerdotes se ajuntam para matar no caminho de Siquém.','É uma das acusações mais duras contra a classe sacerdotal no livro.','texto_biblico',37),
('oseias','Oséias',9,'Segundo Oséias 9:11, o que acontecerá à glória de Efraim, comparada a uma ave?','dificil','Permanecerá intacta por gerações','Se tornará eterna e visível a todos','Será entregue aos sacerdotes','Fugirá voando para longe','D','Oséias 9:11 declara que a glória de Efraim fugirá como ave, com o fim da fecundidade, da gravidez e da concepção.','É uma imagem de perda repentina e completa.','texto_biblico',38),
('oseias','Oséias',11,'Segundo Oséias 11:9, por que Deus decide não executar o furor da sua ira contra Efraim?','dificil','Porque um novo rei justo havia subido ao trono','Porque Efraim já havia se arrependido totalmente','Porque é Deus, e não homem, o Santo no meio de Israel','Porque Judá intercedeu formalmente por Efraim','C','Oséias 11:9 revela a razão da misericórdia divina: "Porque eu sou Deus e não homem, o Santo no meio de ti".','É um dos versos mais teologicamente profundos do livro sobre a natureza de Deus.','texto_biblico',39),
('oseias','Oséias',13,'Segundo Oséias 13:2, o que o povo passou a fazer cada vez mais, mesmo depois de tantas advertências?','dificil','Abandonar totalmente os altares pagãos','Reconstruir o templo em Jerusalém','Consultar apenas profetas verdadeiros','Fundir imagens de prata e beijar bezerros de ídolo','D','Oséias 13:2 descreve o povo fazendo imagens de fundição com sua prata, ídolos segundo a sua compreensão, e até beijando bezerros.','É uma imagem chocante de devoção idólatra ao bezerro de ouro.','texto_biblico',40),
('joel','Joel',1,'Qual desastre ocupa grande parte do capítulo 1 de Joel?','facil','Um terremoto','Uma invasão de gafanhotos','Uma enchente','Uma seca no Egito','B','Joel 1 descreve uma devastação causada por gafanhotos e convoca o povo ao lamento e ao jejum.','O desastre é descrito como uma praga de insetos.','texto_biblico',41),
('joel','Joel',2,'O que Deus promete derramar sobre toda carne em Joel 2?','facil','O seu ouro','O seu templo','A sua espada','O seu Espírito','D','Joel 2:28 anuncia: Deus derramará o seu Espírito sobre toda carne.','É a promessa associada a filhos e filhas profetizando.','texto_biblico',42),
('joel','Joel',2,'Qual atitude Joel 2:12-13 pede ao povo?','medio','Construir uma fortaleza','Migrar para outra terra','Parar de orar','Voltar ao Senhor de todo o coração','D','Joel chama o povo a voltar ao Senhor com jejum, choro e pranto, rasgando o coração.','O chamado é interior, não apenas externo.','texto_biblico',43),
('joel','Joel',3,'Segundo Joel 3, onde as nações são reunidas para julgamento?','medio','Monte Carmelo','Vale de Elá','Vale de Josafá','Deserto do Sinai','C','Joel 3:2 e 12 menciona o vale de Josafá como lugar do julgamento das nações.','O nome significa associado ao julgamento do Senhor.','texto_biblico',44),
('joel','Joel',2,'Qual fenômeno é citado junto à promessa do Espírito e aos sinais no céu?','dificil','A chuva cessará por quarenta anos','As montanhas desaparecerão','O mar se tornará doce','O sol se converterá em trevas e a lua em sangue','D','Joel 2:30-31 menciona sinais no céu, incluindo sol em trevas e lua em sangue antes do grande e terrível dia do Senhor.','São sinais celestes.','texto_biblico',45),
('joel','Joel',1,'Quem Joel convoca a despertar e chorar por causa da devastação em Joel 1:5?','facil','Os exércitos vizinhos','Os sacerdotes apenas','Os bêbados','Os reis estrangeiros','C','Joel 1:5 chama os bêbados a despertarem e chorarem pela perda do vinho novo.','Estão associados à bebida.','texto_biblico',46),
('joel','Joel',2,'O que o povo deve tocar em Sião para anunciar o perigo em Joel 2:1?','facil','A trombeta','Os címbalos','O tambor','A harpa','A','Joel 2:1 ordena tocar a trombeta em Sião para soar o alarme.','É um instrumento de alerta.','texto_biblico',47),
('joel','Joel',2,'O que Deus promete restituir em Joel 2:25?','medio','Os anos que o gafanhoto comeu','Os tronos derrubados','As tribos perdidas','As muralhas da cidade','A','Joel 2:25 promete restituir os anos devorados pelo gafanhoto, símbolo de restauração após o juízo.','É uma promessa de compensação pelo tempo perdido.','texto_biblico',48),
('joel','Joel',3,'Em Joel 3:10, o que as nações são chamadas a transformar em espadas?','medio','Suas tendas','As relhas dos seus arados','Seus rebanhos','Seus templos','B','Joel 3:10 inverte a imagem de paz (vista em Miquéias e Isaías), convocando as nações à guerra: batei as relhas em espadas.','É o oposto da imagem de paz de Miquéias 4:3.','texto_biblico',49),
('joel','Joel',2,'Segundo Joel 2:32, o que acontecerá a todo aquele que invocar o nome do Senhor?','dificil','Será salvo','Perderá seus bens','Será exilado','Será esquecido','A','Joel 2:32 promete que todo aquele que invocar o nome do Senhor será salvo, texto citado em Atos 2 e Romanos 10.','É citado por Pedro no dia de Pentecostes.','texto_biblico',50),
('joel','Joel',1,'Segundo Joel 1:4, quantos tipos/estágios de gafanhoto são mencionados na devastação?','facil','Nenhum, eram apenas gumes de espada','Dois (grande e pequeno)','Um exército só de gafanhotos adultos','Quatro (cortador, voador, saltador e devorador)','D','Joel 1:4 descreve a devastação em etapas: o que o gafanhoto cortador deixou, o voador comeu, e assim sucessivamente.','É uma sequência de pragas que devoraram tudo por completo.','texto_biblico',51),
('joel','Joel',1,'Segundo Joel 1:11, quem é convocado a lamentar pela perda do trigo e da cevada?','facil','Os lavradores e os vinhateiros','Somente os sacerdotes','Os reis vizinhos','Apenas as crianças','A','Joel 1:11 chama lavradores e vinhateiros a se envergonharem e uivarem pela perda da colheita de trigo e cevada.','São os responsáveis diretos pelo campo e pela vinha.','texto_biblico',52),
('joel','Joel',1,'O que aconteceu com a vide e a figueira, segundo Joel 1:12?','facil','Deram fruto em dobro','A vide se secou e a figueira se murchou','Foram plantadas de novo','Ficaram intactas apesar da praga','B','Joel 1:12 relata que a vide se secou, a figueira se murchou, e todas as árvores do campo pereceram.','É a continuação da descrição da devastação agrícola.','texto_biblico',53),
('joel','Joel',1,'Segundo Joel 1:13-14, o que os sacerdotes deveriam fazer diante da crise?','facil','Organizar uma grande festa','Vestir-se de saco e convocar um jejum solene','Fugir para outra cidade','Silenciar e nada fazer','B','Joel 1:13-14 convoca os sacerdotes a vestirem saco, lamentarem e proclamarem um jejum santificado, reunindo o povo.','É um chamado litúrgico de arrependimento coletivo.','texto_biblico',54),
('joel','Joel',2,'A que Joel 2:4 compara o aspecto do exército de gafanhotos?','facil','A nuvens paradas no céu','A pássaros voando em bando','A peixes nadando em cardume','A cavalos, correndo como cavaleiros','D','Joel 2:4 diz que o aspecto do exército de gafanhotos é como o aspecto de cavalos, e correm como cavaleiros.','É uma comparação militar para descrever a velocidade e força da praga.','texto_biblico',55),
('joel','Joel',2,'Segundo Joel 2:3, como fica a terra depois da passagem do exército de gafanhotos?','facil','Coberta de flores novas','Mais fértil do que antes','Um deserto assolado, depois de ter sido como o jardim do Éden','Exatamente igual a antes','C','Joel 2:3 contrasta: diante dele a terra é como o jardim do Éden, e atrás dele um deserto assolado.','É uma das imagens mais fortes de destruição total do livro.','texto_biblico',56),
('joel','Joel',2,'Como Joel 2:13 descreve o caráter de Deus, motivando o arrependimento do povo?','facil','Indiferente ao sofrimento humano','Distante, frio e inacessível','Vingativo e impaciente','Gracioso, compassivo, tardio em irar-se e grande em benignidade','D','Joel 2:13 descreve Deus como gracioso e compassivo, tardio em irar-se, e grande em benignidade, arrependendo-se do mal.','É uma descrição clássica do caráter de Deus repetida em vários livros do Antigo Testamento.','texto_biblico',57),
('joel','Joel',2,'Segundo Joel 2:16, quem além dos anciãos e crianças é convocado para a assembleia de jejum?','facil','O noivo e a noiva, mesmo em seus aposentos','Somente os soldados','Apenas os estrangeiros residentes','Somente os profetas','A','Joel 2:16 convoca até o noivo a sair do seu aposento, e a noiva do seu tálamo, mostrando a urgência da convocação geral.','Mostra que nem os recém-casados ficariam de fora da reunião.','texto_biblico',58),
('joel','Joel',2,'Segundo Joel 2:18, qual foi a reação de Deus depois do arrependimento do povo?','facil','Teve zelo pela sua terra e se apiedou do povo','Permaneceu irredutível em sua ira','Enviou um novo exército inimigo','Exigiu mais sacrifícios antes de responder','A','Joel 2:18 marca a virada do livro: o Senhor teve zelo da sua terra e se apiedou do seu povo.','É o ponto de virada entre o lamento e a restauração.','texto_biblico',59),
('joel','Joel',2,'Segundo Joel 2:19, o que Deus promete enviar em fartura ao povo arrependido?','facil','Um novo templo imediato','Ouro e prata em abundância','Trigo, mosto e azeite','Exércitos estrangeiros aliados','C','Joel 2:19 promete trigo, mosto e azeite, fartando o povo, e prometendo não mais entregá-lo ao opróbrio entre as nações.','São os três principais produtos agrícolas de Israel.','texto_biblico',60),
('joel','Joel',2,'Segundo Joel 2:20, o que Deus promete fazer com o exército do norte?','facil','Fazê-lo governar Jerusalém','Torná-lo aliado permanente de Israel','Removê-lo e lançá-lo ao mar','Transformá-lo em sacerdotes','C','Joel 2:20 promete afastar de sobre o povo o exército do norte, lançando-o para uma terra seca e deserta, e ao mar.','É a remoção da ameaça militar que atormentava a nação.','texto_biblico',61),
('joel','Joel',3,'Segundo Joel 3:19, o que acontecerá ao Egito e a Edom por causa da violência contra Judá?','facil','Se tornarão as nações mais poderosas da terra','Tornar-se-ão desolação e deserto assolado','Receberão as bênçãos prometidas a Judá','Serão perdoados sem nenhuma consequência','B','Joel 3:19 anuncia que o Egito se tornará em desolação, e Edom em deserto assolado, por violência contra os filhos de Judá.','É um julgamento específico contra nações vizinhas hostis.','texto_biblico',62),
('joel','Joel',1,'Segundo Joel 1:3, o que o povo deve fazer com a memória da devastação sofrida?','medio','Contar aos filhos, para que estes contem aos seus filhos','Esquecer o quanto antes','Guardar segredo absoluto','Reescrever a história de forma diferente','A','Joel 1:3 ordena que contem isso a seus filhos, e seus filhos a seus filhos, e a outra geração, perpetuando a memória do desastre.','É uma ordem de transmissão da lembrança entre gerações.','texto_biblico',63),
('joel','Joel',1,'Segundo Joel 1:9, o que foi cortado da casa do Senhor por causa da devastação?','medio','A arca da aliança','O véu do templo','A oferta de manjares e a libação','O altar do incenso','C','Joel 1:9 lamenta que a oferta de manjares e a libação foram cortadas da casa do Senhor, afligindo os sacerdotes.','É uma consequência direta da perda das colheitas para o culto no templo.','texto_biblico',64),
('joel','Joel',2,'Segundo Joel 2:1, o que deve ser feito em Sião diante da aproximação do Dia do Senhor?','medio','Abandonar a cidade em silêncio','Construir um novo altar','Tocar a trombeta e dar alarma no monte santo','Reunir apenas os sacerdotes em segredo','C','Joel 2:1 ordena tocar a trombeta em Sião e dar alarma no monte santo do Senhor, para que todos os moradores da terra tremam.','É um alerta militar e espiritual simultâneo.','texto_biblico',65),
('joel','Joel',2,'Como Joel 2:2 descreve o Dia do Senhor logo no início do capítulo 2?','medio','Dia de trevas, escuridão, nuvens e negridão','Dia de luz radiante e festa','Dia comum, sem nenhuma diferença','Dia de descanso tranquilo','A','Joel 2:2 descreve o Dia do Senhor como dia de trevas e de escuridão, dia de nuvens e negridão.','É uma descrição sombria típica dos textos proféticos sobre o "Dia do Senhor".','texto_biblico',66),
('joel','Joel',2,'Segundo Joel 2:10, o que acontece com a terra e os céus diante do exército que se aproxima?','medio','Apenas o mar se agita levemente','Tudo permanece absolutamente calmo','A terra treme, os céus estremecem, sol e lua se escurecem','Só as estrelas se movem, o resto fica parado','C','Joel 2:10 descreve cataclismos cósmicos: a terra treme, os céus estremecem, o sol e a lua se escurecem, e as estrelas retiram o seu resplendor.','É uma linguagem apocalíptica comum aos profetas.','texto_biblico',67),
('joel','Joel',2,'Segundo Joel 2:11, por que é tão terrível o dia descrito, "mui grande e mui terrível"?','medio','Porque nenhuma nação estará envolvida','Porque quem executa a palavra do Senhor é grande e poderoso','Porque apenas Israel participará dele','Porque será um dia de descanso total','B','Joel 2:11 explica que o Senhor levanta a voz diante do seu exército, pois grande e mui poderoso é quem executa a sua palavra.','É uma reflexão sobre a grandiosidade do juízo divino.','texto_biblico',68),
('joel','Joel',2,'Segundo Joel 2:23 e 2:26-27, o que o povo restaurado nunca mais experimentará?','medio','Poderá cultivar a terra novamente','Terá filhos ou netos','Será envergonhado, e saberá que o Senhor está no meio de Israel','Ouvirá a palavra dos profetas','C','Joel 2:26-27 promete que o povo comerá e se fartará, louvará o nome do Senhor, e nunca mais será envergonhado.','É a conclusão da promessa de restauração agrícola e espiritual.','texto_biblico',69),
('joel','Joel',2,'Segundo Joel 2:23, que tipo de chuva Deus promete enviar com justiça?','medio','Chuva temporã e serôdia, no tempo certo','Apenas granizo destruidor','Chuva ácida sobre os inimigos','Nenhuma chuva, só orvalho','A','Joel 2:23 promete que Deus dará a chuva temporã com justiça, fazendo descer a chuva, a temporã e a serôdia, como dantes.','Refere-se às duas estações de chuva essenciais para a agricultura em Israel.','texto_biblico',70),
('joel','Joel',3,'Segundo Joel 3:2, para onde Deus ajuntará todas as nações a fim de entrar em juízo?','medio','Para as margens do rio Jordão','Para o monte Carmelo','Para o deserto do Sinai','Para o vale de Josafá','D','Joel 3:2 anuncia que Deus ajuntará todas as nações e as fará descer ao vale de Josafá para ali entrar em juízo com elas.','O nome do vale significa "o Senhor julga".','texto_biblico',71),
('joel','Joel',3,'Segundo Joel 3:4-6, por que Tiro, Sidom e a Filístia são julgadas?','medio','Por venderem filhos de Judá como escravos aos gregos','Por se recusarem a comerciar com Israel','Por adorarem o mesmo Deus de Israel','Por ajudarem Judá contra seus inimigos','A','Joel 3:4-6 acusa essas nações de tomarem prata e ouro de Judá e venderem seus filhos e filhas aos filhos dos gregos.','É uma acusação concreta de tráfico de pessoas contra essas cidades.','texto_biblico',72),
('joel','Joel',3,'Segundo Joel 3:14, o que caracteriza "o vale da decisão"?','medio','Um mercado próspero e pacífico','Um lugar vazio e esquecido','Um santuário reconstruído','Multidões reunidas, pois o Dia do Senhor está perto','D','Joel 3:14 declara: "Multidões, multidões no vale da decisão! Porque perto está o dia do Senhor no vale da decisão".','É uma repetição retórica que enfatiza a urgência do julgamento.','texto_biblico',73),
('joel','Joel',3,'Segundo Joel 3:16, o que acontece quando o Senhor ruge de Sião e faz ouvir sua voz de Jerusalém?','medio','Os céus e a terra tremem, mas o Senhor é refúgio para o seu povo','Nada de especial acontece','Apenas os sacerdotes ouvem o som','As nações vizinhas fazem aliança imediata','A','Joel 3:16 diz que os céus e a terra tremerão, mas o Senhor será refúgio para o seu povo e força para os filhos de Israel.','É uma imagem de juízo que também traz proteção ao povo fiel.','texto_biblico',74),
('joel','Joel',1,'Segundo Joel 1:18, como o próprio gado reage à devastação da praga e da seca?','dificil','Geme e se perturba, por não haver pasto para os rebanhos','Multiplica-se rapidamente por falta de predadores','Migra pacificamente para outra região','Permanece indiferente à escassez de alimento','A','Joel 1:18 descreve até os animais sofrendo: "como geme o gado! Os rebanhos de gado vacum estão confusos, porque não têm pasto".','É uma imagem que estende a devastação a toda a criação, não só aos humanos.','texto_biblico',75),
('joel','Joel',2,'Segundo Joel 2:2, como o exército descrito se compara a eventos da história de Israel?','dificil','Não houve outro como ele desde a antiguidade, nem haverá depois dele','É idêntico ao exército que cruzou o Mar Vermelho','É menor que qualquer invasão anterior','É comparável apenas às pragas do Egito','A','Joel 2:2 afirma que um povo grande e poderoso como aquele nunca houve desde a antiguidade, nem depois dele haverá, por gerações e gerações.','É uma hipérbole profética para enfatizar a magnitude única do julgamento.','texto_biblico',76),
('joel','Joel',2,'Segundo Joel 2:7-8, como o exército avança sem se desviar do seu curso?','dificil','Espera ordens antes de cada movimento','Avança apenas de noite, escondido','Corre como valentes, sobe muros, e cada um segue seu caminho sem se desviar','Recua ao menor sinal de resistência','C','Joel 2:7-8 descreve disciplina impressionante: correm como valentes, sobem os muros como homens de guerra, e não torcem os seus caminhos.','É uma descrição quase militar da precisão da praga de gafanhotos.','texto_biblico',77),
('joel','Joel',3,'Segundo Joel 3:12, o que Deus fará ao se assentar no vale de Josafá?','dificil','Julgar todas as nações ao redor','Coroar um novo rei sobre Judá','Reconstruir o templo pessoalmente','Assinar um tratado de paz eterna','A','Joel 3:12 declara: "Levantem-se as nações, e subam ao vale de Josafá; pois ali me assentarei para julgar todas as nações em redor".','É a cena central de julgamento universal no livro de Joel.','texto_biblico',78),
('joel','Joel',3,'Segundo Joel 3:13, a que imagem agrícola a hora do julgamento é comparada?','dificil','A uma semente que ainda não germinou','À colheita madura e ao lagar cheio, prestes a transbordar','A um campo deixado em pousio','A uma árvore recém-plantada','B','Joel 3:13 ordena: "Lançai a foice, porque já está madura a seara... o lagar transborda, porque a maldade deles é grande".','É uma imagem de juízo maduro e iminente, pronto para ser executado.','texto_biblico',79),
('joel','Joel',3,'Segundo Joel 3:20, por quanto tempo o livro promete que Judá e Jerusalém serão habitadas?','dificil','Somente durante quarenta anos','Apenas até o próximo exílio','Para sempre, de geração em geração','Até a chegada de um novo profeta','C','Joel 3:20 encerra o livro com a promessa: "Mas Judá será habitada para sempre, e Jerusalém de geração em geração".','É a nota final de esperança permanente do livro de Joel.','texto_biblico',80),
('amos','Amós',1,'Qual era a profissão de Amós antes de exercer seu ministério profético?','facil','Rei','Pastor de ovelhas e cultivador de sicômoros','Pescador','Sacerdote','B','Amós 1:1 e 7:14 apresentam Amós como pastor e cultivador de sicômoros.','Ele não se apresenta como membro de uma escola profética.','texto_biblico',81),
('amos','Amós',5,'O que Amós 5:24 diz que deve correr como um rio?','facil','O ouro','O vinho','A guerra','A justiça','D','Amós 5:24 compara a justiça a águas e o juízo à correnteza de um ribeiro perene.','É uma das imagens mais conhecidas do livro.','texto_biblico',82),
('amos','Amós',3,'Qual princípio Amós 3:3 apresenta?','medio','Dois andarão juntos se não houver acordo entre eles','Todo rei é justo','Israel nunca será julgado','Profetas não precisam ouvir Deus','A','Amós 3:3 pergunta se duas pessoas podem andar juntas sem estarem de acordo.','É uma pergunta sobre concordância e caminhada conjunta.','texto_biblico',83),
('amos','Amós',7,'O que Amós vê em uma das primeiras visões do capítulo 7?','medio','Uma escada','Uma arca','Um cesto de frutas de verão','Um carro de fogo','C','Amós 8:1-2 registra a visão de um cesto de frutas de verão, símbolo da proximidade do fim de Israel.','A visão está no capítulo 8.','texto_biblico',84),
('amos','Amós',8,'Na visão do cesto de frutas de verão, qual jogo de palavras aparece?','dificil','Chuva e bênção','Fruta de verão e fim chegou','Templo e altar','Rei e sacerdote','B','Amós 8:2 usa um jogo de palavras em hebraico entre fruta de verão e fim, indicando o fim de Israel.','A visão anuncia que o fim chegou.','texto_biblico',85),
('amos','Amós',4,'Como Amós 4:1 chama as mulheres opressoras de Samaria?','facil','Leoas do deserto','Vacas de Basã','Pombas do vale','Águias da montanha','B','Amós 4:1 usa a expressão vacas de Basã para denunciar mulheres que oprimiam os pobres.','É uma comparação com um animal de pastagem rica.','texto_biblico',86),
('amos','Amós',9,'O que Deus promete restaurar em Amós 9:11?','facil','O tabernáculo caído de Davi','O templo de Baal','O palácio do Egito','A muralha de Nínive','A','Amós 9:11 promete levantar o tabernáculo caído de Davi, texto citado em Atos 15.','É uma promessa messiânica ligada à linhagem de Davi.','texto_biblico',87),
('amos','Amós',2,'Do que Israel é acusado em Amós 2:6, ao vender pessoas?','medio','Vender terras para o Egito','Vender animais sagrados','Vender o justo por prata e o pobre por um par de sandálias','Vender armas para a Assíria','C','Amós 2:6 denuncia a venda do justo por dinheiro e do pobre por um simples par de sandálias.','É uma denúncia de injustiça social extrema.','texto_biblico',88),
('amos','Amós',6,'Contra quem é o "ai" pronunciado em Amós 6:1?','medio','Os estrangeiros pobres','Os pastores humildes','Os que vivem sossegados em Sião','Os sacerdotes fiéis','C','Amós 6:1 pronuncia ai sobre os que vivem despreocupados e confiantes em Sião e em Samaria.','É uma crítica à complacência dos líderes.','texto_biblico',89),
('amos','Amós',7,'Quem ordenou que Amós fugisse para Judá e parasse de profetizar em Betel?','dificil','O rei da Assíria','Um profeta rival','Jeroboão pessoalmente','Amazias, sacerdote de Betel','D','Amós 7:10-13 narra o confronto com Amazias, sacerdote de Betel, que expulsou Amós, ao que o profeta respondeu que não era profeta profissional, mas pastor chamado por Deus.','É o sacerdote do santuário real de Betel.','texto_biblico',90),
('amos','Amós',1,'Contra qual cidade é dirigido o primeiro oráculo de julgamento em Amós 1:3, com a fórmula "por três transgressões e por quatro"?','facil','Jerusalém','Damasco','Roma','Nínive','B','Amós 1:3 abre a série de oráculos contra as nações com Damasco, capital da Síria.','É a primeira de várias nações vizinhas condenadas nos capítulos 1 e 2.','texto_biblico',91),
('amos','Amós',1,'Por que Gaza é condenada em Amós 1:6?','facil','Por atacar diretamente Jerusalém','Por entregar cativos inteiros a Edom','Por se recusar a pagar tributo','Por adorar o Deus de Israel','B','Amós 1:6 acusa Gaza de levar cativo um povo inteiro para entregá-lo a Edom.','É uma acusação relacionada ao comércio de escravos entre nações.','texto_biblico',92),
('amos','Amós',1,'Por que Tiro é condenada em Amós 1:9?','facil','Por abrigar profetas falsos','Por adorar ídolos estrangeiros','Por recusar comerciar com outras nações','Por não se lembrar da aliança fraternal com Israel','D','Amós 1:9 acusa Tiro de entregar um povo inteiro a Edom, não se lembrando da aliança de irmãos.','Refere-se a um pacto histórico de amizade quebrado.','texto_biblico',93),
('amos','Amós',2,'Por que Judá é condenada em Amós 2:4?','facil','Por recusar pagar impostos a Israel','Por fazer aliança com o Egito','Por destruir o templo de Betel','Por rejeitar a lei do Senhor e não guardar seus preceitos','D','Amós 2:4 acusa Judá de rejeitar a lei do Senhor e se deixar enganar por mentiras que seus pais seguiram.','É a última nação condenada antes do foco se voltar para Israel.','texto_biblico',94),
('amos','Amós',2,'Segundo Amós 2:12, o que Israel fez contra os nazireus e os profetas?','facil','Deu vinho aos nazireus e mandou os profetas não profetizarem','Construiu templos especiais para eles','Multiplicou o número de nazireus e profetas','Pediu que ensinassem nas escolas','A','Amós 2:12 acusa Israel de dar vinho a beber aos nazireus (que haviam feito voto de abstinência) e calar os profetas.','É uma acusação de corromper pessoas consagradas a Deus.','texto_biblico',95),
('amos','Amós',3,'Segundo Amós 3:7, o que o Senhor Deus não faz sem antes revelar aos seus profetas?','facil','O seu segredo (plano)','O seu nome verdadeiro','A data exata do fim do mundo','O nome de cada pecador','A','Amós 3:7 declara: "Certamente o Senhor Deus não fará coisa alguma sem primeiro revelar o seu segredo aos seus servos, os profetas".','É um princípio importante sobre o papel da profecia bíblica.','texto_biblico',96),
('amos','Amós',4,'Segundo o refrão de Amós 4:6, apesar de Deus enviar fome de pão a todas as cidades, o que o povo não fez?','facil','Não notaram a diferença','Não se converteram a Deus','Prosperaram ainda mais','Culparam apenas os sacerdotes','B','Amós 4:6 repete o refrão "contudo não vos convertestes a mim", diz o Senhor, após enviar fome como advertência.','Esse refrão se repete várias vezes no capítulo 4, após diferentes pragas.','texto_biblico',97),
('amos','Amós',5,'Qual é o convite direto de Amós 5:6 ao povo de Israel?','facil','"Buscai o Senhor e vivei"','"Construí um novo templo"','"Aumentai vossos sacrifícios"','"Escolhei um novo rei"','A','Amós 5:6 apela: "Buscai o Senhor, e vivei, para que não se atire com fogo na casa de José".','É um chamado urgente e direto ao arrependimento.','texto_biblico',98),
('amos','Amós',5,'Segundo Amós 5:10, como o povo trata quem repreende com justiça?','facil','Recompensam com honrarias','Odeiam quem repreende e abominam quem fala com sinceridade','Pedem mais conselhos a essa pessoa','Nomeiam essa pessoa como juiz','B','Amós 5:10 denuncia: "Odeiam na porta ao que os repreende e abominam ao que fala com sinceridade".','Mostra a rejeição da correção justa pela sociedade corrupta.','texto_biblico',99),
('amos','Amós',6,'Como Amós 6:4 descreve o estilo de vida luxuoso e negligente dos líderes de Israel?','facil','Dormem em camas de marfim, estendidos em seus leitos','Vivem em barracas simples no deserto','Trabalham arduamente no campo todos os dias','Jejuam constantemente por devoção','A','Amós 6:4 descreve os que se deitam em camas de marfim e se estendem sobre os seus leitos, vivendo em ócio e luxo.','É uma crítica à vida confortável da elite enquanto o povo sofria.','texto_biblico',100),
('amos','Amós',8,'Segundo Amós 8:11, que tipo de fome o Senhor enviaria sobre a terra?','facil','Fome apenas entre os estrangeiros','Fome apenas de água','Fome de ouvir as palavras do Senhor','Fome que atingiria só os ricos','C','Amós 8:11 anuncia: "Enviarei fome sobre a terra, não fome de pão, nem sede de água, mas de ouvir as palavras do Senhor".','É uma fome espiritual, não apenas física.','texto_biblico',101),
('amos','Amós',9,'Segundo Amós 9:2, o que aconteceria mesmo que o povo cavasse até o Seol ou subisse ao céu?','facil','Se tornariam invisíveis a Deus','Encontrariam refúgio seguro','Ainda assim não escapariam do juízo de Deus','Ganhariam mais tempo de vida','C','Amós 9:2 declara que, ainda que cavem até o Seol, dali a mão de Deus os tirará; ainda que subam ao céu, dali os fará descer.','É uma afirmação sobre a onipresença do juízo divino.','texto_biblico',102),
('amos','Amós',1,'Por que Edom é condenado em Amós 1:11?','medio','Por abrigar refugiados de Judá','Por recusar pagar tributo a Israel','Por adorar o Deus de Israel secretamente','Por perseguir seu irmão com a espada, sufocando toda compaixão','D','Amós 1:11 acusa Edom de perseguir a espada o seu irmão (Israel/Judá), sufocando toda a sua compaixão, guardando ira para sempre.','Refere-se à relação histórica tensa entre Edom (descendente de Esaú) e Israel (descendente de Jacó).','texto_biblico',103),
('amos','Amós',1,'Por que os filhos de Amom são condenados em Amós 1:13?','medio','Por libertarem cativos de outras nações','Por se recusarem a fazer comércio com Israel','Por destruírem templos pagãos vizinhos','Por rasgarem o ventre de grávidas em Gileade para alargar seus limites','D','Amós 1:13 denuncia a brutalidade de Amom, que rasgou o ventre das mulheres grávidas de Gileade para expandir seu território.','É uma das acusações mais chocantes de crueldade em guerra no livro.','texto_biblico',104),
('amos','Amós',2,'Por que Moabe é condenado em Amós 2:1?','medio','Por recusar-se a pagar impostos a Judá','Por queimar os ossos do rei de Edom até os reduzir a cal','Por adorar abertamente o Deus de Israel','Por libertar prisioneiros de guerra','B','Amós 2:1 acusa Moabe de queimar os ossos do rei de Edom até virarem cal, um ato de profanação e desrespeito extremo.','Mostra que Deus também julga crimes cometidos entre nações pagãs, não só contra Israel.','texto_biblico',105),
('amos','Amós',3,'Segundo Amós 3:2, qual é a consequência de Israel ser o único povo que Deus conheceu dentre todas as famílias da terra?','medio','Por isso serão poupados de qualquer disciplina','Por isso nunca mais serão julgados','Por isso Deus os visitará (punirá) por todas as suas iniquidades','Por isso governarão todas as nações','C','Amós 3:2 declara: "a vós somente vos conheci... portanto eu vos punirei por todas as vossas iniquidades", ligando privilégio à responsabilidade.','É um princípio central da teologia da eleição em Amós.','texto_biblico',106),
('amos','Amós',3,'Segundo Amós 3:8, a que Amós compara a urgência de profetizar quando Deus fala?','medio','A um rumor sem importância','Ao canto de um pássaro qualquer','A um sussurro que pode ser ignorado','Ao rugido do leão, que ninguém deixa de temer','D','Amós 3:8 declara: "Bramando o leão, quem não temerá? Falando o Senhor Deus, quem não profetizará?".','É uma justificativa pessoal do profeta para seu ministério.','texto_biblico',107),
('amos','Amós',4,'Qual ironia Amós 4:4 usa ao convidar o povo a "ir a Betel e transgredir"?','medio','Pede que abandonem totalmente os sacrifícios','Elogia sinceramente o culto em Betel','Zomba dos rituais religiosos feitos sem verdadeiro arrependimento','Convida o povo a se mudar para Jerusalém','C','Amós 4:4 usa ironia mordaz: "Vinde a Betel, e transgredi; a Gilgal, e multiplicai a transgressão", criticando um culto vazio de sentido moral.','É um sarcasmo profético contra a religiosidade sem justiça.','texto_biblico',108),
('amos','Amós',4,'Depois de listar várias pragas que não trouxeram arrependimento, o que Amós 4:12 conclui que Israel deve fazer?','medio','Fazer um novo tratado com a Assíria','Reconstruir imediatamente o templo','Preparar-se para vir ao encontro do seu Deus','Abandonar de vez a terra prometida','C','Amós 4:12 conclui o refrão de pragas com a advertência solene: "Prepara-te, ó Israel, para te encontrares com o teu Deus".','É o clímax de uma série de avisos ignorados.','texto_biblico',109),
('amos','Amós',5,'Segundo Amós 5:21-22, qual é a atitude de Deus em relação às festas religiosas de Israel?','medio','Ignora completamente o assunto','Aprova plenamente cada uma delas','Pede que sejam feitas com mais frequência','Odeia e despreza essas festas, recusando as ofertas','D','Amós 5:21-22 declara: "Odeio, desprezo as vossas festas... não aceitarei as vossas ofertas pacíficas".','É uma crítica contundente ao formalismo religioso sem justiça social.','texto_biblico',110),
('amos','Amós',5,'Segundo Amós 5:23, o que Deus pede que cesse antes de aceitar qualquer adoração?','medio','O trabalho no campo','O estrépito dos cânticos e a música das harpas','As orações dos sacerdotes','A leitura pública da lei','B','Amós 5:23 pede: "Afasta de mim o estrépito dos teus cânticos, e a música das tuas liras não escutarei".','Prepara o caminho para o famoso apelo por justiça que corre como águas no verso seguinte.','texto_biblico',111),
('amos','Amós',6,'Segundo Amós 6:13, de que os líderes se orgulham de forma arrogante?','medio','De terem restaurado a lei de Moisés','De terem construído o templo de Jerusalém','De terem vencido a Assíria em batalha','De terem tomado poder com sua própria força','D','Amós 6:13 denuncia os que se alegram de nada, dizendo: "Não tomamos nós para nós poder com a nossa própria força?".','É uma crítica à autossuficiência que ignora a soberania de Deus.','texto_biblico',112),
('amos','Amós',7,'Na segunda visão de Amós (7:4-6), o que o profeta vê e como reage?','medio','Vê um novo templo e se alegra','Vê um exército estrangeiro e foge','Vê um fogo devorador e intercede pelo povo','Vê uma seca e permanece em silêncio','C','Amós 7:4-6 relata uma visão de fogo que consumiria a terra; Amós intercede e o Senhor se arrepende também dessa punição.','É a segunda de cinco visões registradas nos capítulos finais do livro.','texto_biblico',113),
('amos','Amós',9,'Segundo Amós 9:7, com que povo Israel é comparado para mostrar que todas as nações estão sob o juízo de Deus?','medio','Com nenhum outro povo, pois é único','Apenas com os egípcios','Apenas com os babilônios','Com os filhos dos etíopes (cuxitas)','D','Amós 9:7 questiona: "Não sois vós para mim, ó filhos de Israel, como filhos dos etíopes? diz o Senhor", igualando todos os povos perante o juízo divino.','É uma afirmação surpreendente sobre a universalidade da justiça de Deus.','texto_biblico',114),
('amos','Amós',5,'Segundo Amós 5:18-20, o que o profeta adverte sobre o "Dia do Senhor" para quem o deseja levianamente?','dificil','Será uma festa de alegria sem fim','Será trevas e não luz, ao contrário do que esperam','Trará prosperidade imediata a todos','Não terá nenhuma consequência real','B','Amós 5:18-20 adverte: "Ai dos que desejam o dia do Senhor!... Não é ele trevas, e não luz?", corrigindo uma expectativa equivocada de bênção automática.','É uma das passagens mais teologicamente ricas sobre o "Dia do Senhor" no Antigo Testamento.','texto_biblico',115),
('amos','Amós',7,'Na terceira visão de Amós (7:7-8), o que o Senhor mostra ao profeta, simbolizando um padrão de justiça?','dificil','Um cesto vazio de frutas','Um prumo de pedreiro no meio do seu povo','Uma vara de amendoeira florida','Um rolo de pergaminho em branco','B','Amós 7:7-8 descreve a visão do prumo (fio de prumo), instrumento usado para medir se uma parede está reta, simbolizando o padrão de justiça de Deus para Israel.','É a terceira das cinco visões do livro.','texto_biblico',116),
('amos','Amós',8,'Segundo Amós 8:5, o que os mercadores desonestos aguardavam ansiosamente para poder vender com balanças falsas?','dificil','O início da colheita anual','O fim do sábado e da lua nova','A chegada de comerciantes estrangeiros','A nomeação de um novo sacerdote','B','Amós 8:5 denuncia mercadores que perguntam: "Quando passará a lua nova, para vendermos o grão? e o sábado, para expormos o trigo?", usando balanças enganosas.','É uma crítica direta à corrupção comercial disfarçada de observância religiosa.','texto_biblico',117),
('amos','Amós',9,'Na quinta visão de Amós (9:1), onde o Senhor aparece e o que ordena?','dificil','Aparece no céu e ordena reconstruir o templo','Aparece em pé sobre o altar e ordena ferir os umbrais das portas','Aparece no deserto e ordena erguer uma tenda','Aparece no mar e ordena construir navios','B','Amós 9:1 relata a visão do Senhor em pé sobre o altar, ordenando ferir os capitéis das portas para que os umbrais estremeçam, anunciando julgamento total.','É a quinta e última das visões registradas no livro.','texto_biblico',118),
('amos','Amós',9,'Segundo a promessa final de Amós 9:15, o que acontecerá quando Deus replantar Israel em sua terra?','dificil','Nunca mais serão arrancados da terra que lhes foi dada','Terão que reconquistá-la a cada geração','Precisarão dividir a terra com outras nações','Viverão lá apenas temporariamente','A','Amós 9:15 conclui o livro com a promessa: "Plantá-los-ei na sua terra, e nunca mais serão arrancados da sua terra que eu lhes dei".','É a nota final de esperança depois de tantos oráculos de julgamento.','texto_biblico',119),
('amos','Amós',2,'Segundo Amós 2:9, o que Deus lembra ter feito ao amorreu, "cuja altura era como a dos cedros", diante de Israel?','dificil','Fez aliança eterna de paz com ele','Destruiu-o completamente, de cima a baixo, diante do povo','Permitiu que continuasse a habitar Canaã livremente','Transformou-o em aliado de Israel','B','Amós 2:9 relembra que Deus destruiu o amorreu diante de Israel, cuja altura era como a dos cedros, e cuja força como a dos carvalhos.','É uma referência histórica à conquista de Canaã como fundamento da aliança quebrada por Israel.','texto_biblico',120),
('obadias','Obadias',1,'Qual nação é o principal alvo da profecia de Obadias?','facil','Egito','Moabe','Assíria','Edom','D','Obadias é uma profecia contra Edom.','Edom é o povo descendente de Esaú.','texto_biblico',121),
('obadias','Obadias',1,'Edom é associado a qual ancestral?','facil','Isaque','Esaú','Jacó','José','B','Edom está ligado a Esaú, irmão de Jacó, conforme Gênesis.','Esaú recebeu o nome Edom.','texto_biblico',122),
('obadias','Obadias',1,'Por que Edom é condenado em Obadias?','medio','Por cultivar oliveiras','Por construir o templo','Por abandonar o Egito','Por sua violência contra seu irmão Jacó','D','Obadias 10-14 condena a violência e a participação de Edom na desgraça de Judá.','O texto fala de violência contra o irmão.','texto_biblico',123),
('obadias','Obadias',1,'O que Obadias 17 promete que haverá no monte Sião?','medio','Um exército estrangeiro','Uma nova pirâmide','Livramento e santidade','Uma grande frota','C','Obadias 17 afirma que no monte Sião haverá livramento e ele será santo.','É uma promessa para Sião.','texto_biblico',124),
('obadias','Obadias',1,'Qual é a ideia central do final de Obadias sobre o reino?','dificil','O reino será do Senhor','Não haverá restauração','Edom governará para sempre','Babilônia dominará Judá','A','Obadias 21 termina com a declaração de que o reino será do Senhor.','É a frase final do livro.','texto_biblico',125),
('obadias','Obadias',1,'Segundo Obadias 3, o que enganou o coração de Edom?','facil','A fome','A ignorância','A pobreza','A soberba','D','Obadias 3 diz que a soberba do coração de Edom o enganou, confiando em sua posição elevada nas rochas.','É um pecado ligado ao orgulho.','texto_biblico',126),
('obadias','Obadias',1,'Onde Edom habitava, segundo a descrição de Obadias 3?','facil','Nas fendas das rochas, em lugar alto','Em barcos no mar Vermelho','Nas margens do rio Nilo','Em tendas no deserto do Sinai','A','Obadias 3 descreve Edom habitando nas fendas das rochas, confiante em sua altura e segurança.','É uma região montanhosa e fortificada.','texto_biblico',127),
('obadias','Obadias',1,'Qual foi a atitude de Edom quando estrangeiros saquearam Jerusalém, segundo Obadias 11?','medio','Defendeu Jerusalém com seu exército','Ficou de lado e se comportou como um deles','Avisou os profetas com antecedência','Abrigou os refugiados de Judá','B','Obadias 11 acusa Edom de ficar de lado, omisso, comportando-se como um dos invasores.','A culpa envolve omissão e cumplicidade.','texto_biblico',128),
('obadias','Obadias',1,'Qual princípio de reciprocidade aparece em Obadias 15?','medio','Quem semeia pouco colhe muito','Como fizeste, se fará a ti','Não haverá julgamento para nenhuma nação','O rico sempre vencerá','B','Obadias 15 anuncia que o dia do Senhor virá sobre todas as nações e o que Edom fez lhe será retribuído.','É uma lei de causa e efeito no juízo divino.','texto_biblico',129),
('obadias','Obadias',1,'Em Obadias 18, a que a casa de Esaú é comparada diante do fogo de Jacó e José?','dificil','Um rio caudaloso','Ouro puro','Restolho, que será consumido','Uma torre inabalável','C','Obadias 18 descreve a casa de Jacó como fogo e a de Esaú como restolho, que será totalmente consumido.','É um material seco e facilmente inflamável.','texto_biblico',130),
('obadias','Obadias',1,'Segundo Obadias 1, quem enviou um embaixador entre as nações para convocar a guerra contra Edom?','facil','O Senhor','Um rei estrangeiro aliado de Judá','O próprio Edom, por engano','Um exército sem líder definido','A','Obadias 1 relata: "Ouvimos rumor do Senhor, e um embaixador foi enviado entre as nações", mostrando que a iniciativa do julgamento vem de Deus.','É a abertura solene da visão do profeta.','texto_biblico',131),
('obadias','Obadias',1,'Segundo Obadias 2, como Deus promete tornar Edom entre as nações?','facil','Rico e cobiçado','Grande e temido por todos','Pequeno e muito desprezado','Esquecido e nunca mais mencionado','C','Obadias 2 declara: "Eis que te fiz pequeno entre as nações; mui desprezado és tu".','É o anúncio direto da humilhação que viria sobre Edom.','texto_biblico',132),
('obadias','Obadias',1,'Segundo Obadias 4, o que aconteceria a Edom mesmo que ele se elevasse como a águia e pusesse seu ninho entre as estrelas?','facil','Se tornaria intocável para sempre','Ainda assim Deus o derribaria dali','Ganharia o respeito de todas as nações','Se uniria aos anjos no céu','B','Obadias 4 afirma: "Ainda que te elevasses como a águia... dali te derribaria, diz o Senhor".','É uma imagem de orgulho elevado que será, ainda assim, derrubado.','texto_biblico',133),
('obadias','Obadias',1,'Segundo Obadias 5, o que até ladrões ou vindimadores costumam deixar para trás, ao contrário do que aconteceria com Edom?','facil','Apenas documentos sem valor','Toda a riqueza saqueada','Nada, pois levam tudo igualmente','Alguns restos (o que lhes bastasse, ou alguns rabiscos de uvas)','D','Obadias 5 observa que ladrões levam só o que lhes basta, e vindimadores deixam alguns rabiscos, mas a destruição de Edom seria total.','É uma comparação para mostrar a completude do julgamento sobre Edom.','texto_biblico',134),
('obadias','Obadias',1,'Segundo Obadias 6, o que aconteceu com os tesouros e lugares escondidos de Esaú (Edom)?','facil','Foram investigados e esquadrinhados','Permaneceram seguros para sempre','Foram multiplicados por Deus','Nunca chegaram a existir','A','Obadias 6 exclama: "Como foram investigadas as coisas de Esaú! Como foram esquadrinhados os seus lugares escondidos!".','Mostra que nem os esconderijos mais seguros escapariam da busca dos invasores.','texto_biblico',135),
('obadias','Obadias',1,'Segundo Obadias 9, o que aconteceria aos valentes guerreiros de Temã, região de Edom?','facil','Seriam recompensados com terras','Se tornariam os mais fortes da região','Fugiriam vitoriosos para Judá','Ficariam espantados (aterrorizados)','D','Obadias 9 anuncia: "E os teus valentes, ó Temã, serão espantados", mostrando o colapso da força militar de Edom.','Temã era uma importante cidade/região dentro do território de Edom.','texto_biblico',136),
('obadias','Obadias',1,'Segundo Obadias 10, o que cobriria Edom por causa da violência contra seu irmão Jacó?','facil','Vergonha, e seria exterminado para sempre','Uma grande honra entre as nações','Riqueza duradoura','Nada, pois seria perdoado','A','Obadias 10 declara: "Por causa da violência contra teu irmão Jacó, cobrir-te-á vergonha, e serás exterminado para sempre".','É a razão central do julgamento: a traição fraternal contra Jacó/Israel.','texto_biblico',137),
('obadias','Obadias',1,'Segundo Obadias 16, assim como Edom bebeu no monte santo de Deus, o que aconteceria a todas as nações?','facil','Ficariam livres de qualquer julgamento','Seriam abençoadas com fartura eterna','Se tornariam sócias de Edom','Beberiam continuamente e seriam como se nunca tivessem existido','D','Obadias 16 amplia o julgamento: "como vós bebestes no meu santo monte, beberão continuamente todas as nações... serão como se nunca tivessem sido".','Mostra que o julgamento de Edom é sinal de um julgamento maior sobre as nações.','texto_biblico',138),
('obadias','Obadias',1,'Segundo Obadias 19, quem possuiria o monte de Esaú na restauração prometida?','facil','Apenas os sacerdotes de Jerusalém','Os do sul (Neguebe)','Os babilônios','Ninguém, pois ficaria deserto para sempre','B','Obadias 19 anuncia que os do sul possuiriam o monte de Esaú, e os das planícies, os filisteus.','Faz parte da lista de restauração territorial no fim do livro.','texto_biblico',139),
('obadias','Obadias',1,'Segundo Obadias 20, até onde os cativos de Israel possuiriam terras, segundo a promessa de restauração?','facil','Até a Babilônia','Até o Egito','Até Zarefate (Sarepta)','Até a Pérsia','C','Obadias 20 promete que os cativos dos filhos de Israel possuiriam a terra dos cananeus até Zarefate.','Zarefate era uma cidade na costa fenícia, ao norte de Israel.','texto_biblico',140),
('obadias','Obadias',1,'Segundo Obadias 21, o que subirá ao monte Sião para julgar o monte de Esaú?','facil','Anjos vingadores apenas','Um novo exército de Edom','Salvadores','Reis estrangeiros aliados','C','Obadias 21 conclui: "E salvadores subirão ao monte Sião, para julgarem o monte de Esaú".','É o penúltimo verso do livro, preparando a conclusão final.','texto_biblico',141),
('obadias','Obadias',1,'Segundo a frase final de Obadias 21, a quem pertencerá o reino?','facil','A Edom','Ao Senhor','A um novo império humano','A Judá, de forma independente de Deus','B','Obadias 21 encerra o livro com a declaração: "e o reino será do Senhor".','É a última frase do livro, resumindo toda a esperança profética em um só reino divino.','texto_biblico',142),
('obadias','Obadias',1,'Segundo Obadias 1, qual convocação exata as nações recebem no início da visão?','medio','"Fujamos todos para as montanhas"','"Levantai-vos, e levantemo-nos contra ela à peleja"','"Façamos aliança eterna com Edom"','"Perdoemos Edom por seus erros"','B','Obadias 1 registra a convocação: "Levantai-vos, e levantemo-nos contra ela à peleja", um chamado coletivo de guerra contra Edom.','É a mensagem que o embaixador enviado entre as nações transmite.','texto_biblico',143),
('obadias','Obadias',1,'Segundo Obadias 7, o que os próprios aliados de Edom fizeram no fim?','medio','Se sacrificaram para salvá-lo','Permaneceram fiéis até o último momento','Enganaram-no e prevaleceram contra ele','Se recusaram a lutar contra ele','C','Obadias 7 relata que os aliados de Edom o enganaram e prevaleceram contra ele; até os que comiam seu pão lhe armaram uma cilada.','Mostra a ironia de Edom ser traído pelos mesmos que confiava.','texto_biblico',144),
('obadias','Obadias',1,'Segundo Obadias 8, o que Deus promete fazer com os sábios de Edom?','medio','Multiplicar sua sabedoria','Torná-los conselheiros de Israel','Fazê-los perecer, junto com o entendimento do monte de Esaú','Enviá-los como mensageiros a Judá','C','Obadias 8 declara: "Porventura, não farei eu perecer naquele dia... os sábios de Edom, e o entendimento do monte de Esaú?".','Mostra que nem a reconhecida sabedoria de Edom o salvaria do julgamento.','texto_biblico',145),
('obadias','Obadias',1,'Segundo Obadias 12, do que Edom não deveria ter se alegrado?','medio','Da sua própria prosperidade','Do dia do infortúnio do seu irmão Judá','Das vitórias militares de Israel','Da reconstrução do templo','B','Obadias 12 repreende: "tu não deverias olhar contente o dia de teu irmão, no dia do seu infortúnio".','É o início de uma série de repreensões sobre a atitude de Edom durante a queda de Jerusalém.','texto_biblico',146),
('obadias','Obadias',1,'Segundo Obadias 13, quais três atitudes específicas Edom não deveria ter tido no dia da calamidade de Jerusalém?','medio','Reconstruir seus muros, orar e jejuar','Entrar por suas portas, olhar o mal e lançar mão dos seus bens','Enviar tropas, negociar e assinar tratados','Nenhuma, pois nada é mencionado','B','Obadias 13 lista: não entrar pela porta do povo, não olhar para o mal, e não lançar mão dos bens no dia da calamidade.','É uma acusação detalhada da cumplicidade de Edom na queda de Jerusalém.','texto_biblico',147),
('obadias','Obadias',1,'Segundo Obadias 14, o que Edom fez nas encruzilhadas dos caminhos?','medio','Exterminou os que escapavam e entregou os sobreviventes','Ofereceu refúgio aos fugitivos de Judá','Construiu abrigos para os feridos','Guiou os fugitivos até Jerusalém em segurança','A','Obadias 14 acusa Edom de se postar nas encruzilhadas para exterminar os que escapavam e entregar os que ficavam no dia da angústia.','É uma das acusações mais graves contra a cumplicidade ativa de Edom.','texto_biblico',148),
('obadias','Obadias',1,'Segundo Obadias 15, qual princípio de justiça poética é anunciado sobre o Dia do Senhor?','medio','"Nenhuma nação será julgada"','"Quem perdoa será perdoado sempre"','"O forte sempre vencerá o fraco"','"Como fizeste, se te fará a ti"','D','Obadias 15 declara: "Porque o dia do Senhor está perto sobre todas as nações; como fizeste, se te fará a ti".','É a aplicação do princípio de reciprocidade divina a todas as nações, não só a Edom.','texto_biblico',149),
('obadias','Obadias',1,'Segundo Obadias 17, o que a casa de Jacó voltará a possuir?','medio','Apenas o monte Sião, nada mais','As suas próprias possessões','Territórios pertencentes a outras nações','Somente riquezas do templo','B','Obadias 17 promete: "Mas no monte Sião haverá livramento... e a casa de Jacó possuirá as suas possessões".','Marca a virada do livro, do julgamento de Edom para a restauração de Israel.','texto_biblico',150),
('obadias','Obadias',1,'Segundo Obadias 18, a que a casa de Jacó e a casa de José são comparadas, em contraste com a casa de Esaú?','medio','A fogo e a chama','A água e a chuva','A pedra e a rocha firme','A vento e a tempestade','A','Obadias 18 declara: "a casa de Jacó será fogo, e a casa de José, chama, e a casa de Esaú, restolho", uma imagem de destruição completa de Edom.','O restolho (palha seca) é rapidamente consumido pelo fogo.','texto_biblico',151),
('obadias','Obadias',1,'Segundo Obadias 19, especificamente quem possuiria a região de Gileade na restauração prometida?','medio','Os babilônios exilados','Judá sozinho','Os filisteus','Benjamim','D','Obadias 19 detalha a redistribuição territorial: "e Benjamim possuirá Gileade", entre outras porções restauradas a Israel.','Faz parte da lista detalhada de restauração territorial ao final do livro.','texto_biblico',152),
('obadias','Obadias',1,'Segundo Obadias 20, o que os cativos de Jerusalém que estavam em Sefarade possuiriam?','medio','A capital da Assíria','As cidades do litoral fenício','As cidades do sul','Nenhum território, apenas retornariam vazios','C','Obadias 20 promete que os cativos de Jerusalém, que estavam em Sefarade, possuiriam as cidades do sul (Neguebe).','Sefarade é identificada por estudiosos com uma região do império lídio ou persa.','texto_biblico',153),
('obadias','Obadias',1,'Segundo Obadias 3, qual pergunta arrogante o coração de Edom fazia a si mesmo, revelando sua soberba?','medio','"Quem me derrubará em terra?"','"Quem se atreverá a me visitar?"','"Quando virá minha recompensa?"','"Onde estão meus inimigos agora?"','A','Obadias 3 cita a arrogância de Edom, que habitava nas fendas das rochas e dizia em seu coração: "Quem me derrubará em terra?".','É a raiz espiritual do pecado de Edom: orgulho baseado em segurança geográfica.','texto_biblico',154),
('obadias','Obadias',1,'Segundo Obadias 5, por que a comparação com ladrões e vindimadores torna ainda mais grave a destruição anunciada sobre Edom?','dificil','Porque Edom seria poupado por eles, ao contrário do previsto','Porque ladrões e vindimadores nunca causam dano real','Porque mesmo esses costumam deixar restos, mas Edom seria arrasado por completo','Porque a comparação elogia a generosidade dos invasores de Edom','C','Obadias 5 argumenta que até ladrões levam só o que lhes basta e vindimadores deixam alguns rabiscos, mas o julgamento sobre Edom seria uma devastação total, sem sobras.','É um argumento por contraste ("quanto mais") típico da retórica profética.','texto_biblico',155),
('obadias','Obadias',1,'Segundo Obadias 7, quem especificamente traiu Edom no momento decisivo?','dificil','Somente seus próprios familiares diretos','Apenas exércitos estrangeiros desconhecidos','Seus próprios aliados e os que comiam do seu pão','Ninguém; Edom não foi traído por ninguém','C','Obadias 7 detalha que os aliados de Edom o acompanharam só até certo ponto, e os que tinham paz com ele o enganaram, incluindo os que comiam do seu pão.','É uma reviravolta irônica: Edom, que traiu seu irmão Jacó, é traído por seus próprios aliados.','texto_biblico',156),
('obadias','Obadias',1,'Segundo Obadias 11, qual expressão mostra que Edom se tornou cúmplice dos invasores de Jerusalém?','dificil','"Tu socorreste os sobreviventes"','"Tu foste o único a resistir"','"Tu choraste pela cidade destruída"','"Tu também eras como um deles"','D','Obadias 11 acusa: no dia em que estranhos levavam cativo o exército e lançavam sortes sobre Jerusalém, "tu também eras como um deles".','É a acusação central que justifica todo o julgamento anunciado contra Edom.','texto_biblico',157),
('obadias','Obadias',1,'Segundo Obadias 16, a expressão "beberão continuamente" aplicada a todas as nações se refere a quê?','dificil','A um banquete de celebração da vitória de Edom','A uma bênção de prosperidade universal','Ao cálice do julgamento de Deus, estendido além de Edom','A um pacto de aliança eterna entre as nações','C','Obadias 16 estende o padrão do julgamento de Edom a todas as nações, que "beberão continuamente... e serão como se nunca tivessem sido".','É uma ampliação do juízo particular contra Edom para um princípio universal de justiça.','texto_biblico',158),
('obadias','Obadias',1,'Segundo Obadias 18, qual é o destino final e absoluto declarado sobre a casa de Esaú?','dificil','Não haverá remanescente algum, porque o Senhor o disse','Uma pequena parte sempre sobreviverá','Será restaurada junto com a casa de Jacó','Se tornará serva voluntária de Israel','A','Obadias 18 conclui com máxima ênfase: "e não haverá remanescente algum da casa de Esaú, porque o Senhor o disse".','É a mais categórica sentença de julgamento total em todo o livro.','texto_biblico',159),
('obadias','Obadias',1,'Segundo Obadias 9, qual é a finalidade declarada do espanto que cairia sobre os valentes de Temã?','dificil','Para que se rendessem sem lutar e fossem poupados','Para que cada um fosse exterminado do monte de Esaú pela matança','Para que se tornassem escravos de Israel apenas','Para que abandonassem Edom e migrassem em paz','B','Obadias 9 declara que os valentes de Temã serão espantados, "para que cada um seja exterminado do monte de Esaú pela matança".','Liga o colapso militar de Edom diretamente ao extermínio anunciado contra toda a nação.','texto_biblico',160),
('jonas','Jonas',1,'Para qual cidade Jonas foi enviado para pregar?','facil','Nínive','Babilônia','Jerusalém','Samaria','A','Jonas 1:2 ordena que o profeta vá a Nínive para anunciar sua mensagem.','Era a grande cidade da Assíria.','texto_biblico',161),
('jonas','Jonas',2,'O que engoliu Jonas depois que ele foi lançado ao mar?','facil','Um navio','Um crocodilo','Um grande peixe','Uma baleia mencionada pelo nome','C','Jonas 1:17 diz que o Senhor preparou um grande peixe para engolir Jonas.','O texto chama de grande peixe.','texto_biblico',162),
('jonas','Jonas',3,'Como os ninivitas reagiram à pregação de Jonas?','medio','Prenderam Jonas','Ignoraram a mensagem','Arrependeram-se e proclamaram jejum','Foram para Jerusalém','C','Jonas 3 descreve arrependimento, jejum e clamor a Deus desde o povo até o rei.','O rei também participou do jejum.','texto_biblico',163),
('jonas','Jonas',4,'Por que Jonas ficou descontente depois da misericórdia de Deus para Nínive?','medio','Porque perdeu o barco','Porque não recebeu pagamento','Porque o peixe voltou','Porque Deus não destruiu a cidade','D','Jonas 4:1-2 mostra que Jonas ficou irado porque Deus teve misericórdia e não executou o juízo anunciado.','Jonas já sabia que Deus era misericordioso.','texto_biblico',164),
('jonas','Jonas',4,'Que planta Deus fez crescer para dar sombra a Jonas?','dificil','Uma figueira','Um mamoeiro','Uma videira','Uma planta chamada mamona na tradição portuguesa','D','Jonas 4:6 fala de uma planta que cresceu para fazer sombra; traduções portuguesas variam na identificação, frequentemente usando mamona ou planta de rícino.','O texto enfatiza que Deus preparou a planta e depois a fez secar.','texto_biblico',165),
('jonas','Jonas',1,'Para onde Jonas tentou fugir em vez de ir a Nínive?','facil','Társis','Damasco','Jerusalém','Babilônia','A','Jonas 1:3 relata que o profeta embarcou em um navio rumo a Társis, fugindo da presença do Senhor.','Era uma cidade distante, na direção oposta a Nínive.','texto_biblico',166),
('jonas','Jonas',1,'Como os marinheiros descobriram que Jonas era o responsável pela tempestade?','facil','Lançaram sortes','Consultaram um oráculo egípcio','Jonas confessou espontaneamente logo no início','Um anjo apareceu','A','Jonas 1:7 relata que os marinheiros lançaram sortes, e a sorte caiu sobre Jonas.','É um método antigo de decisão por acaso.','texto_biblico',167),
('jonas','Jonas',2,'O que Jonas declara sobre a salvação em sua oração de dentro do peixe (Jonas 2:9)?','medio','A salvação vem dos sacerdotes','Não há salvação possível','A salvação pertence ao Senhor','A salvação depende dos marinheiros','C','Jonas 2:9 conclui a oração afirmando que a salvação pertence ao Senhor.','É a frase de encerramento da oração no ventre do peixe.','texto_biblico',168),
('jonas','Jonas',3,'Qual foi a mensagem exata que Jonas pregou em Nínive, segundo Jonas 3:4?','medio','Os reis da terra se converterão','Ainda quarenta dias, e Nínive será destruída','Nínive será poupada para sempre','Israel será restaurado em breve','B','Jonas 3:4 registra o anúncio de julgamento em quarenta dias sobre Nínive.','Envolve um prazo específico de dias.','texto_biblico',169),
('jonas','Jonas',4,'No argumento final de Deus a Jonas, quantas pessoas incapazes de discernir a mão direita da esquerda havia em Nínive?','dificil','Um milhão','Mais de cento e vinte mil','Doze mil','Exatamente cem','B','Jonas 4:11 menciona mais de cento e vinte mil pessoas em Nínive, além de muitos animais, como razão da compaixão de Deus.','É um número alto, citado junto com os animais da cidade.','texto_biblico',170),
('jonas','Jonas',1,'Segundo Jonas 1:1, quem era o pai de Jonas?','facil','Baruque','Amoz','Hilquias','Amitai','D','Jonas 1:1 identifica o profeta como "Jonas, filho de Amitai".','É a mesma identificação usada em 2 Reis 14:25 para o profeta Jonas.','texto_biblico',171),
('jonas','Jonas',1,'De qual porto Jonas embarcou ao tentar fugir da missão em Nínive?','facil','Jope','Jerusalém','Cesareia','Alexandria','A','Jonas 1:3 relata que ele desceu a Jope e achou um navio que ia para Társis.','Jope era um importante porto na costa do Mediterrâneo.','texto_biblico',172),
('jonas','Jonas',1,'Segundo Jonas 1:16, o que os marinheiros fizeram depois que o mar se acalmou?','facil','Abandonaram o navio imediatamente','Voltaram a adorar seus próprios deuses','Puniram Jonas por ter causado a tempestade','Temeram ao Senhor, ofereceram sacrifício e fizeram votos','D','Jonas 1:16 relata que os homens temeram ao Senhor com grande temor, ofereceram sacrifício ao Senhor e fizeram votos.','É uma conversão inesperada de marinheiros pagãos diante do poder de Deus.','texto_biblico',173),
('jonas','Jonas',1,'Segundo Jonas 1:15, o que aconteceu ao mar assim que os marinheiros lançaram Jonas nele?','facil','Ficou ainda mais violento','O mar se aquietou, cessando o seu furor','Permaneceu exatamente igual','Se transformou em terra firme','B','Jonas 1:15 relata que, assim que o lançaram ao mar, este cessou o seu furor.','É a resposta imediata de Deus ao sacrifício relutante dos marinheiros.','texto_biblico',174),
('jonas','Jonas',1,'Como Jonas se identificou aos marinheiros quando perguntado sobre quem era, em Jonas 1:9?','facil','"Sou um soldado fugindo da guerra"','"Sou um mercador em viagem de negócios"','"Sou hebreu, e temo ao Senhor Deus dos céus"','"Não sei quem sou nem de onde venho"','C','Jonas 1:9 registra sua resposta: "Sou hebreu, e temo ao Senhor Deus dos céus, que fez o mar e a terra".','É a confissão de fé de Jonas mesmo em plena fuga de sua missão.','texto_biblico',175),
('jonas','Jonas',2,'De onde Jonas orou ao Senhor, segundo Jonas 2:1?','facil','Do ventre do peixe','Do fundo de um poço','De cima de um monte','De dentro de uma caverna','A','Jonas 2:1 relata: "Então orou Jonas ao Senhor, seu Deus, das entranhas do peixe".','É a oração registrada durante os três dias e três noites dentro do peixe.','texto_biblico',176),
('jonas','Jonas',3,'Segundo Jonas 3:3, quantos dias de caminho tinha a grande cidade de Nínive?','facil','Um dia inteiro','Três dias','Sete dias','Quarenta dias','B','Jonas 3:3 descreve Nínive como "uma cidade grande diante de Deus, de caminho de três dias".','Mostra o imenso tamanho da cidade que Jonas precisava percorrer.','texto_biblico',177),
('jonas','Jonas',3,'Segundo Jonas 3:5, qual foi a reação inicial dos ninivitas à pregação de Jonas?','facil','Expulsaram Jonas da cidade imediatamente','Ignoraram completamente a mensagem','Creram em Deus, proclamaram jejum e vestiram saco','Riram e continuaram sua rotina normal','C','Jonas 3:5 relata que os ninivitas creram em Deus, apregoaram jejum e se vestiram de saco, do maior ao menor.','É um dos maiores avivamentos registrados na Bíblia, envolvendo uma cidade pagã inteira.','texto_biblico',178),
('jonas','Jonas',3,'Segundo Jonas 3:6, o que o próprio rei de Nínive fez ao ouvir a mensagem?','facil','Levantou-se do trono, vestiu saco e sentou-se sobre cinza','Ordenou a execução imediata de Jonas','Declarou guerra contra Israel','Ignorou o profeta e continuou seus afazeres reais','A','Jonas 3:6 relata que o rei se levantou do seu trono, tirou de si a roupa de rei, cobriu-se de saco e se assentou sobre cinza.','Mostra a seriedade com que a liderança de Nínive recebeu a mensagem de julgamento.','texto_biblico',179),
('jonas','Jonas',3,'Segundo o decreto real de Jonas 3:7-8, quem mais, além dos seres humanos, deveria participar do jejum em Nínive?','facil','Também os animais','Somente os sacerdotes pagãos','Apenas os estrangeiros na cidade','Ninguém mais, só o próprio rei','A','Jonas 3:7-8 relata um decreto incomum: nem homens nem animais, nem manadas nem rebanhos, provariam coisa alguma, nem comeriam, nem beberiam água.','É um jejum coletivo que envolvia até os animais da cidade.','texto_biblico',180),
('jonas','Jonas',4,'Segundo Jonas 4:6, como Jonas reagiu ao receber a sombra da planta preparada por Deus?','facil','Ficou indiferente','Alegrou-se muito','Ficou ainda mais irado','Destruiu a planta com raiva','B','Jonas 4:6 relata que Jonas se alegrou muito por causa da planta que lhe dava sombra e o livrava do seu mal-estar.','É um momentâneo alívio antes da planta ser destruída no dia seguinte.','texto_biblico',181),
('jonas','Jonas',1,'Segundo Jonas 1:5, o que os marinheiros fizeram com a carga do navio durante a tempestade?','facil','Guardaram-na com mais cuidado ainda','Lançaram-na ao mar para aliviar o peso','Venderam-na assim que chegaram a terra','Dividiram-na entre si como pagamento','B','Jonas 1:5 relata que os marinheiros, apavorados, lançaram ao mar a carga que estava no navio, para o aliviarem.','Foi uma das primeiras medidas desesperadas tomadas antes de descobrirem a causa da tempestade.','texto_biblico',182),
('jonas','Jonas',1,'Segundo Jonas 1:4, o que o Senhor fez assim que Jonas embarcou fugindo para Társis?','medio','Lançou um grande vento sobre o mar, causando forte tempestade','Enviou um anjo para acalmá-lo no navio','Fez o mar ficar completamente calmo','Enviou outro profeta atrás dele','A','Jonas 1:4 relata que o Senhor lançou um grande vento sobre o mar, e fez-se uma tão grande tempestade que o navio estava a ponto de se despedaçar.','É a resposta divina imediata à fuga do profeta.','texto_biblico',183),
('jonas','Jonas',1,'Segundo Jonas 1:6, o que o capitão do navio pediu a Jonas ao encontrá-lo dormindo durante a tempestade?','medio','Que assumisse o comando do navio','Que se levantasse e invocasse o seu deus','Que ajudasse a remar com mais força','Que revelasse seu verdadeiro nome','B','Jonas 1:6 relata que o capitão o encontrou dormindo e disse: "Que tens, ó dorminhoco? Levanta-te, e invoca o teu Deus".','É uma cena irônica: um capitão pagão repreendendo o profeta adormecido.','texto_biblico',184),
('jonas','Jonas',1,'Por que os marinheiros lançaram sortes, segundo Jonas 1:7?','medio','Para determinar o destino da viagem','Para decidir quem ficaria com a carga do navio','Para escolher um novo capitão','Para saber por causa de quem vinha aquele mal','D','Jonas 1:7 relata que lançaram sortes para saber por causa de quem lhes vinha aquele mal, e a sorte caiu sobre Jonas.','Era uma prática comum na antiguidade para buscar respostas divinas.','texto_biblico',185),
('jonas','Jonas',1,'Antes de lançar Jonas ao mar, o que os marinheiros tentaram fazer, segundo Jonas 1:13?','medio','Negociar com Jonas por sua vida','Oferecer Jonas em sacrifício imediatamente','Abandonar o navio em botes salva-vidas','Remar com força para voltar à terra firme','D','Jonas 1:13 relata que os homens remaram fortemente para voltar à terra, mas não conseguiram, pois o mar se embravecia mais e mais.','Mostra a relutância inicial dos marinheiros em lançar Jonas ao mar.','texto_biblico',186),
('jonas','Jonas',2,'Na oração de Jonas em Jonas 2:5, com que imagens ele descreve sua situação nas profundezas?','medio','Um deserto seco e uma fome extrema','Águas cercando-o até a alma e ervas enroladas à cabeça','Um exército inimigo cercando-o em terra','Uma multidão de pessoas zombando dele','B','Jonas 2:5 descreve: "As águas me cercaram até a alma, o abismo me rodeou, ervas se enrolaram à minha cabeça".','É uma descrição poética da experiência de quase afogamento.','texto_biblico',187),
('jonas','Jonas',2,'Segundo Jonas 2:6, até onde Jonas relata ter descido antes de Deus resgatá-lo?','medio','Até uma ilha distante','Ao topo das montanhas mais altas','Aos fundamentos dos montes','Até a cidade de Nínive diretamente','C','Jonas 2:6 declara: "Desci aos fundamentos dos montes; a terra com os seus ferrolhos se fechou sobre mim para sempre; mas tu, Senhor, meu Deus, fizeste subir a minha vida da cova".','É a imagem mais profunda de descida usada na oração de Jonas.','texto_biblico',188),
('jonas','Jonas',2,'Como termina a oração de Jonas dentro do peixe, segundo Jonas 2:9?','medio','Prometendo sacrificar com louvor e pagar o que votou','Pedindo para nunca mais ser enviado a Nínive','Exigindo a destruição imediata dos ninivitas','Recusando-se a cumprir qualquer voto','A','Jonas 2:9 conclui: "Mas eu te oferecerei sacrifícios com voz de louvor, pagarei o que votei. A salvação vem do Senhor".','É a resolução da crise espiritual de Jonas antes de ser vomitado na praia.','texto_biblico',189),
('jonas','Jonas',3,'Segundo o decreto do rei em Jonas 3:7-8, o que nem homens nem animais deveriam fazer em Nínive?','medio','Dormir durante o dia','Comer nem beber água','Sair de suas casas','Falar uns com os outros','B','Jonas 3:7-8 relata o decreto: que nem homens nem animais, nem manadas nem rebanhos, provassem coisa alguma, nem comessem, nem bebessem água.','É um jejum absoluto decretado por toda a cidade.','texto_biblico',190),
('jonas','Jonas',3,'Além do jejum, o que mais o rei de Nínive ordena ao povo em Jonas 3:8?','medio','Que reconstruíssem os muros da cidade','Que clamassem fortemente a Deus e se convertessem do mau caminho','Que pagassem tributo a Israel','Que expulsassem todos os estrangeiros','B','Jonas 3:8 ordena que clamem fortemente a Deus, e se convertam, cada um do seu mau caminho e da violência que há em suas mãos.','Mostra que o arrependimento devia incluir mudança de comportamento, não só rituais.','texto_biblico',191),
('jonas','Jonas',3,'Qual era a esperança do rei de Nínive ao decretar o jejum, segundo Jonas 3:9?','medio','"Quem sabe se Deus se arrependerá... e não pereceremos?"','Que Jonas fosse recompensado com riquezas','Que a cidade se tornasse ainda mais poderosa','Que outros profetas viessem confirmar a mensagem','A','Jonas 3:9 registra a esperança condicional do rei: "Quem sabe se ainda se arrependerá Deus, e se apartará do furor da sua ira, e não pereceremos?".','É uma expressão de humildade diante da incerteza sobre a misericórdia divina.','texto_biblico',192),
('jonas','Jonas',3,'Segundo Jonas 3:10, como Deus respondeu às obras dos ninivitas?','medio','Viu que se converteram do seu mau caminho e se arrependeu do mal que anunciara','Ignorou totalmente o esforço deles','Destruiu a cidade mesmo assim, por já ter decidido','Exigiu mais quarenta dias de jejum','A','Jonas 3:10 relata que Deus viu as obras deles, que se converteram do seu mau caminho, e se arrependeu do mal que tinha dito lhes faria.','É o clímax da narrativa de arrependimento e misericórdia no livro de Jonas.','texto_biblico',193),
('jonas','Jonas',4,'Segundo Jonas 4:2, o que Jonas confessa sobre o caráter de Deus, revelando a verdadeira razão de sua fuga inicial?','medio','Que Deus é indiferente ao destino das nações','Que Deus é gracioso, compassivo e tardio em irar-se','Que Deus só perdoa israelitas','Que Deus nunca muda de plano, seja qual for a situação','B','Jonas 4:2 registra a queixa de Jonas: "sabia eu que és Deus gracioso e compassivo, tardio em irar-te e grande em benignidade, e que te arrependes do mal".','Revela que Jonas fugiu justamente porque temia que Deus perdoasse Nínive.','texto_biblico',194),
('jonas','Jonas',1,'Segundo Jonas 1:5, o que cada um dos marinheiros pagãos fez individualmente durante a tempestade, antes de descobrirem a causa?','dificil','Cada um culpou Jonas imediatamente','Cada um clamou ao seu próprio deus','Cada um pulou ao mar por conta própria','Cada um se escondeu em silêncio absoluto','B','Jonas 1:5 relata que os marinheiros temeram e clamaram cada um ao seu deus, além de lançarem a carga ao mar.','Mostra o politeísmo comum entre marinheiros de diferentes origens na época.','texto_biblico',195),
('jonas','Jonas',2,'Segundo Jonas 2:4, o que Jonas pensou inicialmente ao ser lançado ao mar, antes de expressar esperança?','dificil','Que morreria sem nenhuma dor','Que logo seria resgatado por outro navio','Que o mar o levaria de volta a Társis','Que tinha sido lançado de diante dos olhos de Deus','D','Jonas 2:4 registra: "E eu disse: Lançado estou de diante dos teus olhos; todavia ainda olharei para o teu santo templo", uma mistura de desespero e esperança.','Mostra a complexidade emocional da oração de Jonas dentro do peixe.','texto_biblico',196),
('jonas','Jonas',2,'Segundo Jonas 2:8, o que Jonas afirma sobre os que dão atenção a vaidades e mentiras?','dificil','Abandonam a sua própria misericórdia','Se tornam mais sábios que os outros','Recebem o dobro de bênçãos','Nunca enfrentam dificuldades na vida','A','Jonas 2:8 declara: "Os que se apegam a vaidades falsas abandonam a sua própria misericórdia", uma reflexão sobre idolatria em meio à sua própria oração.','É uma crítica implícita à idolatria dos marinheiros pagãos e das nações.','texto_biblico',197),
('jonas','Jonas',4,'Segundo Jonas 4:2, qual foi a verdadeira razão pela qual Jonas fugiu para Társis desde o início da narrativa?','dificil','Ele sabia que Deus perdoaria Nínive se o povo se arrependesse','Ele tinha medo físico dos ninivitas','Ele não sabia falar a língua de Nínive','Ele queria visitar Társis por motivos pessoais','A','Jonas 4:2 revela que ele fugiu antes porque sabia que Deus é gracioso e compassivo, e temia que perdoasse Nínive, inimiga histórica de Israel.','É a chave teológica que explica toda a atitude de Jonas ao longo do livro.','texto_biblico',198),
('jonas','Jonas',4,'O que Deus enviou no dia seguinte para destruir a planta que dava sombra a Jonas, segundo Jonas 4:7?','dificil','Um verme','Um forte vento do mar','Uma nova tempestade','Um enxame de gafanhotos','A','Jonas 4:7 relata que Deus preparou um verme, ao subir a alva do dia seguinte, e ele feriu a planta, que se secou.','É o segundo elemento natural que Deus "prepara" no capítulo 4, depois da planta.','texto_biblico',199),
('jonas','Jonas',4,'Além do verme e do sol causticante, o que mais Deus preparou contra Jonas, intensificando seu sofrimento, segundo Jonas 4:8?','dificil','Um vento oriental abrasador','Uma nova tempestade no mar','Um segundo grande peixe','Uma chuva de granizo','A','Jonas 4:8 relata que Deus preparou um vento oriental abrasador, e o sol feriu a cabeça de Jonas, de modo que desmaiava e desejava morrer.','É o terceiro elemento natural usado por Deus para confrontar a atitude de Jonas.','texto_biblico',200),
('miqueias','Miquéias',1,'De onde era Miquéias?','facil','Jericó','Tiro','Moresete','Belém','C','Miquéias 1:1 identifica o profeta como morastita, isto é, de Moresete.','O nome do lugar aparece no início do livro.','texto_biblico',201),
('miqueias','Miquéias',5,'Qual cidade é mencionada como origem do governante prometido?','facil','Nínive','Hebrom','Jerusalém','Belém Efrata','D','Miquéias 5:2 menciona Belém Efrata como pequena entre os clãs de Judá.','É uma cidade pequena de Judá.','texto_biblico',202),
('miqueias','Miquéias',6,'Segundo Miquéias 6:8, o que o Senhor requer do ser humano?','medio','Oferecer milhares de cavalos','Construir grandes palácios','Conquistar outras nações','Praticar a justiça, amar a misericórdia e andar humildemente com Deus','D','Miquéias 6:8 resume o chamado ético em justiça, misericórdia e humildade diante de Deus.','São três verbos/ideias centrais.','texto_biblico',203),
('miqueias','Miquéias',4,'O que Miquéias 4:3 diz que as nações transformarão?','medio','Templos em palácios','Espadas em arados e lanças em foices','Arados em espadas','Rios em estradas','B','Miquéias 4:3 descreve a transformação de armas de guerra em instrumentos agrícolas.','A imagem é de paz e cultivo.','texto_biblico',204),
('miqueias','Miquéias',3,'Qual crítica Miquéias faz aos líderes que deveriam conhecer a justiça?','dificil','Eles reconstruíram Nínive','Eles aborreciam o bem e amavam o mal','Eles abandonaram a agricultura','Eles serviam como sacerdotes fiéis','B','Miquéias 3:1-3 acusa chefes e líderes de odiar o direito e praticar violência contra o povo.','A crítica é dirigida aos líderes de Israel.','texto_biblico',205),
('miqueias','Miquéias',2,'Contra quem é pronunciado o "ai" em Miquéias 2:1?','facil','Os que maquinam a iniquidade em suas camas','As crianças de Judá','Os pastores fiéis','Os estrangeiros pobres','A','Miquéias 2:1 denuncia os que planejam o mal durante a noite e o praticam pela manhã.','O planejamento do mal ocorre à noite.','texto_biblico',206),
('miqueias','Miquéias',7,'O que Miquéias declara em 7:8 mesmo depois de cair?','facil','Fugirei para sempre','Desistirei','Levantar-me-ei','Esconder-me-ei','C','Miquéias 7:8 expressa confiança: ainda que eu caia, levantar-me-ei.','É uma declaração de esperança e confiança.','texto_biblico',207),
('miqueias','Miquéias',7,'Segundo Miquéias 7:19, o que Deus faz com os pecados do seu povo?','medio','Reparte-os entre as nações','Transforma-os em ouro','Lança-os nas profundezas do mar','Guarda-os para sempre','C','Miquéias 7:19 descreve o perdão de Deus como lançar os pecados nas profundezas do mar.','É uma imagem de perdão completo e definitivo.','texto_biblico',208),
('miqueias','Miquéias',3,'Em contraste com falsos profetas, do que Miquéias 3:8 diz estar cheio?','medio','De sabedoria humana apenas','Do poder do Espírito do Senhor','De exércitos','De riquezas materiais','B','Miquéias 3:8 afirma que o profeta está cheio do poder do Espírito do Senhor, de juízo e de força para denunciar o pecado.','É uma afirmação de autoridade profética genuína.','texto_biblico',209),
('miqueias','Miquéias',1,'Durante o reinado de quais reis de Judá Miquéias profetizou, segundo Miquéias 1:1?','dificil','Jotão, Acaz e Ezequias','Herodes e Augusto','Saul, Davi e Salomão','Nabucodonosor e Ciro','A','Miquéias 1:1 situa o ministério do profeta nos dias de Jotão, Acaz e Ezequias, reis de Judá.','São três reis de Judá do período pré-exílico.','texto_biblico',210),
('miqueias','Miquéias',1,'Segundo Miquéias 1:1, sobre quais duas cidades principais recai a profecia do livro?','facil','Damasco e Edom','Nínive e Babilônia','Tiro e Sidom','Samaria e Jerusalém','D','Miquéias 1:1 apresenta a visão que ele teve a respeito de Samaria e Jerusalém, capitais de Israel e Judá.','São as capitais dos dois reinos, do Norte e do Sul.','texto_biblico',211),
('miqueias','Miquéias',1,'Segundo Miquéias 1:3, de onde o Senhor sai para vir julgar a terra?','facil','De um monte distante e desconhecido','Somente do templo de Jerusalém','Do meio do povo de Samaria','Do seu lugar, para pisar as alturas da terra','D','Miquéias 1:3 declara: "Porque eis que o Senhor sai do seu lugar, e descerá, e pisará sobre os altos da terra".','É uma imagem teofânica de Deus vindo em juízo.','texto_biblico',212),
('miqueias','Miquéias',1,'Segundo Miquéias 1:4, o que acontece com as montanhas diante da presença do Senhor?','facil','Derretem-se como cera diante do fogo','Ficam ainda mais altas e fortes','Permanecem completamente intactas','Se transformam em ouro','A','Miquéias 1:4 descreve: "E debaixo dele se derreterão os montes, e os vales se fenderão, como a cera diante do fogo".','É uma linguagem poética típica das teofanias no Antigo Testamento.','texto_biblico',213),
('miqueias','Miquéias',1,'Segundo Miquéias 1:8, como o próprio profeta reage pessoalmente ao anúncio da destruição?','facil','Anda descalço e nu, lamentando como um chacal','Organiza uma grande celebração','Permanece indiferente aos eventos','Foge imediatamente da região','A','Miquéias 1:8 relata: "Por isso lamentarei e uivarei; andarei despojado e nu; farei lamentação como os chacais".','É uma demonstração física e pública de luto profético.','texto_biblico',214),
('miqueias','Miquéias',2,'Contra quem é dirigido o "ai" de Miquéias 2:1-2?','facil','Os pobres que sofrem injustiça','Os sacerdotes fiéis do templo','Os que maquinam a iniquidade em suas camas e cobiçam campos alheios','Os estrangeiros que vivem em Judá','C','Miquéias 2:1-2 denuncia os que planejam o mal em suas camas e, ao amanhecer, cobiçam campos e casas e os tomam à força.','É uma crítica à opressão econômica planejada com antecedência.','texto_biblico',215),
('miqueias','Miquéias',2,'Segundo Miquéias 2:6, o que os ouvintes hostis dizem aos verdadeiros profetas de Deus?','facil','"Ensinai-nos a lei com mais detalhes"','"Profetizai mais e com mais força"','"Vinde habitar conosco em paz"','"Não profetizeis"','D','Miquéias 2:6 registra a rejeição do povo: "Não profetizeis, dizem eles, a estes; não profetizarão, e não os cobrirá a vergonha".','Mostra a resistência do povo em ouvir advertências proféticas verdadeiras.','texto_biblico',216),
('miqueias','Miquéias',3,'Segundo a acusação de Miquéias 3:1-3, do que os chefes de Jacó se "alimentam" metaforicamente?','facil','De produtos importados do Egito','Apenas de pão e água simples','De ofertas voluntárias dos ricos','Da carne do próprio povo, explorando-o','D','Miquéias 3:1-3 usa a imagem chocante de líderes que comem a carne do povo e lhe arrancam a pele, denunciando a exploração dos governantes.','É uma das denúncias mais fortes contra a liderança corrupta em todo o Antigo Testamento.','texto_biblico',217),
('miqueias','Miquéias',4,'Segundo Miquéias 4:1, o que acontecerá ao monte da casa do Senhor nos últimos dias?','facil','Será estabelecido e exaltado acima de todos os montes','Será destruído para sempre','Se tornará propriedade de outra nação','Permanecerá esquecido e sem visitantes','A','Miquéias 4:1 profetiza que, nos últimos dias, o monte da casa do Senhor será estabelecido no cume dos montes, e a ele afluirão os povos.','É uma visão paralela à encontrada em Isaías 2:2-4.','texto_biblico',218),
('miqueias','Miquéias',4,'Segundo Miquéias 4:4, debaixo do que cada pessoa se assentará em segurança, sem ser espantada?','facil','De um grande carvalho real','Da sua videira e da sua figueira','De uma tenda comunitária','Do teto do templo reconstruído','B','Miquéias 4:4 promete: "Mas cada um se assentará debaixo da sua videira, e debaixo da sua figueira, e não haverá quem os espante".','É uma imagem clássica de paz e prosperidade agrícola.','texto_biblico',219),
('miqueias','Miquéias',5,'Segundo Miquéias 5:5, o que o governante prometido, que viria de Belém, seria para o seu povo?','facil','Um novo legislador apenas','A paz','Um sacerdote permanente','Um conquistador de territórios distantes','B','Miquéias 5:5 declara sobre esse governante: "E este será a paz", ligando sua vinda à segurança do povo contra a Assíria.','Continua a profecia messiânica iniciada em Miquéias 5:2.','texto_biblico',220),
('miqueias','Miquéias',6,'Segundo Miquéias 6:4, quais líderes Deus enviou adiante do seu povo durante o êxodo do Egito?','facil','Davi e Salomão','Josué e Calebe','Moisés, Arão e Miriã','Elias e Eliseu','C','Miquéias 6:4 relembra: "Porque te fiz subir da terra do Egito... e enviei adiante de ti a Moisés, Arão e Miriã".','É parte do apelo de Deus lembrando sua fidelidade histórica ao povo.','texto_biblico',221),
('miqueias','Miquéias',7,'Apesar de todas as dificuldades descritas no capítulo 7, o que Miquéias decide fazer, segundo Miquéias 7:7?','facil','Abandonar o povo de Judá','Desistir completamente de sua fé','Olhar para o Senhor e esperar o Deus da sua salvação','Buscar refúgio em outra nação','C','Miquéias 7:7 declara pessoalmente: "Eu, porém, olharei para o Senhor, esperarei o Deus da minha salvação; o meu Deus me ouvirá".','É uma declaração pessoal de confiança em meio à corrupção generalizada descrita no capítulo.','texto_biblico',222),
('miqueias','Miquéias',1,'Segundo Miquéias 1:5, o que é identificado como "a transgressão de Jacó" e "os altos de Judá"?','medio','Egito e Assíria, respectivamente','Samaria e Jerusalém, respectivamente','Belém e Nazaré, respectivamente','Sinai e Carmelo, respectivamente','B','Miquéias 1:5 pergunta retoricamente: "Qual é a transgressão de Jacó? Não é Samaria? E quais são os altos de Judá? Não é Jerusalém?".','Identifica as capitais como o centro dos pecados de cada reino.','texto_biblico',223),
('miqueias','Miquéias',2,'Segundo Miquéias 2:2, o que os opressores fazem especificamente com campos e casas que cobiçam?','medio','Doam-nos aos pobres da cidade','Compram-nos por um preço justo','Devolvem-nos após breve uso','Tomam-nos à força, oprimindo o homem e a sua herança','D','Miquéias 2:2 denuncia: "cobiçam campos, e os arrebatam; e casas, e as tomam; assim oprimem o homem e a sua casa".','É uma acusação de abuso de poder para roubo de propriedades.','texto_biblico',224),
('miqueias','Miquéias',2,'Segundo Miquéias 2:12, a que Deus compara o remanescente de Israel que promete reunir?','medio','A sementes espalhadas ao vento','A águias voando livremente','A um exército pronto para a guerra','A ovelhas de Bozra, um rebanho no meio do curral','D','Miquéias 2:12 promete: "certamente ajuntarei a ti, ó Jacó, todo o teu resto; como ovelhas de Bozra, os ajuntarei".','É uma imagem pastoral de restauração e proteção.','texto_biblico',225),
('miqueias','Miquéias',3,'Segundo Miquéias 3:5, o que os falsos profetas fazem quando alguém não lhes dá comida?','medio','Pedem desculpas e seguem em frente','Oferecem-lhe uma bênção especial','Declaram guerra (santificam guerra) contra essa pessoa','Convidam-na para uma festa','C','Miquéias 3:5 denuncia profetas que clamam paz quando têm o que comer, mas declaram guerra contra quem não lhes põe nada na boca.','É uma crítica a uma profecia motivada por interesse financeiro.','texto_biblico',226),
('miqueias','Miquéias',3,'Segundo Miquéias 3:11, apesar de julgarem por suborno e ensinarem por interesse, o que os líderes ainda afirmam com falsa confiança?','medio','Que o Senhor está no meio deles e nenhum mal lhes sobrevirá','Que abandonarão o poder voluntariamente','Que merecem ser julgados com rigor','Que o povo deveria se rebelar contra eles','A','Miquéias 3:11 denuncia essa falsa segurança: "e ainda se encostam ao Senhor, dizendo: Não está o Senhor no meio de nós? Nenhum mal nos sobrevirá".','É um exemplo de religiosidade usada para encobrir corrupção.','texto_biblico',227),
('miqueias','Miquéias',3,'Segundo Miquéias 3:12, o que acontecerá a Sião e Jerusalém por causa da liderança corrupta descrita no capítulo?','medio','Se tornarão as cidades mais ricas do mundo','Serão fortificadas ainda mais contra invasores','Sião será lavrada como campo, e Jerusalém se tornará montão de pedras','Receberão um novo templo imediatamente','C','Miquéias 3:12 anuncia: "Sião será lavrada como um campo, Jerusalém se tornará em montões de pedras", por causa dos líderes corruptos denunciados antes.','Esse mesmo versículo é citado décadas depois em Jeremias 26:18.','texto_biblico',228),
('miqueias','Miquéias',4,'Segundo Miquéias 4:6-7, o que Deus promete fazer com "a que coxeava" e a que fora afastada?','medio','Enviá-la para o exílio permanente','Abandoná-la definitivamente ao seu destino','Ajuntá-la e fazer dela um remanescente forte','Puni-la com o dobro do sofrimento anterior','C','Miquéias 4:6-7 promete: "ajuntarei a que coxeava, e recolherei a que foi expulsa... e farei da coxa um remanescente".','É uma imagem de restauração para os mais fracos e vulneráveis do povo.','texto_biblico',229),
('miqueias','Miquéias',5,'Segundo Miquéias 5:7, a que o resto de Jacó é comparado no meio de muitos povos?','medio','A um rio seco e improdutivo','A um leão feroz entre ovelhas','A um exército invencível','Ao orvalho do Senhor e a chuvinhas sobre a erva','D','Miquéias 5:7 declara: "E o resto de Jacó estará no meio de muitos povos, como orvalho do Senhor, como chuvinhas sobre a erva".','É uma imagem de bênção silenciosa e vivificante entre as nações.','texto_biblico',230),
('miqueias','Miquéias',6,'Segundo Miquéias 6:6-7, quais ofertas exageradas o povo pergunta retoricamente se agradariam a Deus?','medio','Somente orações silenciosas','Apenas um punhado de trigo','Milhares de carneiros, rios de azeite, ou até o primogênito','Nenhuma oferta, apenas boas intenções','C','Miquéias 6:6-7 questiona: "agradar-me-ei eu de milhares de carneiros, ou de dez mil ribeiros de azeite? Darei o meu primogênito pela minha transgressão?".','Prepara o terreno para a resposta central do verso 8 sobre o que Deus realmente requer.','texto_biblico',231),
('miqueias','Miquéias',6,'Segundo Miquéias 6:11, qual prática comercial desonesta Deus reprova entre o povo?','medio','Balanças e pesos enganosos','A cobrança de impostos justos','O comércio com nações estrangeiras','O uso de moedas estrangeiras','A','Miquéias 6:11 pergunta: "Seria eu limpo com balanças falsas e com um saco de pesos enganosos?", denunciando fraude comercial.','É uma crítica recorrente nos profetas contra a desonestidade no comércio.','texto_biblico',232),
('miqueias','Miquéias',7,'Segundo Miquéias 7:5-6, em quem o profeta adverte que não se deve confiar totalmente naqueles dias corrompidos?','medio','Apenas nos governantes estrangeiros','Apenas em estrangeiros desconhecidos','Somente nos sacerdotes do templo','No amigo, no príncipe e até em parentes próximos','D','Miquéias 7:5 adverte: "Não creiais no amigo, nem confieis no príncipe; guarda as portas da tua boca daquela que dorme em teu seio".','Mostra a desintegração das relações de confiança mais básicas na sociedade.','texto_biblico',233),
('miqueias','Miquéias',7,'Segundo Miquéias 7:6, que conflito familiar é citado como sinal extremo de corrupção social?','medio','Os irmãos sempre se ajudam mutuamente','O filho despreza o pai, e a filha se levanta contra a mãe','As famílias se tornam mais unidas do que nunca','Os avós assumem toda a liderança social','B','Miquéias 7:6 descreve: "Porque o filho despreza o pai, a filha se levanta contra a mãe... os inimigos do homem são os da sua própria casa".','Esse versículo é citado por Jesus em Mateus 10:35-36.','texto_biblico',234),
('miqueias','Miquéias',1,'Segundo Miquéias 1:10-12, qual recurso literário o profeta usa ao mencionar cidades como Gate e Bete-Le-Afra?','dificil','Uma lista neutra de cidades sem significado especial','Jogos de palavras (trocadilhos) com os nomes das cidades para anunciar julgamento','Nomes inventados sem relação com lugares reais','Uma ordem cronológica de conquistas passadas','B','Miquéias 1:10-12 usa trocadilhos sonoros com nomes de cidades (como Bete-Le-Afra, que soa como "casa da poeira") para anunciar seus respectivos destinos de julgamento.','É um recurso poético hebraico difícil de perceber apenas na tradução.','texto_biblico',235),
('miqueias','Miquéias',2,'Segundo Miquéias 2:13, quem "rompe o caminho" adiante do remanescente reunido por Deus?','dificil','Nenhum líder; eles avançam sozinhos','Um general humano designado','Um anjo sem identificação específica','O próprio Senhor, à frente deles como rei','D','Miquéias 2:13 declara: "o que rompe o caminho sobe adiante deles... e o seu rei passará adiante deles, e à frente deles o Senhor".','É uma imagem de libertação liderada diretamente por Deus.','texto_biblico',236),
('miqueias','Miquéias',4,'Segundo Miquéias 4:10, a que a cidade de Sião é comparada em seu sofrimento antes da libertação prometida?','dificil','A uma mulher com dores de parto','A uma árvore sem frutos','A um exército derrotado sem esperança','A um rio completamente seco','A','Miquéias 4:10 descreve: "Sofre dores, e trabalha por dar à luz, ó filha de Sião, como a que está de parto... porém ali o Senhor te livrará".','É uma imagem comum nos profetas para descrever sofrimento seguido de libertação.','texto_biblico',237),
('miqueias','Miquéias',5,'Segundo Miquéias 5:10-12, o que Deus promete destruir de Israel como parte de sua purificação?','dificil','Unicamente os templos pagãos vizinhos','Somente os ídolos de metal','Apenas as fortalezas da Assíria','Cavalos, carros de guerra, cidades e feitiçarias','D','Miquéias 5:10-12 anuncia a destruição dos cavalos, carros, cidades, fortalezas e feitiçarias de Israel, removendo fontes de confiança que não em Deus.','Mostra que a purificação envolveria até recursos militares e práticas ocultas.','texto_biblico',238),
('miqueias','Miquéias',6,'Segundo Miquéias 6:3, qual pergunta comovente Deus faz ao seu povo logo no início de sua controvérsia?','dificil','"Que te fiz, e em que te ofendi? Responde-me"','"Quem te libertou do Egito, afinal?"','"Por que me abandonaste tão cedo?"','"Onde estavas quando criei o mundo?"','A','Miquéias 6:3 registra o apelo divino: "Povo meu, que te tenho eu feito? E em que te enfadei? Testifica contra mim".','É um dos apelos mais pessoais e emocionais de Deus a Israel em todo o livro.','texto_biblico',239),
('miqueias','Miquéias',7,'Segundo Miquéias 7:18, qual pergunta retórica resume a teologia central da misericórdia de Deus no livro?','dificil','"Quem pode escapar do juízo final?"','"Quem é Deus semelhante a ti, que perdoa a iniquidade?"','"Quantos pecados Deus pode suportar?"','"Quem construirá o novo templo?"','B','Miquéias 7:18 declara: "Quem é Deus semelhante a ti, que perdoas a iniquidade e te esqueces da transgressão do resto da tua herança?".','É considerado o ponto culminante teológico de todo o livro de Miquéias, inclusive um jogo com o próprio significado do nome Miquéias ("quem é como Deus?").','texto_biblico',240),
('naum','Naum',1,'Contra qual cidade é dirigida a profecia de Naum?','facil','Damasco','Tiro','Nínive','Jerusalém','C','Naum 1:1 apresenta a sentença contra Nínive.','É a capital assíria.','texto_biblico',241),
('naum','Naum',1,'Como Naum descreve o Senhor em relação à ira?','facil','Fraco e indeciso','Sempre irado sem misericórdia','Tardio em irar-se e grande em poder','Indiferente ao mal','C','Naum 1:3 afirma que o Senhor é tardio em irar-se e grande em poder, sem deixar impune o culpado.','O verso combina paciência e justiça.','texto_biblico',242),
('naum','Naum',2,'Qual imagem aparece na descrição da queda de Nínive?','medio','Carros correndo pelas ruas e portas dos rios abertas','Uma seca no deserto','Um templo sendo reconstruído','Um exército chegando de Jerusalém','A','Naum 2 descreve de forma poética o ataque e a queda de Nínive, incluindo carros e a abertura das portas dos rios.','A cidade está sob ataque.','texto_biblico',243),
('naum','Naum',3,'Por que Nínive é chamada de cidade sanguinária?','medio','Por ser pequena','Por sua violência, mentira e exploração','Por seus muitos jardins','Por sua riqueza agrícola','B','Naum 3:1 acusa Nínive de sangue, mentira, roubo e violência.','A expressão aparece no início do capítulo 3.','texto_biblico',244),
('naum','Naum',3,'Qual é o destino anunciado para Nínive?','dificil','Ser reconstruída como capital de Judá','Ser destruída e não ter cura para sua ferida','Receber um novo templo','Governar o Egito','B','Naum 3:7-19 descreve a queda de Nínive como irreversível diante das nações.','O final do livro não anuncia restauração de Nínive.','texto_biblico',245),
('naum','Naum',1,'Como Naum 1:7 descreve o Senhor para os que confiam nele?','facil','Bom e fortaleza no dia da angústia','Ausente em tempos de crise','Distante e indiferente','Fraco diante dos inimigos','A','Naum 1:7 afirma que o Senhor é bom, fortaleza no dia da angústia, e conhece os que nele confiam.','É um verso de consolo em meio ao anúncio de juízo.','texto_biblico',246),
('naum','Naum',1,'O que Naum 1:15 anuncia que chega sobre os montes?','facil','Uma nuvem de gafanhotos','Um novo exército assírio','Os pés do que anuncia a paz','Uma seca prolongada','C','Naum 1:15 anuncia os pés do mensageiro de boas novas, que proclama a paz após a queda de Nínive.','É uma imagem semelhante à de Isaías 52:7.','texto_biblico',247),
('naum','Naum',3,'A que Nínive é comparada em Naum 3:4 por causa de suas seduções?','medio','Uma noiva fiel','Uma cidade santa','Uma mãe protetora','Uma prostituta encantadora e mestra de feitiços','D','Naum 3:4 acusa Nínive de seduzir nações como uma prostituta encantadora, mestra de feitiçarias.','A acusação envolve sedução e engano.','texto_biblico',248),
('naum','Naum',2,'A que Nínive é comparada em Naum 2:11-12, por causa de sua violência conquistadora?','medio','Um templo sagrado','Um covil de leões','Uma torre pacífica','Um jardim florido','B','Naum 2:11-12 compara Nínive a um covil de leões, cheio de presas, símbolo de sua violência contra outras nações.','É uma comparação com um animal predador feroz.','texto_biblico',249),
('naum','Naum',1,'O que Deus decreta contra a descendência do rei assírio em Naum 1:14?','dificil','Que reconstruiria o templo de Jerusalém','Que se tornaria aliado de Judá','Que seria coroado rei universal','Que seu nome não teria mais descendência','D','Naum 1:14 anuncia que do nome do rei assírio não haveria mais semeadura, e os ídolos de sua casa seriam destruídos.','Envolve o fim da linhagem e dos ídolos do rei.','texto_biblico',250),
('naum','Naum',1,'Como Naum 1:2 descreve a Deus logo na abertura do livro?','facil','Deus zeloso e vingador','Deus distante e indiferente','Deus apenas misericordioso, sem juízo','Deus silencioso diante do mal','A','Naum 1:2 declara: "O Senhor é Deus zeloso e vingador; o Senhor é vingador e cheio de indignação".','É a abertura solene que define o tom de julgamento do livro contra Nínive.','texto_biblico',251),
('naum','Naum',1,'Segundo Naum 1:4, o que acontece a Basã, Carmelo e a flor do Líbano diante da repreensão de Deus?','facil','Murcham','Florescem ainda mais','Permanecem intocados','Se multiplicam rapidamente','A','Naum 1:4 descreve Deus repreendendo o mar e secando-o, fazendo Basã, Carmelo e a flor do Líbano murcharem.','Eram regiões conhecidas pela fertilidade e beleza natural.','texto_biblico',252),
('naum','Naum',1,'Segundo Naum 1:6, quem consegue parar diante da indignação de Deus?','facil','Apenas os reis poderosos','Ninguém','Somente os sacerdotes consagrados','Qualquer exército bem preparado','B','Naum 1:6 pergunta retoricamente: "Quem parará diante da sua indignação? E quem persistirá diante do ardor da sua ira?".','É uma afirmação da absoluta supremacia do poder divino.','texto_biblico',253),
('naum','Naum',1,'Segundo Naum 1:10, a que a condição de Nínive é comparada, mostrando sua destruição total?','facil','A uma fortaleza inabalável','A uma árvore frondosa e resistente','A espinhos enredados e restolho seco, prontos para serem consumidos','A um exército em plena vitória','C','Naum 1:10 declara: "Porque, ainda que se enredem como espinhos, e se embriaguem como beberrões, serão consumidos como restolho seco".','É uma imagem de fragilidade apesar da aparente força.','texto_biblico',254),
('naum','Naum',1,'Segundo Naum 1:13, o que Deus promete quebrar sobre o povo oprimido pela Assíria?','facil','O jugo do opressor','As muralhas da própria Nínive','Os templos pagãos de Judá','Os laços de aliança com o Egito','A','Naum 1:13 promete: "Mas agora quebrarei o seu jugo de sobre ti, e romperei as tuas ataduras".','É uma palavra de esperança e libertação para o povo oprimido.','texto_biblico',255),
('naum','Naum',2,'Segundo Naum 2:2, o que o Senhor promete restituir ao seu povo?','facil','A excelência (glória) de Jacó','As riquezas da Assíria diretamente','Um novo templo já reconstruído','Territórios do Egito','A','Naum 2:2 declara: "Porque o Senhor restitui a excelência de Jacó, como a excelência de Israel".','É uma promessa de restauração da honra de Israel após o julgamento de seu opressor.','texto_biblico',256),
('naum','Naum',2,'Segundo Naum 2:3-4, como são descritos os escudos e carros dos atacantes que cercam Nínive?','facil','Vermelhos, como fogo e tochas','Verdes como a vegetação do Líbano','Brancos como neve pura','Invisíveis, sem nenhuma cor definida','A','Naum 2:3-4 descreve escudos vermelhos, homens de guerra vestidos de escarlata, e carros como tochas ardentes correndo pelas ruas.','É uma cena vívida do exército que destruiria Nínive.','texto_biblico',257),
('naum','Naum',2,'Segundo Naum 2:9, o que os invasores são convocados a fazer com as riquezas de Nínive conquistada?','facil','Devolver tudo aos moradores','Saquear prata e ouro em abundância','Queimar tudo sem levar nada','Distribuir igualmente entre os pobres da cidade','B','Naum 2:9 convida: "Saqueai a prata, saqueai o ouro; e não há fim das preciosidades".','Mostra a riqueza acumulada por Nínive, agora tomada por seus conquistadores.','texto_biblico',258),
('naum','Naum',2,'Segundo Naum 2:10, como fica Nínive descrita depois do saque?','facil','Sem nenhuma mudança visível','Mais rica do que nunca','Reconstruída rapidamente','Vazia, esvaziada e devastada','D','Naum 2:10 declara: "Ela está vazia, e esvaziada, e devastada; e o coração se derrete, e os joelhos ferem-se um contra o outro".','É a imagem final da desolação completa da cidade.','texto_biblico',259),
('naum','Naum',3,'Como o capítulo 3 de Naum começa a descrever Nínive, segundo Naum 3:1?','facil','"Ai da cidade sanguinária, cheia de mentiras e de rapina!"','"Bem-aventurada a cidade fiel e justa"','"Ninguém pode acusar Nínive de nada"','"Nínive será poupada de todo julgamento"','A','Naum 3:1 abre o capítulo com a denúncia: "Ai da cidade sanguinária! É toda cheia de mentiras e de rapina".','É a acusação central que resume todo o capítulo final do livro.','texto_biblico',260),
('naum','Naum',3,'Segundo Naum 3:3, o que caracteriza a cena de batalha descrita contra Nínive?','facil','Uma procissão festiva pelas ruas','Um silêncio completo, sem nenhuma luta','Apenas negociações diplomáticas pacíficas','Cavaleiro montado, espada reluzente e multidão de mortos','D','Naum 3:3 descreve intensamente: "cavaleiro que monta, e espada reluzente, e lança cintilante, e multidão de mortos".','É uma das descrições de guerra mais vívidas entre os profetas menores.','texto_biblico',261),
('naum','Naum',3,'Segundo Naum 3:19, qual é a reação de outras nações ao ouvirem a notícia da queda de Nínive?','facil','Baterão palmas, pois todas sofreram sua maldade constante','Lamentarão profundamente a perda de uma aliada','Tentarão reconstruir a cidade imediatamente','Ficarão indiferentes ao acontecimento','A','Naum 3:19 conclui: "Todos os que ouvirem a notícia de ti baterão palmas sobre ti, porque sobre quem não passou continuamente a tua malícia?".','É a conclusão do livro, mostrando o alívio geral das nações oprimidas pela Assíria.','texto_biblico',262),
('naum','Naum',1,'Segundo Naum 1:8, de que forma Deus promete acabar de vez com Nínive?','medio','Com uma seca prolongada','Com uma inundação transbordante','Com uma praga de gafanhotos','Com um terremoto isolado','B','Naum 1:8 declara: "mas com uma inundação transbordante ele acabará de vez com o lugar dela, e as trevas perseguirão os seus inimigos".','É consistente com o papel histórico das enchentes do rio Tigre na queda real de Nínive.','texto_biblico',263),
('naum','Naum',1,'Segundo Naum 1:9, o que Deus responde a quem maquina mal contra ele?','medio','Aguardará mais mil anos antes de agir','Perdoará imediatamente sem nenhuma consequência','Enviará apenas uma advertência verbal','Fará consumação total, sem repetir a angústia uma segunda vez','D','Naum 1:9 declara: "Que pensais vós contra o Senhor? Ele mesmo fará consumação; a angústia não se levantará duas vezes".','Mostra a certeza e definitividade do julgamento anunciado contra a Assíria.','texto_biblico',264),
('naum','Naum',1,'Segundo Naum 1:11, de onde saiu aquele que maquinava mal contra o Senhor?','medio','Do Egito, um faraó rebelde','Do meio do próprio povo de Judá','De Nínive, um conselheiro de Belial','Da Babilônia, um general ambicioso','C','Naum 1:11 declara: "De ti saiu um que maquinava mal contra o Senhor, um conselheiro de Belial", provavelmente referência a um líder assírio hostil.','É uma acusação direta contra a liderança de Nínive.','texto_biblico',265),
('naum','Naum',2,'Segundo Naum 2:5-6, o que acontece quando os nobres de Nínive tropeçam correndo aos muros?','medio','As muralhas se tornam ainda mais fortes','A cidade se torna impossível de conquistar','Um exército aliado chega para socorrê-los','As portas dos rios se abrem e o palácio se derrete','D','Naum 2:5-6 descreve o caos da defesa: nobres tropeçam ao correr para os muros, as portas dos rios se abrem, e o palácio se derrete de pavor.','É uma cena de colapso total das defesas da cidade.','texto_biblico',266),
('naum','Naum',2,'Segundo Naum 2:7, o que acontece com Huzabe (associada à realeza ou à própria cidade personificada)?','medio','É levada cativa, e suas servas gemem como pombas','É coroada rainha de um novo império','Permanece intocada durante todo o cerco','Se torna aliada dos invasores','A','Naum 2:7 relata que "Huzabe é levada cativa... e as suas servas a acompanham, gemendo como pombas, batendo em seus peitos".','É uma imagem de humilhação da realeza ou da cidade personificada como mulher.','texto_biblico',267),
('naum','Naum',2,'Segundo Naum 2:13, quem declara estar "contra" Nínive, e o que promete queimar?','medio','O rei da Babilônia; promete queimar apenas os arquivos','Um general assírio rival; promete queimar templos','O Senhor dos Exércitos; promete queimar os carros dela','Um profeta anônimo; promete queimar as leis','C','Naum 2:13 declara: "Eis que eu estou contra ti, diz o Senhor dos Exércitos, e queimarei os teus carros, e a espada devorará os teus leõezinhos".','É a assinatura divina sobre toda a sentença de destruição contra Nínive.','texto_biblico',268),
('naum','Naum',3,'Segundo Naum 3:5-6, de que forma Deus promete humilhar publicamente Nínive, comparada a uma prostituta?','medio','Coroando-a publicamente como rainha das nações','Descobrindo suas saias sobre o rosto e mostrando sua nudez às nações','Oferecendo-lhe riquezas para se render em paz','Enviando embaixadores para negociar sua rendição','B','Naum 3:5-6 anuncia: "eis que estou contra ti... descobrirei as tuas saias sobre o teu rosto, e mostrarei às nações a tua nudez", uma humilhação pública típica contra cidades hostis.','É uma linguagem forte de julgamento que aparece também em outros profetas contra cidades corruptas.','texto_biblico',269),
('naum','Naum',3,'Segundo Naum 3:8, com qual outra grande cidade antiga Nínive é comparada, sugerindo que sofreria o mesmo destino de queda?','medio','Jope, na costa do Mediterrâneo','Babilônia, na Mesopotâmia','Tebas (No-Amom), no Egito','Damasco, na Síria','C','Naum 3:8 pergunta: "És tu melhor do que Tebas, que estava situada entre os rios... e que foi levada em cativeiro?", pois essa cidade egípcia também havia caído.','Tebas (No-Amom) era uma capital egípcia conquistada pela própria Assíria décadas antes.','texto_biblico',270),
('naum','Naum',3,'Segundo Naum 3:9, quais nações eram apoio e força de Tebas antes de sua queda, usada como exemplo para Nínive?','medio','Etiópia, Egito, Fute e Líbios','Apenas a Babilônia isoladamente','Somente tropas mercenárias gregas','Nenhuma; Tebas estava completamente isolada','A','Naum 3:9 lembra que a força ilimitada de Tebas incluía a Etiópia, o Egito, Fute e os líbios como ajudadores, mas ainda assim ela caiu.','Mostra que nem grandes alianças militares garantiram a sobrevivência de Tebas.','texto_biblico',271),
('naum','Naum',3,'Segundo Naum 3:13, o que é dito de forma humilhante sobre os guerreiros de Nínive?','medio','São descritos como guerreiros invencíveis','"Teu povo são mulheres no meio de ti", indicando fraqueza militar','Superam em número qualquer exército inimigo','Serão poupados por sua bravura excepcional','B','Naum 3:13 declara: "Eis que o teu povo no meio de ti são mulheres; as portas da tua terra estão de todo abertas aos teus inimigos".','É uma forma antiga e dura de descrever a perda total de capacidade defensiva.','texto_biblico',272),
('naum','Naum',3,'Segundo Naum 3:15-17, a que praga agrícola os príncipes e capitães de Nínive são comparados?','medio','A águias que dominam o céu sempre','A leões que nunca recuam de uma batalha','A gafanhotos que fogem assim que o sol nasce','A árvores que resistem a qualquer tempestade','C','Naum 3:17 compara os capitães de Nínive a gafanhotos que se acampam nas sebes em dia frio, mas fogem assim que o sol aparece, sem deixar rastro.','É uma imagem de fragilidade repentina apesar da aparência numerosa.','texto_biblico',273),
('naum','Naum',3,'Segundo Naum 3:18, o que é dito sobre os "pastores" (líderes) e o povo da Assíria no final do livro?','medio','Os pastores permanecem vigilantes para sempre','Os pastores dormitam, e o povo se espalha pelos montes sem quem o ajunte','O povo se reúne em uma nova capital fortificada','Os líderes são substituídos por reis ainda mais fortes','B','Naum 3:18 lamenta ao rei da Assíria: "Os teus pastores dormitam... o teu povo anda espalhado pelos montes, e não há quem o ajunte".','É a imagem final de um reino sem liderança e sem coesão, prestes a desaparecer.','texto_biblico',274),
('naum','Naum',1,'Segundo Naum 1:3, apesar de ser tardio em irar-se, o que também é afirmado sobre o caráter de Deus quanto ao culpado?','dificil','Que ele não inocentará o culpado de maneira nenhuma','Que ele sempre perdoa sem exceção','Que ele nunca julga ninguém definitivamente','Que ele ignora pecados pequenos','A','Naum 1:3 equilibra dois atributos: "O Senhor é tardio em irar-se, e grande em força, e ao culpado de maneira nenhuma tem por inocente".','Mostra que paciência divina não significa ausência de justiça.','texto_biblico',275),
('naum','Naum',2,'Segundo Naum 2:8, a que Nínive é comparada "desde os dias antigos", antes de sua queda repentina?','dificil','A uma fortaleza recém-construída','A um deserto árido, sempre vazio','A um tanque de águas, mas agora foge apressadamente','A uma cidade sem nenhuma história anterior','C','Naum 2:8 relata: "Nínive, desde os dias antigos, era como um tanque de águas; mas eles agora fogem", contrastando sua antiga estabilidade com o colapso repentino.','É uma imagem que destaca a reviravolta súbita no destino da cidade.','texto_biblico',276),
('naum','Naum',3,'Segundo Naum 3:4, qual motivo espiritual, além da violência, é apresentado para a queda de Nínive?','dificil','Suas feitiçarias e prostituições, que vendiam nações e povos','Sua recusa em pagar impostos ao Egito','Sua aliança proibida com Israel','Sua recusa em adorar deuses estrangeiros','A','Naum 3:4 acusa Nínive de ser "a graciosa prostituta, a mestra de feitiçarias, que vende nações com a sua prostituição, e famílias com as suas feitiçarias".','Liga a exploração política e comercial de Nínive a uma linguagem de corrupção espiritual.','texto_biblico',277),
('naum','Naum',3,'Segundo Naum 3:16, a que Naum compara os mercadores de Nínive, e o que acontece com eles no final?','dificil','São poucos, mas extremamente ricos e leais','São mais numerosos que as estrelas, mas o pulgão despoja e voa','Permanecem fiéis à cidade até o fim','Se tornam os novos governantes da região','B','Naum 3:16 descreve: "Multiplicaste os teus mercadores mais que as estrelas do céu; o pulgão estende as asas, e voa", uma imagem de riqueza que rapidamente desaparece.','É uma comparação irônica entre abundância comercial e fragilidade repentina.','texto_biblico',278),
('naum','Naum',3,'Segundo Naum 3:19, por que se afirma que não há cura para a ferida de Nínive?','dificil','Porque sua malícia (maldade) passou continuamente sobre todas as nações vizinhas','Porque nenhum médico da época conseguia tratá-la','Porque a cidade nunca teve recursos suficientes','Porque seus deuses a abandonaram sem explicação','A','Naum 3:19 declara: "Não há cura para a tua ferida; a tua chaga é grave... porque sobre quem não passou continuamente a tua malícia?".','É a conclusão que justifica moralmente toda a alegria das nações com a queda de Nínive.','texto_biblico',279),
('naum','Naum',1,'Segundo Naum 1:12, o que Deus promete acontecer aos assírios mesmo que estejam "em paz" e sejam numerosos?','dificil','Formarão um império eterno','Se tornarão ainda mais poderosos','Serão tosquiados e desaparecerão','Serão poupados por sua grande população','C','Naum 1:12 declara: "Ainda que estejam em paz, e sejam muitos, contudo serão tosquiados, e ele passará; ainda que te afligi, não te afligirei mais".','Mostra que nem a aparente estabilidade e número protegeriam a Assíria do julgamento.','texto_biblico',280),
('habacuque','Habacuque',1,'O que Habacuque faz principalmente no início do livro?','facil','Interpreta sonhos de Nabucodonosor','Foge para o Egito','Questiona a Deus sobre a violência e a injustiça','Constrói um altar','C','Habacuque começa apresentando perguntas e queixas sobre a violência e a aparente demora da justiça.','O livro tem forma de diálogo entre profeta e Deus.','texto_biblico',281),
('habacuque','Habacuque',2,'Qual frase famosa aparece em Habacuque 2:4?','facil','O Senhor é meu pastor','Tudo é vaidade','O justo viverá pela sua fé','Olho por olho','C','Habacuque 2:4 afirma: o justo viverá pela sua fé/fidelidade, conforme a tradução.','É uma frase central do livro.','texto_biblico',282),
('habacuque','Habacuque',2,'O que Deus manda Habacuque fazer com a visão?','medio','Escrevê-la claramente em tábuas','Entregá-la ao rei do Egito','Apagá-la','Escondê-la','A','Habacuque 2:2 ordena que a visão seja escrita claramente em tábuas para que possa ser lida.','A instrução é escrever a visão.','texto_biblico',283),
('habacuque','Habacuque',3,'Apesar da crise, como termina a oração de Habacuque?','medio','Com silêncio absoluto','Com alegria e confiança em Deus','Com uma coroação','Com uma fuga','B','Habacuque 3:17-19 reconhece a falta de frutos e rebanhos, mas afirma alegria no Senhor e confiança em Deus.','A alegria não depende da prosperidade.','texto_biblico',284),
('habacuque','Habacuque',1,'Qual povo Deus diz que levantará como instrumento de juízo?','dificil','Os filisteus','Os caldeus','Os egípcios','Os edomitas','B','Habacuque 1:6 identifica os caldeus como povo que Deus levantaria para executar juízo.','Caldeus é uma designação associada aos babilônios.','texto_biblico',285),
('habacuque','Habacuque',1,'Como começa o lamento de Habacuque no capítulo 1?','facil','Eis que o rei chegou vitorioso','O templo está reconstruído','Louvado seja o Senhor para sempre','Até quando, Senhor, clamarei e tu não ouvirás?','D','Habacuque 1:2 abre o livro com uma queixa sobre a violência e a aparente demora da resposta de Deus.','É uma pergunta sobre o tempo de espera.','texto_biblico',286),
('habacuque','Habacuque',3,'Com que imagem de força Habacuque 3:19 termina o livro?','facil','Uma frota poderosa','Um exército invencível','Um novo templo de ouro','Pés como os das cervas, andando nas alturas','D','Habacuque 3:19 declara que o Senhor é sua força e faz seus pés como os da cerva, capazes de andar sobre as alturas.','É uma comparação com um animal ágil em terrenos altos.','texto_biblico',287),
('habacuque','Habacuque',2,'O que Habacuque 2:14 promete que encherá a terra?','medio','As águas do dilúvio','O ouro das nações','O conhecimento da glória do Senhor','Os exércitos da Babilônia','C','Habacuque 2:14 promete que a terra se encherá do conhecimento da glória do Senhor, como as águas cobrem o mar.','É uma imagem de plenitude comparada à água do mar.','texto_biblico',288),
('habacuque','Habacuque',2,'Quantos "ais" (pronunciamentos de juízo) Habacuque declara contra o opressor no capítulo 2?','medio','Nenhum','Dez','Dois','Cinco','D','Habacuque 2:6-19 registra cinco declarações de "ai" contra a injustiça e a opressão do conquistador.','É uma série de acusações repetidas com a mesma palavra.','texto_biblico',289),
('habacuque','Habacuque',1,'Na segunda queixa de Habacuque (cap. 1), o que o incomoda sobre o uso dos caldeus por Deus?','dificil','Que Deus use um povo mais ímpio para julgar um povo menos ímpio','Que os caldeus sejam pobres','Que os caldeus adorem o Deus de Israel','Que os caldeus nunca vençam guerras','A','Habacuque 1:12-13 questiona como Deus, de olhos puros, pode usar os caldeus, mais perversos, para punir um povo menos ímpio.','É um questionamento sobre a justiça divina usando um instrumento moralmente pior.','texto_biblico',290),
('habacuque','Habacuque',1,'Segundo Habacuque 1:3-4, o que o profeta observa estar acontecendo em sua própria nação?','facil','Total paz e prosperidade','Violência, contenda e a lei se afrouxando','Um avivamento espiritual generalizado','Excesso de justiça e ordem social','B','Habacuque 1:3-4 lamenta: "Por que me fazes ver a iniquidade... a violência e a contenda estão diante de mim... por isso a lei se afrouxa".','É o pano de fundo da primeira queixa de Habacuque a Deus.','texto_biblico',291),
('habacuque','Habacuque',1,'Segundo Habacuque 1:7, como o povo caldeu é descrito quanto à origem do seu próprio juízo?','facil','Terrível e espantoso; seu juízo e majestade procedem dele mesmo','Gentil e receptivo às leis de outras nações','Totalmente submisso a conselhos estrangeiros','Incapaz de tomar qualquer decisão militar','A','Habacuque 1:7 descreve os caldeus: "ela é terrível e espantosa; o seu juízo e a sua majestade procedem dela mesma".','Mostra a autoconfiança arrogante do império caldeu.','texto_biblico',292),
('habacuque','Habacuque',1,'Segundo Habacuque 1:8, a que animais os cavalos dos caldeus são comparados?','facil','Bois e jumentos','Cordeiros e pombas','Leopardos e lobos da tarde','Águias e falcões apenas','C','Habacuque 1:8 descreve: "os seus cavalos são mais ligeiros do que os leopardos, e mais ferozes do que os lobos à tarde".','É uma imagem de velocidade e ferocidade militar.','texto_biblico',293),
('habacuque','Habacuque',1,'Segundo Habacuque 1:10, como os caldeus tratam reis e fortalezas de outras nações?','facil','Pedem permissão antes de qualquer ataque','Prestam-lhes homenagem respeitosa','Escarnecem deles e riem-se de toda fortaleza','Evitam confronto direto com reis poderosos','C','Habacuque 1:10 relata: "também escarnecem dos reis, e dos príncipes fazem zombaria; riem-se de toda fortaleza".','Reforça a arrogância militar descrita ao longo do capítulo 1.','texto_biblico',294),
('habacuque','Habacuque',1,'Segundo Habacuque 1:15, com que instrumentos de pesca os caldeus são comparados ao capturar povos inteiros?','facil','Anzol e rede','Lança e escudo','Fogo e espada apenas','Cordas e correntes de ferro','A','Habacuque 1:15 descreve: "a todos tira com anzol, apanha-os com a sua rede, e os ajunta na sua rede varredoura".','É uma imagem que compara a conquista de nações à pesca predatória.','texto_biblico',295),
('habacuque','Habacuque',2,'Segundo Habacuque 2:1, o que o profeta decide fazer para receber a resposta de Deus à sua queixa?','facil','Consultar outros profetas estrangeiros','Ir imediatamente embora da região','Reunir um grande exército próprio','Ficar de guarda, colocando-se sobre uma fortaleza para vigiar','D','Habacuque 2:1 declara: "Sobre a minha guarda estarei, e sobre a fortaleza me colocarei, e vigiarei para ver o que me dirá".','É a postura de espera ativa e atenta do profeta diante de Deus.','texto_biblico',296),
('habacuque','Habacuque',2,'Segundo Habacuque 2:2, o que Deus ordena que o profeta faça com a visão recebida?','facil','Repeti-la apenas de memória, sem registro','Guardá-la em segredo absoluto','Escrevê-la de forma clara em tábuas','Destruí-la após memorizá-la','C','Habacuque 2:2 ordena: "Escreve a visão, e torna-a bem legível sobre tábuas, para que a possa ler quem passa correndo".','Mostra a importância de tornar a revelação acessível e clara para todos.','texto_biblico',297),
('habacuque','Habacuque',2,'Segundo Habacuque 2:3, mesmo que a visão pareça demorar, o que é garantido sobre seu cumprimento?','facil','Será cancelada se o povo pecar novamente','Nunca se cumprirá de fato','Depende exclusivamente da fé do povo','Certamente virá, não tardará','D','Habacuque 2:3 assegura: "ainda que se detenha, espera-o, porque certamente virá, não tardará".','É uma palavra de encorajamento à paciência confiante.','texto_biblico',298),
('habacuque','Habacuque',3,'Segundo Habacuque 3:3, de onde o texto diz que Deus vem em sua manifestação de poder?','facil','De Temã e do monte Parã','Do Egito e do mar Vermelho','Da Babilônia e do rio Eufrates','Do Líbano e do monte Hermom','A','Habacuque 3:3 declara: "Deus vem de Temã, e o Santo, do monte Parã".','São regiões ao sul de Judá, associadas historicamente às teofanias do Sinai.','texto_biblico',299),
('habacuque','Habacuque',3,'Segundo Habacuque 3:4, como é descrito o resplendor de Deus em sua manifestação?','facil','Como uma nuvem baixa e discreta','Como total escuridão e trevas','Como a luz, com raios brilhantes saindo de sua mão','Como um silêncio completo, sem sinais visíveis','C','Habacuque 3:4 descreve: "o seu resplendor é como a luz; raios brilhantes saem da sua mão; e ali se esconde o seu poder".','É parte da grandiosa teofania descrita no capítulo 3.','texto_biblico',300),
('habacuque','Habacuque',3,'Segundo Habacuque 3:11, o que acontece com o sol e a lua diante do avanço poderoso de Deus?','facil','Se movem mais rápido do que o normal','Brilham com o dobro da intensidade','Desaparecem completamente do céu','Param em sua morada','D','Habacuque 3:11 relata: "O sol e a lua pararam na sua morada; à luz das tuas flechas passaram".','É uma imagem semelhante à do sol parado em Josué 10.','texto_biblico',301),
('habacuque','Habacuque',3,'Segundo Habacuque 3:19, o que o profeta declara que o Senhor Deus é para ele, ao final do livro?','facil','Apenas um juiz distante','A sua força','Um mistério incompreensível','Uma fonte de medo constante','B','Habacuque 3:19 conclui: "O Senhor Deus é a minha força, e fará os meus pés como os das cervas, e me fará andar sobre as minhas alturas".','É a declaração final de confiança que encerra todo o livro.','texto_biblico',302),
('habacuque','Habacuque',1,'Segundo Habacuque 1:5, o que Deus avisa que fará "em vossos dias", algo tão surpreendente que ninguém creria mesmo sendo contado?','medio','Enviar um novo dilúvio universal','Destruir Jerusalém instantaneamente sem aviso','Levantar os caldeus como instrumento de juízo','Acabar com todas as nações estrangeiras de uma vez','C','Habacuque 1:5 declara: "Olhai entre as nações, e vede, e maravilhai-vos muitíssimo; porque realizo uma obra em vossos dias que não crereis, quando vos for contada".','Introduz a resposta chocante de Deus sobre o uso dos caldeus como instrumento de juízo.','texto_biblico',303),
('habacuque','Habacuque',1,'Segundo Habacuque 1:11, apesar de todo seu poder militar, qual erro espiritual os caldeus cometem?','medio','Atribuem seu próprio poder ao seu deus, tornando-se culpados','Reconhecem publicamente o Deus de Israel como único Senhor','Recusam-se a lutar por motivos religiosos','Abandonam suas conquistas por medo divino','A','Habacuque 1:11 relata: "Então passam como um vento, e traspassam, e ficam culpados, atribuindo este seu poder ao seu deus".','Revela a idolatria por trás do sucesso militar caldeu.','texto_biblico',304),
('habacuque','Habacuque',1,'Segundo Habacuque 1:12-13, qual questionamento profundo o profeta faz sobre o caráter de Deus diante da violência caldeia?','medio','Por que Deus abandonou totalmente seu povo escolhido','Por que Deus nunca mais falará com os profetas','Por que Deus, sendo puro, tolera que o ímpio devore o mais justo do que ele','Por que Deus permite apenas pequenos pecados, nunca grandes','C','Habacuque 1:13 questiona: "Tu, que és tão puro de olhos que não podes ver o mal... por que olhas para os que procedem aleivosamente, e te calas quando o ímpio devora o mais justo do que ele?".','É o núcleo do dilema teológico enfrentado pelo profeta.','texto_biblico',305),
('habacuque','Habacuque',1,'Segundo Habacuque 1:14-15, a que Habacuque compara os seres humanos capturados pelos caldeus em sua queixa a Deus?','medio','A árvores enraizadas e imóveis','A pássaros livres voando sem limites','A leões fortes que não podem ser capturados','A peixes do mar e répteis sem quem os governe','D','Habacuque 1:14 lamenta: "E farás os homens como os peixes do mar, como os répteis, que não têm quem os governe?".','Expressa a indignação de Habacuque com a desumanização causada pela conquista caldeia.','texto_biblico',306),
('habacuque','Habacuque',1,'Segundo Habacuque 1:16, o que os caldeus fazem por causa de seu próprio sucesso militar, atribuindo-o a seus instrumentos de guerra?','medio','Recusam-se a comemorar qualquer conquista','Devolvem os louros da vitória aos deuses de Israel','Destroem publicamente suas próprias armas','Sacrificam à sua rede e queimam incenso à sua varredoura','D','Habacuque 1:16 relata: "Por isso sacrifica à sua rede, e queima incenso à sua varredoura; porque com elas engordou a sua porção".','É uma forma de idolatria que glorifica o próprio poder militar como se fosse divino.','texto_biblico',307),
('habacuque','Habacuque',2,'Segundo Habacuque 2:5, a que vício o profeta compara a arrogância do soberbo, que "não permanecerá"?','medio','Ao vinho traidor','À água que sempre falta','Ao fogo que nunca se apaga','Ao veneno de escorpião','A','Habacuque 2:5 declara: "E também, como o vinho é traidor, assim o soberbo não permanecerá".','É uma comparação usada para introduzir os "ais" pronunciados no restante do capítulo.','texto_biblico',308),
('habacuque','Habacuque',2,'Segundo Habacuque 2:11, o que a própria construção acusará contra quem edifica com violência e sangue?','medio','Apenas os vizinhos poderão testemunhar contra o construtor','As pedras permanecerão em silêncio absoluto','"A pedra clamará da parede, e a trave lhe responderá do madeiramento"','Nenhuma consequência visível ocorrerá','C','Habacuque 2:11 declara essa acusação poética contra a construção erguida sobre injustiça e violência.','É uma imagem poderosa de que até objetos inanimados testemunham contra a injustiça.','texto_biblico',309),
('habacuque','Habacuque',2,'Segundo Habacuque 2:14, o que encherá a terra assim como as águas cobrem o mar?','medio','A paz política entre todas as nações','A riqueza acumulada pelos caldeus','O conhecimento da glória do Senhor','O número de templos construídos','C','Habacuque 2:14 promete: "Porque a terra se encherá do conhecimento da glória do Senhor, como as águas cobrem o mar".','É uma das promessas mais citadas do livro, repetida de forma similar em Isaías 11:9.','texto_biblico',310),
('habacuque','Habacuque',2,'Segundo Habacuque 2:18-19, o que o profeta questiona sobre a real utilidade dos ídolos esculpidos?','medio','Que eles não têm espírito algum e não podem ensinar nem responder','Que são extremamente poderosos, mas apenas à noite','Que só funcionam quando feitos de ouro puro','Que ajudam apenas os estrangeiros, nunca os israelitas','A','Habacuque 2:19 conclui: "Ai daquele que diz ao pau: Desperta! E à pedra muda: Acorda!... no meio dele, porém, não há espírito algum".','É uma crítica clássica profética contra a idolatria.','texto_biblico',311),
('habacuque','Habacuque',2,'Segundo Habacuque 2:20, qual deve ser a atitude de toda a terra diante do Senhor em seu santo templo?','medio','Discutir teologia abertamente','Gritar em alta voz continuamente','Calar-se/guardar silêncio reverente','Ignorar sua presença completamente','C','Habacuque 2:20 declara: "Mas o Senhor está no seu santo templo; cale-se diante dele toda a terra".','É um chamado solene à reverência diante da majestade divina.','texto_biblico',312),
('habacuque','Habacuque',3,'Segundo Habacuque 3:2, o que o profeta pede a Deus mesmo em meio à ira anunciada contra o povo?','medio','Que acabe imediatamente com todo o povo','Que se lembre da misericórdia','Que envie outro profeta em seu lugar','Que esqueça completamente a aliança antiga','B','Habacuque 3:2 ora: "Senhor, ouvi a tua fala, e temi... na ira lembra-te da misericórdia".','É o pedido central da oração do capítulo 3, equilibrando juízo e graça.','texto_biblico',313),
('habacuque','Habacuque',3,'Segundo Habacuque 3:6, o que acontece aos "montes perpétuos" e "outeiros eternos" diante da passagem de Deus?','medio','Se espalham e se abaixam','Permanecem absolutamente imóveis','Crescem ainda mais altos','Se transformam em vales férteis','A','Habacuque 3:6 descreve: "Ele pára, e mede a terra... os montes perpétuos se espalham, os outeiros eternos se abaixam".','É parte da grande teofania que retrata o poder incontrolável de Deus sobre a natureza.','texto_biblico',314),
('habacuque','Habacuque',1,'Segundo Habacuque 1:17, qual pergunta final o profeta faz sobre a continuidade da violência caldeia?','dificil','Se eles se converterão ao Deus de Israel','Se eles finalmente pagarão tributo a Judá','Se eles esvaziarão sua rede sem cessar de matar as nações continuamente','Se eles serão os próximos a ser escravizados','C','Habacuque 1:17 encerra o capítulo perguntando: "Porventura por isso esvaziará ele a sua rede, e não cessará de matar as nações continuamente?".','É a pergunta angustiada que fecha a primeira queixa do profeta antes da resposta de Deus no capítulo 2.','texto_biblico',315),
('habacuque','Habacuque',2,'Segundo Habacuque 2:6-7, que pergunta retórica é feita sobre aqueles que um dia se levantarão contra o opressor caldeu?','dificil','"Quando o opressor finalmente se arrependerá?"','"Quem ousaria desafiar um império tão grande?"','"Por que ninguém nunca se rebelará?"','"Não se levantarão de repente os que te haviam de morder?"','D','Habacuque 2:6-7 pergunta retoricamente sobre o opressor: "não se levantarão de repente os que te haviam de morder, e não despertarão os que te haviam de arrancar?".','Antecipa que o próprio opressor será um dia oprimido por outros.','texto_biblico',316),
('habacuque','Habacuque',2,'Segundo Habacuque 2:13, de quem procede a futilidade do trabalho das nações "para o fogo"?','dificil','Do acaso, sem nenhuma intervenção divina','Dos próprios reis caldeus, por decisão própria','Do Senhor dos Exércitos','Dos deuses pagãos adorados pelos caldeus','C','Habacuque 2:13 pergunta: "Porventura não vem isso do Senhor dos Exércitos, que os povos trabalhem para o fogo, e as nações se cansem em vão?".','Mostra que até a futilidade do esforço humano está sob a soberania de Deus.','texto_biblico',317),
('habacuque','Habacuque',3,'Segundo Habacuque 3:8, ao perguntar se a ira de Deus era contra os rios e o mar, o que o profeta sugere ser o verdadeiro alvo da ação divina?','dificil','A destruição definitiva de toda a criação','A salvação do seu povo, não os elementos naturais em si','Uma disputa cósmica sem relação com Israel','Um castigo exclusivo contra os egípcios antigos','B','Habacuque 3:8 pergunta: "Acaso indignaste-te, Senhor, contra os rios?... Foi o teu furor contra o mar?", mas o contexto (v.13) revela que o propósito era salvar o povo.','Mostra que os fenômenos naturais descritos são meios, não o alvo final da ação de Deus.','texto_biblico',318),
('habacuque','Habacuque',3,'Segundo Habacuque 3:13, qual é o propósito declarado da grandiosa marcha de Deus descrita no capítulo 3?','dificil','Estabelecer um novo pacto com os caldeus','Demonstrar poder sem nenhum propósito redentor','Punir apenas as nações vizinhas de Judá','Salvar o seu povo e o seu ungido','D','Habacuque 3:13 declara: "Saíste para salvar o teu povo, para salvar o teu ungido; feriste a cabeça da casa do ímpio".','Revela que toda a teofania tem um propósito redentor e não apenas destrutivo.','texto_biblico',319),
('habacuque','Habacuque',3,'Segundo Habacuque 3:16, como o próprio corpo do profeta reage fisicamente diante da visão do poder de Deus?','dificil','Ele perde completamente a fala para sempre','Ele permanece totalmente calmo e impassível','Ele adormece profundamente durante a visão','Seu ventre se comove, seus lábios tremem e sente podridão nos ossos','D','Habacuque 3:16 descreve: "ouvi isto, e o meu ventre se comoveu; à voz disto tremeram os meus lábios; a podridão entrou nos meus ossos".','Mostra o impacto físico e emocional intenso da revelação divina sobre o profeta.','texto_biblico',320),
('sofonias','Sofonias',1,'Quem é identificado como pai de Sofonias?','facil','Amós','Ezequias','Cusi','Hulda','C','Sofonias 1:1 começa com a genealogia e identifica Sofonias como filho de Cusi.','O nome aparece no primeiro versículo.','texto_biblico',321),
('sofonias','Sofonias',1,'Qual expressão marca o anúncio de juízo em Sofonias?','facil','A festa das colheitas','O ano do jubileu','O dia do Senhor','A noite do rei','C','O livro repete a expressão dia do Senhor como momento de juízo.','É o tema temporal mais destacado.','texto_biblico',322),
('sofonias','Sofonias',2,'O que Sofonias 2:3 recomenda buscar?','medio','O Senhor, a justiça e a humildade','Riquezas e poder','A Assíria','Um novo palácio','A','Sofonias 2:3 chama os humildes da terra a buscar o Senhor, a justiça e a humildade.','São três elementos no convite.','texto_biblico',323),
('sofonias','Sofonias',3,'Como termina o livro de Sofonias?','medio','Com a queda de Jerusalém sem esperança','Com uma guerra no Egito','Com promessa de restauração e alegria de Deus sobre seu povo','Com a morte do profeta','C','Sofonias 3:14-20 termina com restauração, reunião dos dispersos e alegria associada à presença de Deus no meio do povo.','O final muda do juízo para a restauração.','texto_biblico',324),
('sofonias','Sofonias',3,'Qual cidade é mencionada entre os alvos de juízo no livro?','dificil','Hebrom','Nínive','Belém','Damasco','B','Sofonias 2:13-15 anuncia juízo contra a Assíria e Nínive, descrita como cidade desolada.','A cidade assíria aparece explicitamente no capítulo 2.','texto_biblico',325),
('sofonias','Sofonias',1,'Qual é a extensão do juízo anunciado logo no início de Sofonias 1:2-3?','facil','Destruição total sobre homens, animais, aves e peixes','Apenas sobre os sacerdotes','Apenas sobre os estrangeiros','Somente sobre a Assíria','A','Sofonias 1:2-3 anuncia uma destruição abrangente sobre toda a face da terra, incluindo homens e animais.','É uma linguagem de juízo cósmico e abrangente.','texto_biblico',326),
('sofonias','Sofonias',3,'O que o Senhor faz por seu povo com alegria, segundo Sofonias 3:17?','facil','Os pune sem misericórdia','Os envia ao exílio','Os abandona no deserto','Canta sobre eles com júbilo','D','Sofonias 3:17 descreve Deus se alegrando e cantando sobre seu povo com júbilo, uma imagem terna do amor divino.','É uma imagem de alegria e canto de Deus.','texto_biblico',327),
('sofonias','Sofonias',1,'Com o que Sofonias 1:12 compara os que estavam acomodados espiritualmente?','medio','Pão fresco','Água corrente e pura','Ouro refinado','Vinho parado sobre as fezes (borra)','D','Sofonias 1:12 fala de buscar com lanternas os que estão acomodados como vinho sobre a borra, indiferentes ao Senhor.','É uma imagem de estagnação e indiferença espiritual.','texto_biblico',328),
('sofonias','Sofonias',2,'Quais grupos de nações são alvo dos oráculos de juízo em Sofonias 2?','medio','Filístia, Moabe, Amom, Cuxe e Assíria','Somente as tribos de Israel','Apenas o Egito','Apenas Roma e Grécia','A','Sofonias 2 traz oráculos de juízo contra Filístia, Moabe, Amom, Cuxe (Etiópia) e a Assíria.','São nações vizinhas de Judá, incluindo a grande potência assíria.','texto_biblico',329),
('sofonias','Sofonias',1,'Segundo a genealogia em Sofonias 1:1, o profeta é apresentado como descendente de qual rei de Judá?','dificil','Davi','Ezequias','Josias, seu contemporâneo','Salomão','B','Sofonias 1:1 traça a genealogia do profeta até Ezequias, sugerindo possível ascendência real.','É um rei reformador anterior a Josias.','texto_biblico',330),
('sofonias','Sofonias',1,'Segundo Sofonias 1:4, contra quem Deus estende a mão, prometendo exterminar o resto de sua adoração?','facil','Apenas os reis estrangeiros','Baal, e os sacerdotes idólatras','Somente os profetas verdadeiros','Os sacerdotes fiéis do templo','B','Sofonias 1:4 declara: "estenderei a minha mão contra Judá, e contra todos os moradores de Jerusalém; e exterminarei deste lugar o resto de Baal".','É o início da denúncia contra a idolatria em Judá.','texto_biblico',331),
('sofonias','Sofonias',1,'Segundo Sofonias 1:5, que prática idólatra específica é mencionada sobre os telhados das casas?','facil','Acender velas em homenagem aos ancestrais','Oferecer sacrifícios de animais','Adorar o exército dos céus','Realizar danças rituais noturnas','C','Sofonias 1:5 denuncia "os que sobre os telhados se prostram ao exército dos céus", uma forma de idolatria astral.','Era uma prática comum de adoração aos astros, condenada repetidamente pelos profetas.','texto_biblico',332),
('sofonias','Sofonias',1,'Segundo Sofonias 1:7, qual deve ser a atitude do povo diante da proximidade do dia do Senhor?','facil','Fugir imediatamente para outras terras','Celebrar com festas abundantes','Ignorar completamente o aviso','Calar-se diante do Senhor Deus','D','Sofonias 1:7 ordena: "Cala-te diante do Senhor Deus, porque o dia do Senhor está perto".','É um chamado solene à reverência diante do julgamento iminente.','texto_biblico',333),
('sofonias','Sofonias',1,'Segundo Sofonias 1:13, o que acontecerá às casas e vinhas dos que serão julgados?','facil','Suas vinhas produzirão o dobro do normal','Suas casas se multiplicarão em número','Edificarão casas mas não habitarão nelas, plantarão vinhas mas não beberão o vinho','Nada de diferente acontecerá com seus bens','C','Sofonias 1:13 anuncia: "e edificarão casas, mas não as habitarão; e plantarão vinhas, mas não beberão o vinho delas".','É uma maldição semelhante à encontrada em outras partes do Antigo Testamento sobre frutos do trabalho perdidos.','texto_biblico',334),
('sofonias','Sofonias',1,'Segundo Sofonias 1:18, o que não poderá livrar ninguém no dia da ira do Senhor?','facil','Unicamente muralhas fortificadas','Apenas exércitos poderosos','Somente alianças estrangeiras','Nem a prata nem o ouro','D','Sofonias 1:18 declara: "nem a sua prata nem o seu ouro os poderá livrar no dia da ira do Senhor".','Mostra que riquezas materiais são inúteis diante do juízo divino.','texto_biblico',335),
('sofonias','Sofonias',2,'Segundo Sofonias 2:1, como a nação é chamada a se preparar antes de vir o julgamento?','facil','Dispersar-se pelas montanhas','Congregar-se e ajuntar-se','Esconder-se em silêncio absoluto','Fortificar suas próprias muralhas','B','Sofonias 2:1 convoca: "Congregai-vos e ajuntai-vos, ó nação sem pudor".','É um chamado coletivo à reflexão antes do dia do Senhor.','texto_biblico',336),
('sofonias','Sofonias',2,'Segundo Sofonias 2:5, contra quem é dirigido o "ai" no início do julgamento das nações, no capítulo 2?','facil','Os moradores da borda do mar, a nação dos quereteus','Apenas os egípcios','Somente os babilônios','Os próprios israelitas exilados','A','Sofonias 2:5 declara: "Ai dos moradores da borda do mar, da nação dos quereteus! A palavra do Senhor é contra vós, ó Canaã, terra dos filisteus".','Inicia a série de julgamentos contra as nações vizinhas de Judá no capítulo 2.','texto_biblico',337),
('sofonias','Sofonias',2,'Segundo Sofonias 2:8, do que Deus ouviu Moabe e os filhos de Amom escarnecerem?','facil','Das riquezas da Babilônia','Das leis egípcias','Dos exércitos assírios','Do povo de Deus','D','Sofonias 2:8 declara: "Ouvi o escárnio de Moabe, e as injúrias dos filhos de Amom, com que escarneceram do meu povo".','É a justificativa para o julgamento anunciado contra essas duas nações vizinhas.','texto_biblico',338),
('sofonias','Sofonias',2,'Segundo Sofonias 2:9, a que cidades destruídas Moabe e Amom são comparados quanto ao seu destino?','facil','Tiro e Sidom','Nínive e Babilônia','Sodoma e Gomorra','Jope e Cesareia','C','Sofonias 2:9 declara: "Moabe será como Sodoma, e os filhos de Amom como Gomorra... um perpétuo assolamento".','É uma comparação clássica usada pelos profetas para anunciar destruição total.','texto_biblico',339),
('sofonias','Sofonias',2,'Segundo Sofonias 2:14, o que passará a habitar nas ruínas de Nínive depois de sua destruição?','facil','Apenas o silêncio, sem nenhuma vida','Uma nova população próspera','Exércitos permanentes de guarda','Manadas de animais, o pelicano e a corneja','D','Sofonias 2:14 descreve: "e manadas se deitarão no meio dela... o pelicano e a corneja pousarão nos seus capitéis".','É uma imagem de completa desolação da outrora poderosa capital assíria.','texto_biblico',340),
('sofonias','Sofonias',3,'Segundo Sofonias 3:3, a que animais os príncipes e juízes da cidade rebelde são comparados?','facil','Bois de carga fiéis','Cordeiros mansos e pombas pacíficas','Águias protetoras do povo','Leões que rugem e lobos da tarde','D','Sofonias 3:3 denuncia: "os seus príncipes são leões que rugem no meio dela; os seus juízes são lobos da tarde, que nada deixam para amanhã".','É uma crítica forte à liderança corrupta e predatória da cidade.','texto_biblico',341),
('sofonias','Sofonias',3,'Segundo Sofonias 3:14, o que a filha de Sião é chamada a fazer, expressando grande alegria?','facil','Fugir imediatamente da cidade','Chorar e lamentar profundamente','Ficar em silêncio absoluto','Cantar, rejubilar e exultar de todo o coração','D','Sofonias 3:14 convoca: "Canta alegremente, ó filha de Sião, rejubila, ó Israel; alegra-te, e exulta de todo o coração, ó filha de Jerusalém!".','Marca a virada do livro do julgamento para a celebração da restauração.','texto_biblico',342),
('sofonias','Sofonias',1,'Segundo Sofonias 1:8-9, quem mais, além dos idólatras comuns, será castigado, incluindo os que se vestem de forma estranha?','medio','Somente os profetas falsos','Apenas os estrangeiros residentes','Os príncipes e os filhos do rei','Unicamente os mercadores ricos','C','Sofonias 1:8 anuncia: "castigarei os príncipes, e os filhos do rei, e todos os que se vestem de veste estranha".','Mostra que nem a realeza estaria isenta do julgamento anunciado.','texto_biblico',343),
('sofonias','Sofonias',1,'Segundo Sofonias 1:9, que comportamento violento e enganoso é citado entre os que seriam castigados naquele dia?','medio','Recusar-se a pagar impostos ao rei','Encher a casa do seu senhor de violência e engano','Adorar publicamente o Deus de Israel','Recusar-se a participar de guerras','B','Sofonias 1:9 denuncia "todos os que saltam o umbral, que enchem de violência e de engano a casa do seu senhor".','Refere-se a práticas de corrupção e violência doméstica ou social.','texto_biblico',344),
('sofonias','Sofonias',1,'Segundo Sofonias 1:12, o que Deus promete fazer com os que dizem "o Senhor não fará bem nem mal"?','medio','Enviar-lhes um profeta para instruí-los','Recompensá-los por sua sinceridade','Ignorá-los completamente no julgamento','Buscá-los com lanternas e castigá-los','D','Sofonias 1:12 declara: "buscarei a Jerusalém com lanternas, e castigarei os homens que... dizem no seu coração: O Senhor não fará bem nem mal".','Denuncia a indiferença espiritual e o ceticismo religioso do povo.','texto_biblico',345),
('sofonias','Sofonias',2,'Segundo Sofonias 2:2, o que o profeta adverte que virá "antes que o decreto produza efeito"?','medio','A reconstrução do templo','Uma grande celebração nacional','Um novo rei justo','O furor do Senhor','D','Sofonias 2:2 adverte: "antes que o decreto produza efeito... antes que venha sobre vós o furor da ira do Senhor".','É um apelo urgente ao arrependimento antes que seja tarde demais.','texto_biblico',346),
('sofonias','Sofonias',2,'Segundo Sofonias 2:7, o que acontecerá com a costa filisteia depois do julgamento, beneficiando o remanescente de Judá?','medio','Se tornará território assírio','Será reconstruída pelos próprios filisteus','Permanecerá para sempre inabitável','Se tornará pastagem para o remanescente da casa de Judá','D','Sofonias 2:7 promete: "e será a costa para o resto da casa de Judá; nela apascentarão... porque o Senhor, seu Deus, os visitará".','Mostra que o julgamento das nações traria benefício ao remanescente fiel de Judá.','texto_biblico',347),
('sofonias','Sofonias',2,'Segundo Sofonias 2:10, qual é a razão explícita apontada para o julgamento de Moabe e Amom?','medio','Uma seca prolongada em seu território','A falta de exércitos suficientes','A soberba deles','A traição de um aliado poderoso','C','Sofonias 2:10 declara: "Isso lhes sucederá pela sua soberba, porque escarneceram do povo do Senhor dos Exércitos, e se engrandeceram contra ele".','A soberba é uma acusação recorrente contra as nações julgadas nos profetas menores.','texto_biblico',348),
('sofonias','Sofonias',2,'Segundo Sofonias 2:11, o que Deus promete fazer com os deuses de todas as nações da terra?','medio','Transformá-los em ídolos de ouro','Fortalecê-los temporariamente','Enfraquecê-los/consumi-los todos','Distribuí-los entre os povos vencedores','C','Sofonias 2:11 declara: "O Senhor será terrível contra eles, porque enfraquecerá a todos os deuses da terra; e cada um do seu lugar o adorará".','Antecipa uma adoração universal ao verdadeiro Deus, superando todos os ídolos.','texto_biblico',349),
('sofonias','Sofonias',2,'Segundo Sofonias 2:13, contra qual grande potência do norte Deus promete estender sua mão, destruindo Nínive?','medio','A Babilônia','A Assíria','O Egito','A Média e a Pérsia','B','Sofonias 2:13 anuncia: "E estenderá a sua mão contra o norte, e destruirá a Assíria; e fará de Nínive uma assolação".','Confirma a queda do grande império assírio anunciada também em Naum.','texto_biblico',350),
('sofonias','Sofonias',3,'Segundo Sofonias 3:4, como são descritos os profetas e sacerdotes da cidade rebelde?','medio','Fiéis e dedicados ao culto verdadeiro','Levianos e aleivosos; profanam o santuário e violentam a lei','Ausentes completamente da vida da cidade','Rigorosos demais no cumprimento da lei','B','Sofonias 3:4 denuncia: "os seus profetas são levianos, homens aleivosos; os seus sacerdotes profanam o santuário, e fazem violência à lei".','É uma crítica dura à liderança religiosa corrupta de Jerusalém.','texto_biblico',351),
('sofonias','Sofonias',3,'Segundo Sofonias 3:5, apesar da corrupção geral da cidade, o que se afirma sobre o caráter do Senhor que está no meio dela?','medio','Também se corrompeu junto com o povo','É indiferente e distante de tudo','Está prestes a abandonar completamente a cidade','É justo, não pratica iniquidade, e traz seu juízo à luz a cada manhã','D','Sofonias 3:5 declara: "O Senhor justo está no meio dela; não pratica iniquidade; cada manhã tira a lume o seu juízo, nunca falta".','Contrasta a fidelidade de Deus com a infidelidade constante do povo.','texto_biblico',352),
('sofonias','Sofonias',3,'Segundo Sofonias 3:9, o que Deus promete dar aos povos para que todos o invoquem em unidade?','medio','Novos reis justos','Riquezas abundantes','Territórios conquistados','Lábios puros','D','Sofonias 3:9 promete: "Porque então darei aos povos lábios puros, para que todos invoquem o nome do Senhor, para o servirem de comum acordo".','É uma visão de unidade e adoração universal ao Senhor entre as nações.','texto_biblico',353),
('sofonias','Sofonias',3,'Segundo Sofonias 3:19, o que Deus promete fazer com "a que coxeava" e "a que foi expulsa", ao final do livro?','medio','Salvá-la e ajuntá-la, tornando-a um louvor e um nome em toda a terra','Abandoná-la definitivamente ao esquecimento','Enviá-la de volta ao cativeiro estrangeiro','Puni-la ainda mais severamente','A','Sofonias 3:19 promete: "eis que naquele tempo... salvarei a que coxeia, e ajuntarei a que foi expulsa; e farei deles um louvor e um nome em toda a terra".','É uma das promessas finais de restauração do remanescente fiel.','texto_biblico',354),
('sofonias','Sofonias',1,'Segundo Sofonias 1:11, quem é convocado a uivar porque "todo o povo mercantil é destruído"?','dificil','Os príncipes de Judá','Os sacerdotes de Baal','Os moradores de Mactes','Os profetas levianos','C','Sofonias 1:11 declara: "Uivai, moradores de Mactes, porque todo o povo mercantil é destruído; todos os que trazem prata são exterminados".','Mactes era provavelmente um bairro comercial de Jerusalém.','texto_biblico',355),
('sofonias','Sofonias',1,'Segundo Sofonias 1:17, a que se compara o sangue derramado dos que pecaram contra o Senhor?','dificil','Ao orvalho, que evapora rapidamente','Ao vinho, que será derramado em fartura','Ao pó, que será espalhado','Às lágrimas, que serão esquecidas','C','Sofonias 1:17 declara: "e espalhar-se-á o seu sangue como pó, e a sua carne, como esterco".','É uma imagem chocante da total desonra reservada aos culpados.','texto_biblico',356),
('sofonias','Sofonias',2,'Segundo Sofonias 2:6, o que a região costeira dos filisteus (a borda do mar) se tornará depois do julgamento anunciado?','dificil','Um deserto completamente estéril','Uma grande metrópole comercial','Cabanas de pastores e currais de rebanhos','Um novo porto militar fortificado','C','Sofonias 2:6 anuncia: "E a borda do mar será só cabanas, com cisternas para os pastores, e currais para os rebanhos".','Contrasta com a antiga prosperidade urbana da região filisteia.','texto_biblico',357),
('sofonias','Sofonias',3,'Segundo Sofonias 3:6-7, o que Deus esperava do povo depois de exterminar outras nações como advertência, mas que na verdade não aconteceu?','dificil','Esperava que reconstruíssem o templo sem demora','Esperava que se rendessem imediatamente aos babilônios','Esperava que temessem a Deus e aceitassem correção, mas eles se corromperam ainda mais','Esperava que abandonassem totalmente a agricultura','C','Sofonias 3:7 relata a decepção divina: "Eu disse: Certamente me temerás, aceitarás a correção... mas eles se levantaram de madrugada, e corromperam todas as suas obras".','Mostra que nem mesmo o exemplo de julgamento sobre outras nações levou o povo ao arrependimento.','texto_biblico',358),
('sofonias','Sofonias',3,'Segundo Sofonias 3:15, que título é dado ao Senhor que está no meio de Sião, garantindo que ela não temerá mais mal algum?','dificil','"O Guardião Silencioso"','"O Juiz das Nações"','"O Deus Distante"','"O Rei de Israel"','D','Sofonias 3:15 declara: "O Rei de Israel, o Senhor, está no meio de ti; não temerás mal algum".','É uma afirmação da realeza e presença ativa de Deus em meio ao seu povo restaurado.','texto_biblico',359),
('sofonias','Sofonias',3,'Segundo Sofonias 3:20, com que promessa final, ligada à reversão do cativeiro, o livro se encerra?','dificil','"Nunca mais falarei ao meu povo"','"Tornarei o vosso cativeiro diante dos vossos olhos"','"O templo será destruído para sempre"','"Todas as nações serão igualmente castigadas"','B','Sofonias 3:20 conclui: "Naquele tempo vos trarei... porque farei de vós um nome e um louvor entre todos os povos da terra, quando eu tornar o vosso cativeiro diante dos vossos olhos, diz o Senhor".','É a nota final de esperança que encerra todo o livro de Sofonias.','texto_biblico',360),
('ageu','Ageu',1,'Qual obra Ageu incentiva o povo a retomar?','facil','O palácio do rei','A reconstrução do templo','A muralha de Jericó','A construção de uma frota','B','Ageu 1:8 chama o povo a subir ao monte, trazer madeira e edificar a casa de Deus.','O templo é chamado de casa do Senhor.','texto_biblico',361),
('ageu','Ageu',1,'Quem governava Judá como governador no contexto de Ageu?','facil','Zorobabel','Saul','Elias','Ezequias','A','Ageu 1:1 identifica Zorobabel, filho de Sealtiel, como governador de Judá.','Ele aparece ao lado de Josué, o sumo sacerdote.','texto_biblico',362),
('ageu','Ageu',1,'Quem era o sumo sacerdote mencionado junto a Zorobabel?','medio','Josué, filho de Jeozadaque','Zadoque','Arão','Eli','A','Ageu 1:1 e outros textos do livro mencionam Josué, filho de Jeozadaque, como sumo sacerdote.','Não é Josué, sucessor de Moisés.','texto_biblico',363),
('ageu','Ageu',2,'O que Deus promete em Ageu 2:9 sobre a glória da casa?','medio','Não haveria templo','A casa seria abandonada','A glória desta última casa seria maior que a da primeira','O templo seria transferido para o Egito','C','Ageu 2:9 promete que a glória desta última casa seria maior que a primeira e anuncia paz.','A comparação é entre a casa anterior e a reconstruída.','texto_biblico',364),
('ageu','Ageu',2,'Qual imagem política aparece em Ageu 2:22?','dificil','A Assíria voltará a governar','Zorobabel será coroado rei de todas as nações','Tronos serão derrubados e reinos serão destruídos','Israel dominará o Egito imediatamente','C','Ageu 2:22 fala em derrubar tronos e destruir forças de reinos, dentro da mensagem escatológica do profeta.','A linguagem é de abalo dos poderes políticos.','texto_biblico',365),
('ageu','Ageu',1,'O que Ageu 1:6 diz sobre o salário de quem trabalhava enquanto negligenciava o templo?','facil','Dobrava a cada semana','Era guardado com segurança','Era posto num saco furado','Vinha do Egito','C','Ageu 1:6 descreve a futilidade econômica do povo, comparando o salário a algo posto num saco furado.','É uma imagem de perda constante e frustração.','texto_biblico',366),
('ageu','Ageu',1,'O que Deus declarou ao povo depois que eles obedeceram e começaram a reconstrução, segundo Ageu 1:13?','facil','Esquecerei o templo','Eu sou convosco','Eu vos abandono','Não voltarei mais','B','Ageu 1:13 registra a palavra de encorajamento do Senhor: Eu sou convosco, diz o Senhor.','É uma promessa de presença divina.','texto_biblico',367),
('ageu','Ageu',2,'O que Ageu 2:7 anuncia que virá depois que Deus abalar céus e terra?','medio','Um novo dilúvio','A queda definitiva de Jerusalém','O fim dos sacrifícios','O Desejado de todas as nações','D','Ageu 2:6-7 anuncia o abalo dos céus e da terra, seguido da vinda do Desejado de todas as nações, enchendo a casa de glória.','É uma expressão messiânica sobre expectativa das nações.','texto_biblico',368),
('ageu','Ageu',1,'Segundo Ageu 1:14, o que o Senhor despertou em Zorobabel, Josué e no povo?','medio','O desejo de fugir para o Egito','O espírito para trabalharem na casa do Senhor','O interesse em construir palácios pessoais','A vontade de abandonar Judá','B','Ageu 1:14 relata que o Senhor despertou o espírito de Zorobabel, Josué e do restante do povo para a obra da reconstrução.','É um despertar coletivo para o trabalho no templo.','texto_biblico',369),
('ageu','Ageu',2,'No versículo final de Ageu (2:23), a que objeto de honra Deus compara Zorobabel?','dificil','Uma espada real','Uma coroa de ouro','Um cetro de ferro','Um anel de selar','D','Ageu 2:23 declara que Deus fará de Zorobabel, seu servo, como um anel de selar, símbolo de honra e escolha divina.','É um objeto usado para autenticar documentos com um selo pessoal.','texto_biblico',370),
('ageu','Ageu',1,'Segundo Ageu 1:2, que desculpa o povo dava para não reconstruir o templo do Senhor?','facil','"Não veio ainda o tempo" de se edificar a casa do Senhor','"Não temos madeira suficiente"','"O rei da Pérsia proibiu a obra"','"Já reconstruímos o suficiente"','A','Ageu 1:2 registra a desculpa do povo: "Este povo diz: Não veio ainda o tempo, o tempo em que a casa do Senhor deve ser edificada".','É a procrastinação espiritual que o profeta vem confrontar diretamente.','texto_biblico',371),
('ageu','Ageu',1,'Segundo Ageu 1:4, que contraste o profeta aponta entre as casas do povo e a casa do Senhor?','facil','O povo não tem casa própria, mas o templo está lotado','O povo mora em casas forradas, enquanto o templo permanece deserto','Ambos estão igualmente abandonados','O templo está mais luxuoso do que as casas do povo','B','Ageu 1:4 questiona: "Porventura é tempo de habitardes nas vossas casas forradas, e esta casa está deserta?".','É a acusação central que expõe as prioridades erradas do povo.','texto_biblico',372),
('ageu','Ageu',1,'Segundo Ageu 1:8, o que o povo deveria fazer para agradar e glorificar a Deus?','facil','Esperar por um novo rei que ordenasse a obra','Oferecer apenas orações, sem nenhuma ação prática','Subir ao monte, trazer madeira e edificar a casa do Senhor','Construir primeiro suas próprias casas com mais luxo','C','Ageu 1:8 ordena: "Subi ao monte, e trazei madeira, e edificai esta casa, para que dela me agrade, e seja glorificado, diz o Senhor".','É o chamado direto à ação prática de reconstrução do templo.','texto_biblico',373),
('ageu','Ageu',1,'Segundo Ageu 1:12, como o povo e seus líderes reagiram à mensagem do profeta?','facil','Ignoraram completamente a mensagem','Obedeceram à voz do Senhor e temeram diante dele','Expulsaram Ageu da cidade','Continuaram exatamente como antes','B','Ageu 1:12 relata que Zorobabel, Josué e todo o resto do povo obedeceram à voz do Senhor, seu Deus, e temeram diante dele.','É uma resposta rápida e positiva à pregação profética, incomum entre os profetas menores.','texto_biblico',374),
('ageu','Ageu',1,'Segundo Ageu 1:13, qual promessa de presença Deus faz ao povo por meio do profeta?','facil','"Enviarei outro profeta em meu lugar"','"Nunca mais falarei convosco"','"Deixarei vocês por conta própria"','"Eu sou convosco, diz o Senhor"','D','Ageu 1:13 registra a mensagem encorajadora: "Eu sou convosco, diz o Senhor".','É a resposta imediata de Deus à obediência do povo.','texto_biblico',375),
('ageu','Ageu',1,'Segundo Ageu 1:14, o que Deus fez com o espírito de Zorobabel, Josué e do restante do povo?','facil','Fez com que adormecessem de exaustão','Despertou-os para trabalharem na casa do Senhor','Enviou-lhes sonhos confusos','Os deixou ainda mais desanimados','B','Ageu 1:14 relata que o Senhor despertou o espírito de Zorobabel, de Josué e de todo o povo, e eles vieram e trabalharam na casa do Senhor dos Exércitos.','Mostra a motivação divina por trás da retomada das obras do templo.','texto_biblico',376),
('ageu','Ageu',2,'Segundo Ageu 2:3, que pergunta é feita comparando o templo em reconstrução com sua "primeira glória"?','facil','Se parecia "como nada" em comparação com o templo anterior','Se já era mais bonito do que o de Salomão','Se estava completamente terminado','Se havia sido construído mais rápido que o esperado','A','Ageu 2:3 pergunta: "Quem há entre vós que viu esta casa na sua primeira glória? E como a vedes agora? Não é esta como nada em vossos olhos?".','Reflete a decepção de quem se lembrava do esplendor do templo de Salomão.','texto_biblico',377),
('ageu','Ageu',2,'Segundo Ageu 2:4, qual palavra de encorajamento repetida Deus dá a Zorobabel, Josué e a todo o povo?','facil','"Recuai" / "desistam"','"Esforça-te" / "esforçai-vos"','"Aguardem" / "não façam nada"','"Fujam" / "escondam-se"','B','Ageu 2:4 repete três vezes o chamado: "esforça-te, Zorobabel... esforça-te, Josué... esforça-te, todo o povo da terra".','É um encorajamento repetido para vencer o desânimo diante da obra incompleta.','texto_biblico',378),
('ageu','Ageu',2,'Segundo Ageu 2:5, o que Deus promete que permanecerá no meio do povo, assim como na aliança feita no Egito?','facil','Um exército protetor','Um novo rei permanente','Riquezas ilimitadas','O seu Espírito','D','Ageu 2:5 promete: "segundo a palavra do concerto que fiz convosco quando saístes do Egito, assim o meu Espírito permanecerá no meio de vós; não temais".','Liga a presença do Espírito à antiga aliança do êxodo.','texto_biblico',379),
('ageu','Ageu',2,'Segundo Ageu 2:8, a quem pertencem a prata e o ouro, segundo a declaração do Senhor dos Exércitos?','facil','Ao rei da Pérsia','A Deus mesmo','Somente aos sacerdotes','A quem trabalhar mais na reconstrução','B','Ageu 2:8 declara: "Minha é a prata, e meu é o ouro, diz o Senhor dos Exércitos".','Reforça que os recursos para a glória futura do templo pertencem inteiramente a Deus.','texto_biblico',380),
('ageu','Ageu',2,'Segundo Ageu 2:17, com quais pragas agrícolas Deus diz ter ferido o povo, sem que ele se voltasse para Deus?','facil','Fome generalizada e peste','Gafanhotos e lagarta apenas','Terremoto e inundação','Queimadura, ferrugem e saraiva','D','Ageu 2:17 relata: "feri-vos com queimadura, e com ferrugem, e com saraiva, em toda a obra das vossas mãos; e não houve entre vós quem voltasse para mim".','Mostra que mesmo o castigo direto não produziu arrependimento imediato no povo.','texto_biblico',381),
('ageu','Ageu',2,'Segundo Ageu 2:23, que honra especial Deus promete a Zorobabel como seu servo escolhido?','facil','Torná-lo sumo sacerdote também','Coroá-lo rei sobre todas as nações','Fazê-lo como um anel de selar','Enviá-lo como profeta para outras terras','C','Ageu 2:23 promete: "te tomarei, ó Zorobabel... e te porei como um anel de selar; porque te escolhi, diz o Senhor dos Exércitos".','É uma reversão simbólica da rejeição da linhagem real anunciada anteriormente contra o rei Joaquim.','texto_biblico',382),
('ageu','Ageu',1,'Segundo Ageu 1:6, como o profeta descreve vividamente a frustração econômica vivida pelo povo?','medio','Vivem em total escassez de água apenas','Colhem fartamente, mas não sabem o que fazer com o excesso','Têm fartura de tudo, mas reclamam sem motivo','Semeiam muito e colhem pouco; comem e bebem sem se fartar','D','Ageu 1:6 descreve: "Semeastes muito, e recolhestes pouco; comeis, mas não vos fartais; bebeis, mas não vos saciais... o que ganha salário, ganha-o para o meter num saco furado".','É uma descrição da maldição econômica ligada à negligência espiritual do povo.','texto_biblico',383),
('ageu','Ageu',1,'Segundo Ageu 1:9, por que Deus frustrou ("assoprou") o pouco que o povo trazia para casa?','medio','Porque os sacerdotes pediam demais em sacrifícios','Porque o povo pagava impostos insuficientes ao rei persa','Porque havia guerra iminente na região','Por causa da casa do Senhor estar deserta, enquanto cada um corria à sua própria casa','D','Ageu 1:9 explica: "Por que causa? diz o Senhor dos Exércitos; por causa da minha casa, que está deserta, enquanto correis, cada um, à sua própria casa".','Liga diretamente a dificuldade econômica à negligência espiritual coletiva.','texto_biblico',384),
('ageu','Ageu',1,'Segundo Ageu 1:10-11, o que Deus reteve e o que ele chamou sobre a terra por causa da negligência do povo?','medio','Enviou pragas apenas sobre os animais, poupando as plantações','Enviou chuvas em excesso, causando enchentes','Multiplicou as colheitas além do esperado','Reteve o orvalho e a chuva, e chamou a seca sobre a terra, o trigo e os animais','D','Ageu 1:10-11 relata que o céu reteve o orvalho e a terra reteve sua novidade, e Deus chamou a seca sobre a terra, os montes, o trigo, o mosto, o azeite, os homens e os animais.','É a consequência natural anunciada pela negligência com a casa de Deus.','texto_biblico',385),
('ageu','Ageu',2,'Segundo Ageu 2:6-7, o que Deus promete fazer com os céus, a terra, o mar e todas as nações?','medio','Fará tremer tudo, e virá o Desejado de todas as nações','Deixará tudo permanentemente estável','Destruirá apenas as nações vizinhas de Judá','Enviará apenas um sinal discreto no céu','A','Ageu 2:6-7 promete: "ainda uma vez, daqui a pouco, farei tremer os céus, a terra, o mar e a terra seca; e farei tremer todas as nações, e virá o Desejado de todas as nações".','É uma das profecias messiânicas mais citadas do livro de Ageu.','texto_biblico',386),
('ageu','Ageu',2,'Segundo Ageu 2:9, além de prometer uma glória maior que a do templo anterior, o que mais Deus promete dar "neste lugar"?','medio','A paz','Riquezas incalculáveis apenas para os sacerdotes','Um novo exército permanente','Territórios adicionais para Judá','A','Ageu 2:9 promete: "a glória desta última casa será maior do que a da primeira... e neste lugar darei a paz, diz o Senhor dos Exércitos".','Une a promessa de glória material e espiritual à promessa de paz duradoura.','texto_biblico',387),
('ageu','Ageu',2,'Segundo Ageu 2:11-13, sobre qual assunto específico Ageu é orientado a perguntar aos sacerdotes?','medio','Regras sobre o pagamento de dízimos','Leis de pureza e impureza cerimonial','Normas sobre casamentos mistos','Regulamentos sobre sacrifícios de animais estrangeiros','B','Ageu 2:11-13 registra a pergunta sobre se carne santa que toca outra coisa a torna santa, e se algo impuro que toca outra coisa a torna impura, usando isso como ilustração espiritual.','É uma lição objetiva usando a lei levítica para ensinar uma verdade espiritual sobre o povo.','texto_biblico',388),
('ageu','Ageu',2,'Segundo Ageu 2:14, o que Deus afirma sobre a pureza de todas as obras e ofertas desse povo até aquele momento?','medio','Eram completamente aceitáveis','Eram impuras diante dele','Eram melhores do que as ofertas anteriores','Não tinham nenhuma relevância espiritual','B','Ageu 2:14 declara: "assim é este povo, e assim é esta nação diante de mim, diz o Senhor; e assim é toda a obra das suas mãos; e tudo quanto ali oferecem é imundo".','Aplica a lição da pureza cerimonial à condição espiritual real do povo antes da reconstrução do templo.','texto_biblico',389),
('ageu','Ageu',2,'Segundo Ageu 2:16, que exemplo de escassez agrícola ilustra a maldição sobre o trabalho do povo antes da retomada da obra?','medio','As colheitas eram sempre exatamente como o esperado','Esperavam pouco e recebiam muito mais','Esperavam vinte medidas de grão e havia somente dez','Não havia nenhuma colheita agrícola naquele período','C','Ageu 2:16 relata: "vindo alguém a um montão de vinte medidas, havia somente dez; vindo à lagar para tirar cinquenta, havia somente vinte".','É uma imagem concreta da escassez sofrida antes da reconstrução do templo.','texto_biblico',390),
('ageu','Ageu',2,'Segundo Ageu 2:19, a partir de que marco Deus promete começar a abençoar o povo?','medio','A partir da próxima colheita apenas','A partir da coroação de um novo rei','A partir do dia em que foram postos os fundamentos do templo','A partir do fim do domínio persa','C','Ageu 2:19 pergunta e promete: "desde este dia vos abençoarei", referindo-se ao dia em que os fundamentos do templo foram lançados.','Marca uma virada simbólica de maldição para bênção ligada à obediência na reconstrução.','texto_biblico',391),
('ageu','Ageu',2,'Segundo Ageu 2:21-22, o que Deus promete fazer com os tronos e a força militar dos reinos das nações?','medio','Derribá-los, destruindo carros, cavalos e cavaleiros','Fortalecê-los como aliados de Judá','Distribuí-los entre os líderes de Judá','Ignorá-los completamente no plano divino','A','Ageu 2:22 promete: "derribarei o trono dos reinos, e destruirei a força dos reinos das nações; e derribarei os carros, e os que neles andam".','É parte da revelação final feita diretamente a Zorobabel sobre o futuro das nações.','texto_biblico',392),
('ageu','Ageu',1,'Segundo Ageu 1:15, em que data específica o povo começou efetivamente a trabalhar na reconstrução do templo?','medio','Exatamente um ano após o decreto de Ciro','No primeiro dia do ano novo persa','No dia vinte e quatro do sexto mês, no segundo ano do rei Dario','No último dia do calendário sagrado judaico','C','Ageu 1:15 registra a data precisa: "no dia vinte e quatro do mês sexto, no segundo ano do rei Dario".','Mostra a precisão histórica com que o livro de Ageu registra os eventos.','texto_biblico',393),
('ageu','Ageu',2,'Segundo Ageu 2:1, em que data específica veio a segunda palavra do Senhor por meio de Ageu, registrada no capítulo 2?','medio','No último dia do ano civil','No dia primeiro do primeiro mês','No dia vinte e um do sétimo mês','Exatamente um mês após a primeira mensagem','C','Ageu 2:1 registra: "no sétimo mês, no dia vinte e um do mês, veio a palavra do Senhor pelo profeta Ageu".','É a segunda de quatro mensagens datadas com precisão ao longo do livro.','texto_biblico',394),
('ageu','Ageu',1,'Segundo Ageu 1:9, qual foi a causa espiritual raiz apontada por Deus para toda a frustração econômica sofrida pelo povo?','dificil','A recusa em pagar dízimos aos sacerdotes','A cobrança excessiva de impostos pelo governo persa','Uma invasão militar recente na região','A negligência com a casa de Deus, enquanto cada um cuidava apenas da própria casa','D','Ageu 1:9 aponta a causa: "por causa da minha casa, que está deserta, enquanto correis, cada um, à sua própria casa".','É o diagnóstico espiritual central por trás de toda a crise econômica descrita no capítulo 1.','texto_biblico',395),
('ageu','Ageu',2,'Segundo Ageu 2:12-13, na ilustração feita aos sacerdotes, qual conclusão se tira sobre como a impureza se espalha em comparação à santidade?','dificil','Somente objetos de ouro podem transmitir santidade','A santidade se espalha com a mesma facilidade que a impureza','Nem santidade nem impureza podem ser transmitidas por contato','A impureza se contagia mais facilmente do que a santidade se transmite','D','Ageu 2:12-13 mostra, pela resposta dos sacerdotes, que carne santa não transmite santidade por simples contato indireto, mas algo impuro (por contato com corpo morto) transmite impureza facilmente.','É uma lição usada para mostrar que a impureza espiritual do povo contaminava até suas boas obras e ofertas.','texto_biblico',396),
('ageu','Ageu',2,'Segundo Ageu 2:17, apesar das pragas agrícolas enviadas por Deus (queimadura, ferrugem e saraiva), o que significativamente não aconteceu da parte do povo?','dificil','Não houve ninguém que se voltasse para Deus','O povo se arrependeu imediatamente','As colheitas voltaram a crescer sem esforço','Os sacerdotes intercederam com sucesso imediato','A','Ageu 2:17 lamenta: "e não houve entre vós quem voltasse para mim, diz o Senhor", mostrando a dureza de coração do povo mesmo sob disciplina divina.','Contrasta com a resposta positiva do povo à pregação direta do profeta em 1:12.','texto_biblico',397),
('ageu','Ageu',2,'Segundo Ageu 2:6-7, que título messiânico é dado à figura esperada que viria e por meio de quem a casa seria enchida de glória?','dificil','"O Príncipe da Babilônia"','"O Rei dos Persas"','"O Redentor de Jerusalém" apenas','"O Desejado de todas as nações"','D','Ageu 2:7 declara: "e virá o Desejado de todas as nações; e encherei esta casa de glória, diz o Senhor dos Exércitos".','É um dos textos messiânicos mais discutidos entre os profetas menores.','texto_biblico',398),
('ageu','Ageu',2,'Segundo Ageu 2:23, com que reversão simbólica de uma maldição real anterior (contra o rei Joaquim, em Jeremias 22:24) a promessa a Zorobabel pode ser associada?','dificil','A criação de um novo templo em outra cidade','A restauração imediata da monarquia independente de Judá','A anulação total da profecia de Jeremias sobre o exílio','A reversão da rejeição do "anel de selar" sobre a linhagem davídica','D','Em Jeremias 22:24, Deus rejeita Joaquim como "anel de selar" que seria arrancado; em Ageu 2:23, Zorobabel, da mesma linhagem, é declarado como o novo "anel de selar" escolhido por Deus.','É uma conexão profética sutil que mostra a restauração da esperança messiânica através da linhagem davídica.','texto_biblico',399),
('ageu','Ageu',1,'Segundo Ageu 1:5 e 1:7, que mandamento idêntico é repetido duas vezes no capítulo 1, funcionando como chamado central à reflexão do povo?','dificil','"Multiplicai vossas ofertas"','"Considerai os vossos caminhos"','"Abandonai vossas casas"','"Escolhei um novo rei"','B','Ageu 1:5 e 1:7 repetem exatamente a mesma ordem: "Assim diz o Senhor dos Exércitos: Considerai os vossos caminhos".','A repetição reforça a importância de uma autoavaliação honesta das prioridades do povo.','texto_biblico',400),
('zacarias','Zacarias',1,'Qual era a principal mensagem inicial de Zacarias 1:3?','facil','Fugi para o Egito','Voltai para mim, e eu me voltarei para vós','Escolham outro rei','Não construam o templo','B','Zacarias 1:3 chama o povo a retornar ao Senhor e promete que o Senhor se voltará para eles.','É um chamado ao retorno.','texto_biblico',401),
('zacarias','Zacarias',5,'O que Zacarias vê em uma das visões do capítulo 5?','facil','Um peixe gigante','Uma arca de Noé','Uma coroa de ferro','Um rolo voante','D','Zacarias 5:1 descreve um rolo voante.','É uma visão escrita e voadora.','texto_biblico',402),
('zacarias','Zacarias',4,'Na visão do capítulo 4, o que representa o azeite em relação às duas oliveiras?','medio','A riqueza do rei','A força militar','A água do templo','A provisão do Espírito de Deus','D','Zacarias 4 enfatiza a ação do Espírito: não por força nem por poder, mas pelo Espírito do Senhor.','O verso 6 fornece a chave da visão.','texto_biblico',403),
('zacarias','Zacarias',9,'Qual rei é descrito chegando a Jerusalém montado em um jumento?','medio','O rei da Assíria','Um rei justo e salvador','O faraó do Egito','Nabucodonosor','B','Zacarias 9:9 descreve um rei justo, salvador e humilde, montado em jumento.','A descrição é de um rei humilde.','texto_biblico',404),
('zacarias','Zacarias',12,'Qual expressão aparece em Zacarias 12:10 sobre o futuro arrependimento?','dificil','Jerusalém será abandonada para sempre','Israel será levado ao Egito','Olharão para aquele a quem traspassaram e prantearão','Não haverá arrependimento','C','Zacarias 12:10 descreve derramamento de espírito de graça e súplicas, seguido de lamento ao olhar para aquele que foi traspassado.','É uma passagem de lamento e arrependimento.','texto_biblico',405),
('zacarias','Zacarias',3,'Na visão de Zacarias 3, quem acusa o sumo sacerdote Josué diante do anjo do Senhor?','facil','O rei da Babilônia','Satanás','Um sacerdote rival','Um profeta falso','B','Zacarias 3:1 descreve Satanás à direita de Josué, o sumo sacerdote, para acusá-lo, mas o Senhor o repreende.','É o acusador por excelência nas Escrituras.','texto_biblico',406),
('zacarias','Zacarias',6,'O que Zacarias vê saindo dentre dois montes de bronze na visão do capítulo 6?','facil','Uma nuvem de fogo apenas','Um exército de anjos armados','Quatro carros puxados por cavalos','Uma frota de navios','C','Zacarias 6:1-8 descreve quatro carros com cavalos de cores diferentes, representando os quatro espíritos dos céus.','São veículos puxados por cavalos de cores distintas.','texto_biblico',407),
('zacarias','Zacarias',8,'Segundo Zacarias 8:23, o que dez homens de todas as línguas farão a um judeu?','medio','Tomarão pela orla de sua veste, dizendo que irão com ele','Pedirão para adorar outros deuses','Ignorarão completamente','Expulsarão da cidade','A','Zacarias 8:23 anuncia que nações desejarão acompanhar o povo judeu, pois reconhecerão que Deus está com eles.','Envolve reconhecimento da presença de Deus com o povo.','texto_biblico',408),
('zacarias','Zacarias',11,'Por quantas moedas de prata o pastor (representando o Senhor) foi avaliado em Zacarias 11:12?','medio','Trinta','Cem','Mil','Dez','A','Zacarias 11:12-13 menciona trinta moedas de prata, valor depois associado à traição de Judas contra Jesus.','É o mesmo valor pago pela traição de Judas no Novo Testamento.','texto_biblico',409),
('zacarias','Zacarias',14,'Em Zacarias 14:4, onde os pés do Senhor se firmarão, fazendo o monte se fender em duas partes?','dificil','Monte Sinai','Monte Carmelo','Monte Nebo','Monte das Oliveiras','D','Zacarias 14:4 descreve os pés do Senhor firmados no monte das Oliveiras, que se fenderá ao meio no dia do Senhor.','É o monte a leste de Jerusalém.','texto_biblico',410),
('zacarias','Zacarias',1,'Segundo Zacarias 1:1, quem era o pai de Zacarias, o profeta?','facil','Amoz','Berequias, filho de Ido','Buzi','Hilquias','B','Zacarias 1:1 identifica o profeta como "Zacarias, filho de Berequias, filho de Ido, o profeta".','É a genealogia usada para identificar o profeta logo na abertura do livro.','texto_biblico',411),
('zacarias','Zacarias',1,'Na visão dos cavaleiros entre as murtas (Zacarias 1:8), de que cor era o cavalo do primeiro cavaleiro?','facil','Vermelho','Branco','Preto','Verde','A','Zacarias 1:8 descreve: "Vi de noite, e eis um homem montado num cavalo vermelho... e atrás dele havia cavalos vermelhos, ruivos e brancos".','É a primeira das oito visões noturnas recebidas por Zacarias.','texto_biblico',412),
('zacarias','Zacarias',1,'Segundo Zacarias 1:12, o que o anjo do Senhor pergunta a Deus a respeito de Jerusalém?','facil','Até quando não terá piedade dela','Quando ela será destruída de vez','Por que ela nunca foi construída','Quando os inimigos a atacarão novamente','A','Zacarias 1:12 registra a intercessão: "Senhor dos Exércitos, até quando não terás piedade de Jerusalém... contra as quais estiveste indignado estes setenta anos?".','É uma súplica de misericórdia feita pelo próprio anjo em favor do povo.','texto_biblico',413),
('zacarias','Zacarias',1,'Na visão dos quatro chifres e dos quatro carpinteiros (Zacarias 1:18-21), o que os chifres representam?','facil','Reis fiéis que protegeram o povo','As nações que espalharam Judá, Israel e Jerusalém','Anjos guardiões do templo','Instrumentos usados no culto do templo','B','Zacarias 1:19 explica que os chifres "são os que espalharam a Judá, a Israel e a Jerusalém".','Os carpinteiros da visão vêm para derrubar esses chifres opressores.','texto_biblico',414),
('zacarias','Zacarias',2,'O que o homem visto por Zacarias segura na mão, no início do capítulo 2?','facil','Uma vara de pastor','Uma espada reluzente','Um pergaminho selado','Um cordel de medir','D','Zacarias 2:1 relata: "Levantei outra vez os meus olhos, e olhei, e eis um homem que trazia na mão um cordel de medir", indo medir Jerusalém.','Simboliza o plano de reconstrução e expansão futura da cidade.','texto_biblico',415),
('zacarias','Zacarias',2,'Segundo Zacarias 2:5, o que o Senhor promete ser para Jerusalém, ao redor dela?','facil','Um exército permanente de anjos','Uma muralha de pedra reforçada','Um muro de fogo','Uma nuvem protetora visível','C','Zacarias 2:5 promete: "Eu serei para ela, diz o Senhor, um muro de fogo em redor, e para glória estarei no meio dela".','É uma imagem de proteção divina superior a qualquer muralha humana.','texto_biblico',416),
('zacarias','Zacarias',2,'Segundo Zacarias 2:8, como Deus descreve simbolicamente quem toca o seu povo?','facil','Toca uma pedra sem valor','Toca a menina do seu olho','Toca apenas um estranho distante','Toca algo sem nenhuma consequência','B','Zacarias 2:8 declara: "quem vos tocar, toca a menina do seu olho", mostrando o quanto Deus valoriza e protege seu povo.','É uma expressão de proteção extremamente pessoal e sensível.','texto_biblico',417),
('zacarias','Zacarias',3,'Segundo Zacarias 3:4, o que é feito com as vestes sujas de Josué, o sumo sacerdote, na visão?','facil','São queimadas publicamente como julgamento','São lavadas e devolvidas a ele','Permanecem sujas como sinal de humildade','São tiradas dele e substituídas por vestes de festa','D','Zacarias 3:4 relata a ordem do anjo: "Tirai-lhe as vestes sujas... eis que tenho feito passar de ti a tua iniquidade, e te vestirei de vestes de festa".','É um símbolo de purificação e restauração do sacerdócio.','texto_biblico',418),
('zacarias','Zacarias',4,'Segundo Zacarias 4:6, por qual meio a grande obra seria realizada, e não por força nem violência humana?','facil','Pelo Espírito do Senhor','Por um exército numeroso','Por riquezas acumuladas','Por alianças políticas estrangeiras','A','Zacarias 4:6 declara a célebre frase: "Não por força nem por violência, mas pelo meu Espírito, diz o Senhor dos Exércitos".','É um dos versículos mais citados de todo o livro de Zacarias.','texto_biblico',419),
('zacarias','Zacarias',6,'Segundo Zacarias 6:11, o que é colocado sobre a cabeça de Josué, o sumo sacerdote, nessa visão?','facil','Uma faixa de linho simples','Um véu de luto','Coroas','Nada, ele permanece de cabeça descoberta','C','Zacarias 6:11 ordena: "Toma, pois, prata e ouro, e faze coroas, e põe-nas na cabeça de Josué".','É um ato simbólico ligado à promessa do "Renovo" que viria a edificar o templo.','texto_biblico',420),
('zacarias','Zacarias',8,'Segundo Zacarias 8:4-5, que cena pacífica de restauração é descrita nas ruas de Jerusalém?','facil','Velhos e velhas sentados, e meninos e meninas brincando nas ruas','Soldados marchando em formação constante','Mercadores discutindo preços em voz alta','Sacerdotes realizando sacrifícios contínuos','A','Zacarias 8:4-5 descreve: "ainda hão de habitar velhos e velhas nas ruas de Jerusalém... e as ruas da cidade se encherão de meninos e meninas brincando nelas".','É uma das imagens mais ternas de paz e normalidade restaurada em toda a Bíblia.','texto_biblico',421),
('zacarias','Zacarias',9,'Segundo Zacarias 9:11, pelo que o Senhor promete tirar os presos da cova?','facil','Por uma guerra vitoriosa','Por um resgate pago em prata','Por um decreto de um rei estrangeiro','Pelo sangue do seu concerto (aliança)','D','Zacarias 9:11 declara: "Ainda quanto a ti, pelo sangue do teu concerto, tirei os teus presos da cova em que não havia água".','Liga a libertação do povo diretamente à aliança feita por meio de sangue.','texto_biblico',422),
('zacarias','Zacarias',1,'Segundo Zacarias 1:15, por que Deus está irado contra as nações que estavam "sossegadas" quando afligiam seu povo?','medio','Porque elas nunca conheceram a lei de Moisés','Porque elas se recusaram a pagar tributo a Deus','Porque, embora Deus estivesse só um pouco irado, elas agravaram o mal','Porque elas destruíram templos de outros deuses','C','Zacarias 1:15 explica: "E estou mui indignado contra as nações que estão sossegadas; porque eu estava só um pouco indignado, mas elas agravaram o mal".','Mostra que o castigo excessivo aplicado por essas nações ultrapassou o propósito original de Deus.','texto_biblico',423),
('zacarias','Zacarias',1,'Segundo Zacarias 1:16-17, o que Deus promete quanto à sua casa e às suas cidades ao voltar com misericórdia a Jerusalém?','medio','Sua casa será edificada nela, e suas cidades transbordarão de bem','Sua casa permanecerá em ruínas por mais setenta anos','Nenhuma cidade será reconstruída novamente','O povo será disperso ainda mais entre as nações','A','Zacarias 1:16-17 promete: "voltarei a Jerusalém com misericórdias; a minha casa se edificará nela... ainda hão de transbordar as minhas cidades de bem".','É a resposta positiva de Deus à intercessão do anjo por Jerusalém.','texto_biblico',424),
('zacarias','Zacarias',2,'Segundo Zacarias 2:11, o que acontecerá com muitas nações "naquele dia", segundo essa profecia?','medio','Serão completamente destruídas sem exceção','Se ajuntarão ao Senhor e se tornarão seu povo','Se tornarão escravas de Jerusalém para sempre','Nunca mais terão contato com Israel','B','Zacarias 2:11 promete: "E muitas nações se ajuntarão ao Senhor naquele dia, e serão o meu povo".','É uma visão de inclusão universal ligada à restauração de Sião.','texto_biblico',425),
('zacarias','Zacarias',3,'Segundo Zacarias 3:8-9, que título é dado ao servo que Deus fará vir, associado a uma pedra com sete olhos?','medio','"O Escolhido de Israel"','"O Conselheiro"','"O Redentor de Sião"','"O Renovo"','D','Zacarias 3:8 anuncia: "farei vir o meu servo, o Renovo", relacionado à pedra com sete olhos mencionada no verso seguinte.','É um título messiânico repetido também no capítulo 6 do livro.','texto_biblico',426),
('zacarias','Zacarias',4,'Segundo Zacarias 4:7, o que o "grande monte" se tornará diante de Zorobabel, segundo a visão?','medio','Um templo ainda maior','Uma campina (planície)','Uma nova capital do reino','Um exército invencível','B','Zacarias 4:7 promete: "Quem és tu, ó grande monte? Diante de Zorobabel serás uma campina; e ele trará a pedra angular com aclamações".','Simboliza a remoção de todos os obstáculos à reconstrução do templo.','texto_biblico',427),
('zacarias','Zacarias',4,'Segundo Zacarias 4:9-10, de quem são as mãos que lançaram e completarão os fundamentos da casa, e o que se afirma sobre desprezar coisas pequenas?','medio','As mãos dos sacerdotes; apenas grandes obras importam','As mãos do rei persa; qualquer início é irrelevante','As mãos de Zorobabel; ninguém deve desprezar o dia das coisas pequenas','As mãos dos anjos; humanos não participam da obra','C','Zacarias 4:9-10 declara: "as mãos de Zorobabel têm lançado os fundamentos desta casa; também as suas mãos a acabarão... Quem despreza o dia das coisas pequenas?".','É um encorajamento a valorizar os pequenos começos de uma grande obra.','texto_biblico',428),
('zacarias','Zacarias',6,'Segundo Zacarias 6:12-13, o que o "Renovo" fará, exercendo simultaneamente duas funções distintas?','medio','Edificará o templo do Senhor e será sacerdote sobre o seu trono','Será apenas rei, sem função sacerdotal','Será apenas sacerdote, sem função real','Destruirá o templo para reconstruí-lo depois','A','Zacarias 6:12-13 profetiza: "ele mesmo edificará o templo do Senhor... e será sacerdote sobre o seu trono; e o conselho de paz haverá entre ambos os ofícios".','Antecipa a união entre realeza e sacerdócio numa só figura messiânica.','texto_biblico',429),
('zacarias','Zacarias',7,'Segundo Zacarias 7:9-10, que tipo de justiça social Deus exige explicitamente do seu povo?','medio','Apenas o pagamento pontual de impostos ao templo','Apenas o cumprimento rigoroso dos jejuns anuais','Juízo verdadeiro, misericórdia, e não oprimir viúva, órfão, estrangeiro e pobre','Apenas a participação em festas religiosas específicas','C','Zacarias 7:9-10 ordena: "executai juízo verdadeiro, e mostrai piedade e compaixão cada um para com seu irmão... não oprimais a viúva, nem o órfão, nem o estrangeiro, nem o pobre".','É uma exigência ética que vai além do simples ritualismo religioso.','texto_biblico',430),
('zacarias','Zacarias',7,'Segundo Zacarias 7:11-12, como o povo reagiu historicamente aos apelos anteriores de Deus por meio dos profetas?','medio','Enviaram representantes para negociar condições','Obedeceram imediatamente sem hesitação','Pediram mais tempo para refletir com calma','Recusaram ouvir e endureceram o coração como diamante','D','Zacarias 7:11-12 relata: "eles recusaram escutar, e retiraram o ombro, e agravaram os seus ouvidos, para que não ouvissem. E fizeram o seu coração como diamante".','Explica a razão histórica do exílio como consequência dessa dureza espiritual.','texto_biblico',431),
('zacarias','Zacarias',8,'Segundo Zacarias 8:16-17, que comportamentos éticos específicos Deus pede entre vizinhos na comunidade restaurada?','medio','Apenas participar de todas as festas anuais','Apenas guardar silêncio em disputas comerciais','Apenas pagar dízimos regularmente ao templo','Falar a verdade, executar juízo de paz, e não amar falso juramento','D','Zacarias 8:16-17 ordena: "falai a verdade cada um com o seu próximo; executai juízo de verdade e de paz nas vossas portas... e não ameis o falso juramento".','Reforça que a verdadeira adoração inclui integridade nas relações cotidianas.','texto_biblico',432),
('zacarias','Zacarias',10,'Segundo Zacarias 10:2, por que o povo estava sendo enganado, segundo essa passagem?','medio','Porque os sacerdotes cobravam impostos excessivos','Porque os terafins falavam vaidade e os adivinhos viam mentira','Porque não havia mais profetas verdadeiros disponíveis','Porque as leis de Moisés haviam sido perdidas','B','Zacarias 10:2 denuncia: "Porque os terafins falam a vaidade, e os adivinhos veem a mentira, e contam sonhos falsos; consolam com vaidade".','É uma crítica às práticas de idolatria e adivinhação ainda presentes no povo.','texto_biblico',433),
('zacarias','Zacarias',11,'Segundo Zacarias 11:7, quais nomes o pastor dá aos dois cajados usados na visão simbólica?','medio','Justiça e Misericórdia','Suavidade e Ataduras','Graça e Verdade','Aliança e Redenção','B','Zacarias 11:7 relata: "tomei para mim dois cajados: a um chamei Suavidade, e ao outro chamei Ataduras; e apascentei as ovelhas".','Esses cajados são posteriormente quebrados como sinais simbólicos de julgamento.','texto_biblico',434),
('zacarias','Zacarias',5,'Segundo Zacarias 5:6-8, o que a mulher sentada dentro do efa (uma medida de grãos) representa na visão?','dificil','A impiedade (a maldade)','A prosperidade futura de Jerusalém','A sabedoria divina personificada','A fidelidade do remanescente fiel','A','Zacarias 5:7-8 revela: "esta é a impiedade... e ele a lançou dentro do efa, e lançou o peso de chumbo na boca dele".','É uma das visões mais simbólicas e enigmáticas do livro de Zacarias.','texto_biblico',435),
('zacarias','Zacarias',8,'Segundo Zacarias 8:19, o que os antigos jejuns de lamentação (do quarto, quinto, sétimo e décimo mês) se tornarão para a casa de Judá?','dificil','Em feriados exclusivamente sacerdotais','Em jejuns ainda mais rigorosos','Em dias de guerra memorial','Em gozo, alegria e festividades alegres','D','Zacarias 8:19 promete: "o jejum do quarto mês, e o jejum do quinto... se tornarão para a casa de Judá em gozo, e em alegria, e em festas alegres".','Marca a transformação do luto histórico do exílio em celebração futura.','texto_biblico',436),
('zacarias','Zacarias',11,'Segundo Zacarias 11:10 e 11:14, o que a quebra dos dois cajados (Suavidade e Ataduras) simboliza, respectivamente?','dificil','A união definitiva de todas as nações vizinhas','O rompimento da aliança com os povos, e o fim da fraternidade entre Judá e Israel','A construção de dois novos templos','A coroação simultânea de dois reis diferentes','B','Zacarias 11:10 relata a quebra de Suavidade "desfazendo a aliança que tinha feito com todos os povos", e 11:14 a quebra de Ataduras "para romper a fraternidade entre Judá e Israel".','É um ato profético duplo que anuncia ruptura tanto externa quanto interna.','texto_biblico',437),
('zacarias','Zacarias',13,'Segundo Zacarias 13:7, o que acontece ao pastor e às ovelhas nessa profecia de ferimento?','dificil','O pastor abandona voluntariamente o rebanho','O pastor se torna rei sobre as ovelhas','As ovelhas defendem o pastor com sucesso','A espada fere o pastor, e as ovelhas se dispersam','D','Zacarias 13:7 profetiza: "Levanta-te, espada, contra o meu pastor, e contra o varão que é meu companheiro... fere o pastor, e espalhar-se-ão as ovelhas".','Este versículo é citado por Jesus em Mateus 26:31 referindo-se a si mesmo.','texto_biblico',438),
('zacarias','Zacarias',13,'Segundo Zacarias 13:8-9, que proporção do povo passará pelo processo de purificação como se purifica a prata pelo fogo?','dificil','Duas partes serão exterminadas, e a terceira parte será refinada','Metade será poupada e metade destruída igualmente','Toda a nação será exterminada sem exceção','Apenas os líderes passarão por esse processo','A','Zacarias 13:8-9 anuncia: "nas duas partes dela será extirpada, e expirará; mas a terceira parte restará nela. E porei esta terceira parte no fogo, e a purificarei como se purifica a prata".','É uma imagem de julgamento seletivo seguido de purificação de um remanescente fiel.','texto_biblico',439),
('zacarias','Zacarias',14,'Segundo Zacarias 14:9, o que se afirma especificamente sobre o reinado e o nome do Senhor "naquele dia"?','dificil','O Senhor será rei sobre toda a terra; um será o Senhor, e um o seu nome','O Senhor dividirá seu reinado entre várias nações','Cada nação terá seu próprio deus reconhecido oficialmente','O nome do Senhor permanecerá desconhecido entre as nações','A','Zacarias 14:9 declara: "E o Senhor será rei sobre toda a terra; naquele dia um será o Senhor, e um será o seu nome".','É uma das declarações mais explícitas de monoteísmo universal futuro em todo o Antigo Testamento.','texto_biblico',440),
('malaquias','Malaquias',1,'Qual é a primeira pergunta de contestação registrada no diálogo de Malaquias?','facil','Quem é o rei?','Quando virá Elias?','Onde está Moisés?','Em que nos amaste?','D','Malaquias 1:2 registra a pergunta do povo: em que nos amaste?','Ela vem logo após Deus declarar seu amor por Jacó.','texto_biblico',441),
('malaquias','Malaquias',3,'Quem é prometido como mensageiro antes da chegada do Senhor?','facil','Um general romano','Um mensageiro que prepararia o caminho','Um novo rei assírio','Um sacerdote de Samaria','B','Malaquias 3:1 fala do mensageiro que preparará o caminho diante do Senhor.','A palavra-chave é mensageiro.','texto_biblico',442),
('malaquias','Malaquias',3,'O que Malaquias 3:10 relaciona ao dízimo?','medio','Trazer todos os dízimos à casa do tesouro','Usar o dízimo para guerra','Entregar somente ao rei','Guardar o dízimo em casa','A','Malaquias 3:10 chama a trazer todos os dízimos à casa do tesouro e apresenta a promessa de provisão.','A expressão é casa do tesouro.','texto_biblico',443),
('malaquias','Malaquias',4,'O que o final do livro de Malaquias promete enviar antes do grande e terrível dia do Senhor?','medio','Jeremias','Samuel','Elias, o profeta','Natã','C','Malaquias 4:5 promete enviar Elias, o profeta, antes do grande e terrível dia do Senhor.','É o último nome mencionado no livro.','texto_biblico',444),
('malaquias','Malaquias',2,'Qual problema dos sacerdotes é denunciado em Malaquias 2?','dificil','Desprezavam o nome de Deus e ofereciam sacrifícios inadequados','Não conheciam a Lei de Moisés','Construíam muitos altares','Recusavam-se a trabalhar no templo','A','Malaquias 1–2 denuncia sacerdotes que desprezavam o nome de Deus e aceitavam animais inadequados para sacrifício.','A denúncia envolve a qualidade das ofertas.','texto_biblico',445),
('malaquias','Malaquias',1,'Que tipo de animais o povo oferecia indevidamente em sacrifício, segundo Malaquias 1:8?','facil','Apenas aves selvagens','Cegos, coxos e enfermos','Peixes do rio Jordão','Somente animais gordos e perfeitos','B','Malaquias 1:8 repreende o povo por oferecer animais cegos, coxos e enfermos, desonrando a Deus.','São animais com defeitos físicos.','texto_biblico',446),
('malaquias','Malaquias',2,'O que Malaquias 2:16 diz que o Senhor aborrece?','facil','As orações longas','Os dízimos','Os sacrifícios de louvor','O repúdio (divórcio)','D','Malaquias 2:16 declara que o Senhor Deus de Israel aborrece o repúdio, condenando a infidelidade conjugal.','É relacionado à quebra do casamento.','texto_biblico',447),
('malaquias','Malaquias',3,'O que Malaquias 3:6 afirma sobre o caráter de Deus que garante que Israel não foi consumido?','medio','Eu esqueço facilmente','Eu mudo conforme as nações','Eu abandono meu povo','Eu, o Senhor, não mudo','D','Malaquias 3:6 afirma a imutabilidade de Deus como razão pela qual os filhos de Jacó não foram consumidos.','É uma afirmação sobre a constância do caráter divino.','texto_biblico',448),
('malaquias','Malaquias',3,'De que forma Malaquias 3:8 diz que o povo estava roubando a Deus?','medio','Nos sacrifícios de animais','Nas orações públicas','Nos dízimos e nas ofertas','Na construção do templo','C','Malaquias 3:8 acusa o povo de roubar a Deus retendo dízimos e ofertas.','Está ligado à contribuição financeira ao templo.','texto_biblico',449),
('malaquias','Malaquias',2,'Qual argumento de unidade Malaquias 2:10 usa para repreender a traição entre irmãos?','dificil','Não somos todos sacerdotes?','Não temos todos um mesmo Pai e um mesmo Criador?','Não vivemos todos no Egito?','Não somos todos reis?','B','Malaquias 2:10 apela à paternidade comum de Deus para denunciar a deslealdade entre os israelitas, quebrando a aliança dos pais.','É um apelo à origem e criação comuns.','texto_biblico',450),
('malaquias','Malaquias',1,'Segundo Malaquias 1:3, o que Deus diz ter feito com os montes de Esaú?','facil','Cobriu-os de bênçãos abundantes','Fez deles assolação, morada de chacais','Entregou-os a Israel como herança','Não fez nenhuma menção a eles','B','Malaquias 1:3 declara: "e aborreci a Esaú, e fiz dos seus montes uma assolação, e dei a sua herança aos chacais do deserto".','Contrasta com o amor eletivo declarado por Deus a Jacó no versículo anterior.','texto_biblico',451),
('malaquias','Malaquias',1,'Segundo Malaquias 1:6, que comparação Deus faz para lembrar o povo da honra e do temor que lhe são devidos?','facil','O cidadão teme apenas as leis civis','O irmão obedece ao irmão mais velho','O aluno respeita apenas seus colegas','O filho honra o pai, e o servo teme o seu senhor','D','Malaquias 1:6 questiona: "O filho honra a seu pai, e o servo a seu senhor; se eu sou pai, onde está a minha honra? E se eu sou senhor, onde está o meu temor?".','É a introdução da acusação contra os sacerdotes desrespeitosos.','texto_biblico',452),
('malaquias','Malaquias',1,'Segundo Malaquias 1:7, do que os sacerdotes são acusados de trazer ao altar do Senhor?','facil','Água impura para libações','Ouro puro em excesso','Pão contaminado','Incenso de má qualidade apenas','C','Malaquias 1:7 denuncia: "vós trazeis pão contaminado sobre o meu altar; e dizeis: Em que te havemos profanado?".','É o início da acusação sobre negligência no culto sacerdotal.','texto_biblico',453),
('malaquias','Malaquias',1,'Segundo Malaquias 1:10, o que Deus declara não mais aceitar da mão do povo?','facil','Qualquer tipo de dízimo em prata','Um culto vazio e sem agrado, oferecido sem sinceridade','Sacrifícios de animais jovens e saudáveis','Orações feitas em público','B','Malaquias 1:10 declara: "não me agrado de vós, diz o Senhor dos Exércitos, nem aceitarei oferta da vossa mão".','Mostra a rejeição divina de um culto puramente formal e desonesto.','texto_biblico',454),
('malaquias','Malaquias',1,'Segundo Malaquias 1:11, entre quem o nome do Senhor é declarado como grande, mesmo fora de Israel?','facil','Somente entre os descendentes de Levi','Apenas entre os reis estrangeiros','Entre os gentios, desde o nascente até o poente do sol','Exclusivamente dentro do templo de Jerusalém','C','Malaquias 1:11 declara: "desde o nascente do sol até ao poente, é grande o meu nome entre os gentios... porque grande é o meu nome entre os gentios".','É uma afirmação surpreendente sobre a extensão universal do reconhecimento do nome de Deus.','texto_biblico',455),
('malaquias','Malaquias',2,'Segundo Malaquias 2:5, com qual tribo/pessoa Deus fez uma aliança de vida e paz?','facil','Com Efraim','Com Judá','Com Benjamim','Com Levi','D','Malaquias 2:5 declara: "Minha aliança com ele era de vida e paz, e eu lhas dei para que me temesse; e ele me temeu, e assombrou-se diante do meu nome".','Refere-se à aliança sacerdotal original feita com a tribo de Levi.','texto_biblico',456),
('malaquias','Malaquias',2,'Segundo Malaquias 2:7, qual deveria ser a principal função do sacerdote fiel, segundo essa passagem?','facil','Governar politicamente sobre o povo','Apenas realizar sacrifícios sem instruir o povo','Cobrar impostos em nome do templo','Guardar o conhecimento e ser mensageiro do Senhor dos Exércitos','D','Malaquias 2:7 declara: "os lábios do sacerdote guardarão o conhecimento, e da sua boca buscarão a lei; porque ele é o mensageiro do Senhor dos Exércitos".','Define o papel ideal do sacerdócio como fonte de instrução espiritual.','texto_biblico',457),
('malaquias','Malaquias',2,'Segundo Malaquias 2:14, como a esposa da juventude de um homem é chamada nessa passagem sobre fidelidade conjugal?','facil','"Serva contratada"','"Companheira" e "mulher do teu concerto"','"Estrangeira sem direitos"','"Propriedade do marido"','B','Malaquias 2:14 declara que o Senhor foi testemunha entre o homem e "a mulher da tua mocidade, contra a qual tens sido desleal, sendo ela a tua companheira, e a mulher do teu concerto".','Eleva o casamento ao nível de uma aliança sagrada testemunhada por Deus.','texto_biblico',458),
('malaquias','Malaquias',3,'Segundo Malaquias 3:2, a que Deus compara o processo de purificação que fará entre os sacerdotes?','facil','A uma nova festa anual instituída','A uma simples lavagem com água comum','A um jejum prolongado sem outra ação','Ao fogo do fundidor e ao sabão dos lavandeiros','D','Malaquias 3:2 pergunta: "quem suportará o dia da sua vinda?... porque ele será como o fogo do fundidor, e como o sabão dos lavandeiros".','É uma imagem intensa de purificação profunda e dolorosa.','texto_biblico',459),
('malaquias','Malaquias',3,'Segundo Malaquias 3:5, contra quais grupos específicos Deus promete ser uma testemunha veloz no juízo?','facil','Feiticeiros, adúlteros, os que juram falsamente e os que exploram os mais vulneráveis','Apenas comerciantes desonestos','Somente reis estrangeiros injustos','Exclusivamente sacerdotes corruptos','A','Malaquias 3:5 lista: "contra os feiticeiros, e contra os adúlteros, e contra os que juram falsamente, e contra os que defraudam o jornaleiro no seu salário, a viúva, e o órfão".','É uma lista abrangente de injustiças sociais e morais que Deus promete julgar.','texto_biblico',460),
('malaquias','Malaquias',3,'Segundo Malaquias 3:16, o que é registrado para os que temem ao Senhor e se lembram do seu nome?','facil','Nenhum registro específico é mencionado','Uma nova lei escrita em pedra','Uma lista pública de méritos no templo','Um livro de memória','D','Malaquias 3:16 relata: "então aqueles que temem ao Senhor falaram, cada um com o seu companheiro... e um livro de memória foi escrito diante dele".','É uma imagem de que Deus registra fielmente a devoção dos seus servos.','texto_biblico',461),
('malaquias','Malaquias',4,'Segundo Malaquias 4:2, o que nascerá para aqueles que temem o nome do Senhor?','facil','Um exército de anjos protetores','Uma nova lei mais rigorosa','O sol da justiça, com saúde debaixo das suas asas','Um novo templo em outra cidade','C','Malaquias 4:2 promete: "mas para vós, os que temeis o meu nome, nascerá o sol da justiça, e a saúde estará debaixo das suas asas".','É uma das imagens mais luminosas de esperança em todo o livro.','texto_biblico',462),
('malaquias','Malaquias',1,'Segundo Malaquias 1:9, o que Deus questiona ironicamente sobre suplicar seu favor após ofertas desonestas terem sido feitas?','medio','Se o povo merece um novo templo','Se ele aceitará as pessoas mesmo assim, apesar de tais ofertas','Se os sacerdotes devem ser substituídos imediatamente','Se as ofertas devem ser dobradas em quantidade','B','Malaquias 1:9 questiona: "Agora, pois, suplicai o favor de Deus, para que se compadeça de nós... Aceitará ele as vossas pessoas? diz o Senhor dos Exércitos".','É uma pergunta retórica que expõe a hipocrisia de buscar bênção após oferecer sacrifícios desprezíveis.','texto_biblico',463),
('malaquias','Malaquias',1,'Segundo Malaquias 1:13, que atitude de desprezo o povo demonstra ao dizer "que canseira!" sobre o culto a Deus?','medio','Demonstram grande zelo e entusiasmo pelo culto','Tratam o serviço a Deus como um fardo cansativo e desagradável','Pedem mais tempo de descanso entre os sacrifícios','Reclamam apenas da distância até o templo','B','Malaquias 1:13 relata: "dizeis também: Eis aqui, que canseira! E o lançastes ao desprezo, diz o Senhor dos Exércitos".','Revela o tédio espiritual e a falta de reverência no culto oferecido pelo povo.','texto_biblico',464),
('malaquias','Malaquias',1,'Segundo Malaquias 1:14, que maldição é pronunciada sobre quem possui um bom animal, mas oferece a Deus um animal com mácula?','medio','"Maldito o enganador"','"Bendito seja o que economiza"','"Perdoado será quem oferece pouco"','"Recompensado será o cauteloso"','A','Malaquias 1:14 declara: "maldito o enganador que, tendo animal no seu rebanho, promete, e sacrifica ao Senhor o que tem mácula".','Reforça a seriedade de oferecer a Deus o melhor, não o descartável.','texto_biblico',465),
('malaquias','Malaquias',2,'Segundo Malaquias 2:2, o que Deus promete fazer com as bênçãos dos sacerdotes, caso eles não ouçam sua advertência?','medio','Amaldiçoá-las','Multiplicá-las ainda mais','Ignorá-las completamente sem consequência','Transferi-las a outra tribo imediatamente','A','Malaquias 2:2 adverte: "se não ouvirdes, e se não propuserdes no coração dar honra ao meu nome... enviarei a maldição sobre vós, e amaldiçoarei as vossas bênçãos".','É uma advertência severa contra a desonra sacerdotal ao nome de Deus.','texto_biblico',466),
('malaquias','Malaquias',2,'Segundo Malaquias 2:6, que qualidades caracterizavam o sacerdócio fiel e original representado por Levi?','medio','Lei da verdade em sua boca, sem iniquidade, andando em paz e retidão','Riqueza acumulada e poder político','Alianças frequentes com nações estrangeiras','Isenção total de qualquer responsabilidade moral','A','Malaquias 2:6 descreve: "a lei da verdade esteve na sua boca, e não se achou iniquidade nos seus lábios; andou comigo em paz e retidão, e converteu a muitos da iniquidade".','Serve de contraste ideal para a corrupção denunciada nos sacerdotes da época de Malaquias.','texto_biblico',467),
('malaquias','Malaquias',2,'Segundo Malaquias 2:8-9, qual foi a consequência da corrupção espiritual dos sacerdotes de seus dias?','medio','Deus lhes concedeu riquezas adicionais','Deus os promoveu a cargos ainda mais altos','Deus os fez desprezíveis e humilhados diante de todo o povo','Nada mudou em sua posição social','C','Malaquias 2:9 declara: "por isso também eu vos fiz desprezíveis, e vis, diante de todo o povo, porquanto não guardastes os meus caminhos".','É a consequência direta anunciada por desviarem-se do caminho e corromperem a aliança de Levi.','texto_biblico',468),
('malaquias','Malaquias',2,'Segundo Malaquias 2:11, que aliança específica Judá é acusado de profanar, ligada a uma prática de casamento?','medio','Adiar casamentos por motivos religiosos','Recusar-se a pagar dote adequado','Realizar casamentos apenas dentro da própria tribo','Casar-se com filha de deus estranho, profanando a santidade do Senhor','D','Malaquias 2:11 denuncia: "Judá profanou a santidade do Senhor, a qual ele amava, e se casou com a filha de deus estranho".','É uma das acusações centrais do capítulo 2 contra a infidelidade espiritual e conjugal do povo.','texto_biblico',469),
('malaquias','Malaquias',2,'Segundo Malaquias 2:13, como o povo reage emocionalmente ao perceber que suas ofertas não são mais aceitas por Deus?','medio','Cobrem o altar do Senhor de lágrimas, choro e gemido','Celebram com festas ainda maiores','Permanecem completamente indiferentes','Culpam publicamente os sacerdotes por tudo','A','Malaquias 2:13 descreve: "cobris o altar do Senhor de lágrimas, de choro e de gemido, porque ele não olha mais para a oferta, nem a aceita com prazer de vossa mão".','Mostra o desespero do povo ao perceber a rejeição divina, ainda sem entender a causa espiritual.','texto_biblico',470),
('malaquias','Malaquias',2,'Segundo Malaquias 2:15, qual propósito divino é mencionado por trás da união de um homem e uma mulher em uma só carne?','medio','Nenhum propósito específico é mencionado','Apenas garantir herança de propriedades','Fortalecer alianças políticas entre famílias','Buscar uma descendência piedosa (de Deus)','D','Malaquias 2:15 explica: "E não fez ele somente um, ainda que lhe sobejava o espírito? E por que somente um? Ele buscava uma descendência de Deus".','Fundamenta teologicamente a seriedade da fidelidade conjugal discutida no capítulo.','texto_biblico',471),
('malaquias','Malaquias',3,'Segundo Malaquias 3:3, com que propósito Deus purificará os filhos de Levi como se purifica ouro e prata?','medio','Para que abandonem completamente o sacerdócio','Para que se tornem ricos e influentes','Para que sejam isentos de toda responsabilidade','Para que ofereçam ao Senhor uma oferta em justiça','D','Malaquias 3:3 declara: "purificará os filhos de Levi, e os afinará como ouro e como prata, para que ofereçam ao Senhor uma oferta em justiça".','Liga diretamente o processo de purificação a um propósito de culto restaurado e íntegro.','texto_biblico',472),
('malaquias','Malaquias',3,'Segundo Malaquias 3:7, o que Deus pede que o povo faça, prometendo reciprocidade caso obedeçam?','medio','"Tornai-vos para mim, e eu me tornarei para vós"','"Construam um templo maior antes de tudo"','"Multipliquem seus sacrifícios imediatamente"','"Abandonem completamente a terra de Judá"','A','Malaquias 3:7 declara: "Tornai-vos para mim, e eu me tornarei para vós, diz o Senhor dos Exércitos. Mas vós dizeis: Em que havemos de tornar?".','É um convite ao arrependimento com a promessa explícita de restauração recíproca.','texto_biblico',473),
('malaquias','Malaquias',3,'Segundo Malaquias 3:11, que promessa agrícola específica Deus faz relacionada a repreender "o devorador" por causa da fidelidade do povo?','medio','Não destruirá o fruto da terra, e a vinha não será estéril','Multiplicará instantaneamente todos os rebanhos','Enviará chuva todos os dias do ano','Eliminará totalmente todos os insetos da região','A','Malaquias 3:11 promete: "também por causa de vós repreenderei o devorador, e ele não vos destruirá o fruto da terra; e a vinha no campo não vos será estéril".','É uma continuação da promessa de bênção ligada à fidelidade nos dízimos mencionada no versículo anterior.','texto_biblico',474),
('malaquias','Malaquias',1,'Segundo Malaquias 1:2-3, que contraste entre dois irmãos Deus usa para ilustrar seu amor eletivo e soberano?','dificil','"Amei a Efraim, e rejeitei a Manassés"','"Amei a Jacó, e aborreci a Esaú"','"Escolhi a Levi, e abandonei a Judá"','"Exaltei a Benjamim, e humilhei a Rúben"','B','Malaquias 1:2-3 declara: "Todavia eu amei a Jacó; mas aborreci a Esaú, e fiz dos seus montes uma assolação".','Este texto é posteriormente citado por Paulo em Romanos 9:13 para discutir a soberania eletiva de Deus.','texto_biblico',475),
('malaquias','Malaquias',2,'Segundo Malaquias 2:3, com que linguagem forte e chocante Deus adverte que tratará a "semente" dos sacerdotes desobedientes?','dificil','Multiplicará sua descendência abundantemente','Espalhará esterco sobre seus rostos, o esterco das suas festas','Elevará seus filhos a posições de honra','Nenhuma ação específica é mencionada contra eles','B','Malaquias 2:3 adverte de forma chocante: "eis que vos corromperei a semente, e espalharei esterco sobre os vossos rostos, o esterco das vossas festas; e sereis levados com ele".','É uma das linguagens mais duras e vívidas usadas por Deus contra os sacerdotes corruptos em todo o Antigo Testamento.','texto_biblico',476),
('malaquias','Malaquias',2,'Segundo Malaquias 2:17, de que forma cínica o povo havia cansado (enfadado) o Senhor com suas palavras?','dificil','Recusando-se a falar com os sacerdotes','Dizendo que quem faz o mal é bom aos olhos do Senhor, ou perguntando onde está o Deus do juízo','Pedindo perdão em excesso, de forma insincera','Cantando hinos de lamentação constantemente','B','Malaquias 2:17 relata: "vós tendes enfadado ao Senhor com vossas palavras... dizendo: Qualquer que faz mal é bom aos olhos do Senhor... Ou: Onde está o Deus do juízo?".','Revela um ceticismo moral profundo que antecede a resposta de Deus no capítulo 3.','texto_biblico',477),
('malaquias','Malaquias',3,'Segundo Malaquias 3:15, que visão distorcida sobre os soberbos e ímpios o povo passou a adotar, mesmo diante da impiedade deles?','dificil','Reputavam os soberbos por bem-aventurados, e diziam que os ímpios prosperam e escapam ao tentar a Deus','Reconheciam publicamente que a justiça sempre prevalece rapidamente','Acreditavam que todo pecado era punido instantaneamente','Defendiam que a riqueza sempre vinha da bênção divina direta','A','Malaquias 3:15 relata essa distorção: "reputamos por bem-aventurados os soberbos; também os que cometem impiedade se edificam, e até tentam a Deus e escapam".','Mostra a crise de fé decorrente de ver o aparente sucesso dos ímpios sem punição imediata.','texto_biblico',478),
('malaquias','Malaquias',4,'Segundo Malaquias 4:1, a que os soberbos e praticantes de impiedade são comparados no "dia que vem ardendo como fornalha"?','dificil','À palha, que será totalmente queimada sem deixar raiz nem ramo','A árvores fortes que resistem ao fogo','A pedras que permanecem intactas no calor','A metais preciosos que apenas se purificam','A','Malaquias 4:1 declara: "todos os soberbos, e todos os que cometem impiedade, serão como a palha; e o dia que vem os abrasará... e não lhes deixará nem raiz nem ramo".','É uma imagem de destruição total e definitiva reservada para o julgamento final.','texto_biblico',479),
('malaquias','Malaquias',4,'Segundo Malaquias 4:6, qual é o propósito final declarado da missão de Elias antes do grande e terrível dia do Senhor?','dificil','Substituir permanentemente a função dos sacerdotes levitas','Reconstruir fisicamente o templo de Jerusalém','Unificar politicamente todas as tribos de Israel','Converter o coração dos pais aos filhos e dos filhos aos pais, evitando que a terra seja ferida de maldição','D','Malaquias 4:6 conclui o livro: "ele converterá o coração dos pais aos filhos, e o coração dos filhos a seus pais; para que eu não venha, e fira a terra com maldição".','É o versículo final de todo o Antigo Testamento na ordem tradicional protestante, preparando a expectativa messiânica.','texto_biblico',480)
